	["1. Llega al nivel 40. La montura y la equitación se compran a la vez: junta el oro mientras subes."] = "1. Достигните 40-го уровня. Транспорт и верховая езда покупаются одновременно: копите золото, пока качаетесь.",
	["2. Ve con el instructor de equitación de tu raza y aprende la de aprendiz."] = "2. Сходите к учителю верховой езды своей расы и изучите навык ученика.",
	["3 de XP, 3 de oro, 3 de XP, 20 de tu profesión y 3 de clase para un objeto único."] = "3 на опыт, 3 на золото, 3 на опыт, 20 по вашей профессии и 3 классовых ради уникального предмета.",
	["3. Compra la montura con el vendedor de tu raza (al lado del instructor) y úsala para aprenderla."] = "3. Купите транспорт у торговца своей расы (рядом с учителем) и используйте его, чтобы изучить.",
	["4. A nivel 60, el mismo instructor enseña la de oficial y el vendedor tiene las rápidas."] = "4. На 60-м уровне тот же учитель обучает навыку подмастерья, а у торговца есть быстрый транспорт.",
	["A %s"] = "До %s",
	["A %s le queda poco"] = "Скоро закончится: %s",
	["A Entrañas se baja por elevadores desde las ruinas de la capital de Lordaeron."] = "В Подгород спускаются на подъемниках из руин столицы Лордерона.",
	["A Mis planes"] = "В «Мои планы»",
	["A Ragnaros no le gusta que lo despierten antes de tiempo, y su mayordomo Executus lo paga caro."] = "Рагнарос не любит, когда его будят раньше времени, и его мажордом Экзекутус дорого за это платит.",
	["A Silithus se entra desde el Cráter de Un'Goro."] = "В Силитус попадают из кратера Ун'Горо.",
	["A distancia"] = "Дальний бой",
	["A entregar tus misiones"] = "Сдаем задания",
	["A la entrada de Ventormenta, estatuas de los grandes héroes de la Segunda Guerra reciben a los visitantes."] = "У входа в Штормград гостей встречают статуи великих героев Второй войны.",
	["A la vista: %d de la manada · %d de tu grupo"] = "В поле зрения: из стаи %d · из группы %d",
	["A las demás les dice qué les falta: tu nivel o una misión antes."] = "Для остальных показывает, чего не хватает: уровня или предварительного задания.",
	["A los lados del modelo, un botón por ranura: un clic oculta esa pieza y otro la vuelve a poner."] = "По бокам модели — кнопка для каждой ячейки: один щелчок скрывает эту вещь, второй возвращает ее.",
	["A mitad de la pelea aparecen espectros de hielo: mátenlos rápido o usen ataques en área."] = "В середине боя появляются ледяные призраки: убейте их быстро или используйте атаки по области.",
	["A mitad de la pelea se protege con un escudo y prepara una gran explosión: cuando lo veas brillar, ¡aléjate de él!"] = "В середине боя он закрывается щитом и готовит мощный взрыв: когда он засветится, отойдите от него!",
	["A nivel 10 haces las misiones para domar a tu primera mascota."] = "На 10-м уровне ты выполняешь задания, чтобы приручить первого питомца.",
	["A nivel 20 aprendes Lobo fantasmal: ¡te vuelves un lobo como yo! Corre, que te echo una carrera."] = "На 20-м уровне ты изучаешь «Призрачного волка»: ты становишься волком, как я! Бежим, наперегонки!",
	["A nivel 60 sigue la rápida: equitación de oficial y una montura épica."] = "На 60-м уровне — быстрый: верховая езда подмастерья и эпический транспорт.",
	["A probar"] = "Пробуем",
	["A quién ir"] = "К кому идти",
	["A su entrenador"] = "К учителю",
	["A tu gusto"] = "По вашему вкусу",
	["A tu lado"] = "Рядом с вами",
	["A tu nivel los enemigos caen rápido: remata con 3 puntos de combo."] = "На вашем уровне противники падают быстро: добивайте при 3 очках серии.",
	["A un clic"] = "В один щелчок",
	["A veces"] = "Иногда",
	["A veces el golpe ni te toca."] = "Иногда удар вас даже не задевает.",
	["A veces pescas cajas y botellas con mensajes que empiezan una misión."] = "Иногда на удочку попадаются ящики и бутылки с посланиями, которые начинают задание.",
	["A veces salen gemas al minar: guárdalas, porque varias profesiones las usan en sus recetas."] = "Иногда при добыче руды попадаются самоцветы: храни их, ведь их используют в рецептах несколько профессий.",
	["Abajo"] = "Вниз",
	["Abajo del modelo, elige lo que hace tu personaje (caminar, bailar, saludar...) y páusalo."] = "Под моделью выберите, что делает ваш персонаж (идет, танцует, машет...), и ставьте на паузу.",
	["Abalorio"] = "Аксессуар",
	["Abalorios"] = "Аксессуары",
	["Abandonar"] = "Отказаться",
