	["Abandonaste %d misiones"] = "Вы отказались от заданий: %d",
	["Abierta"] = "Открыто",
	["Abiertas"] = "Открытые",
	["Abrazo vampírico: tu daño de sombras te cura."] = "Объятия вампира: ваш урон от темной магии лечит вас.",
	["Abre Heridas profundas."] = "Открывает Глубокие раны.",
	["Abre Paisaje y gráficos"] = "Открывает «Пейзаж и графика»",
	["Abre Recolección. Con «ruta», crea y sigue una ruta de farmeo en tu zona."] = "Открывает «Сбор». С «ruta» создает маршрут фарма в вашей зоне и ведет по нему.",
	["Abre desde el sigilo para empezar con ventaja."] = "Начинайте бой из незаметности, чтобы получить преимущество.",
	["Abre el mapa del juego en esta misma zona. En combate el mapa del juego no se abre desde Alfa."] = "Открывает карту игры на этой же зоне. В бою карта игры не открывается из Alfa.",
	["Abre el mapa y haz clic derecho (o Mayús+clic) donde quieras uno: le pones nombre, ícono y color, y la flecha te lleva cuando quieras. En el mapa del juego, Mayús+clic derecho."] = "Откройте карту и щелкните правой кнопкой (или Shift+щелчок) там, где нужен маркер: задайте имя, значок и цвет, и стрелка поведет вас туда, когда захотите. На карте игры — Shift+правый щелчок.",
	["Abre el modo pesca (aquí, con /alfa pesca o al ponerte la caña) y pulsa %s: tu tecla te pone el equipo, el cebo, lanza y recoge cuando salpica."] = "Откройте режим рыбалки (здесь, командой /alfa pesca или надев удочку) и нажмите %s: клавиша наденет снаряжение, наложит приманку, забросит и вытащит, когда поплавок дернется.",
	["Abre el modo pesca y elige tu tecla: te pone el equipo, el cebo, lanza y recoge cuando salpica."] = "Откройте режим рыбалки и выберите клавишу: она наденет снаряжение, наложит приманку, забросит и вытащит, когда поплавок дернется.",
	["Abre el modo pesca y pulsa tu tecla: lo que saques aparece aquí."] = "Откройте режим рыбалки и нажмите свою клавишу: весь улов появится здесь.",
	["Abre la Cocina del juego (el botón lo hace) y vuelve a pulsar."] = "Откройте окно «Кулинария» в игре (это делает кнопка) и нажмите снова.",
	["Abre la Enciclopedia y en la ficha del objeto toca «Agregar a mi ruta»."] = "Откройте «Энциклопедию» и на странице предмета нажмите «Добавить в мой маршрут».",
	["Abre la casa de subastas para escanear."] = "Откройте аукцион, чтобы сканировать.",
	["Abre la casa de subastas y pulsa «Escanear con Alfa» para saber cuánto valen tus objetos."] = "Откройте аукцион и нажмите «Сканировать с Alfa», чтобы узнать, сколько стоят ваши предметы.",
	["Abre la guía de Alfa que te lleva a conseguir este objeto."] = "Открывает гайд Alfa, который приведет вас к этому предмету.",
	["Abre la pelea a distancia antes de que llegue."] = "Начните бой издалека, пока противник не подошел.",
	["Abre la pelea: te acerca al enemigo y te da ira."] = "Начинает бой: сближает с противником и дает ярость.",
	["Abre la siguiente fila."] = "Открывает следующий ряд.",
	["Abre la ventana Historias."] = "Открывает окно «Истории».",
	["Abre la ventana de clic para lanzar de Blizzard para que armes ahí los mismos clics y cures igual en sus marcos de grupo (el juego no deja que un addon los copie)."] = "Открывает окно Blizzard для заклинаний по щелчку, чтобы настроить там те же щелчки и так же лечить на его рамках группы (игра не позволяет аддону их скопировать).",
	["Abre la ventana de talentos del juego una vez o espera unos segundos: en cuanto Alfa la lea, te dice qué poner. Mientras, abajo ves tu build."] = "Откройте окно талантов игры один раз или подождите несколько секунд: как только Alfa его прочитает, подскажет, что взять. А пока ниже ваш билд.",
	["Abre la ventana de tu profesión una vez y Alfa leerá tus recetas para decirte cuáles te dejan ganancia."] = "Откройте окно своей профессии один раз, и Alfa прочитает ваши рецепты, чтобы подсказать, какие из них приносят прибыль.",
	["Abre la ventana principal de Alfa."] = "Открывает главное окно Alfa.",
	["Abre o cierra el mapa de Alfa"] = "Открывает или закрывает карту Alfa",
