	["Aguas conocidas"] = "Знакомые воды",
	["Ahora"] = "Сейчас",
	["Ahora ganas la XP normal"] = "Теперь вы получаете обычный опыт",
	["Ahora no"] = "Не сейчас",
	["Ahora no pude armar el camino a esta misión."] = "Сейчас не удалось проложить путь к этому заданию.",
	["Ahora no sale: Alfa busca cómo unirse a la manada."] = "Сейчас не передается: Alfa ищет, как связаться со стаей.",
	["Ahora no se puede"] = "Сейчас нельзя",
	["Ahora no se puede anunciar"] = "Сейчас нельзя объявить",
	["Ahora no se pueden enviar mensajes (en una instancia o con una cuenta de prueba). %s"] = "Сейчас нельзя отправлять сообщения (в подземелье или с пробной учетной записью). %s",
	["Ahora toca la colección: completa tu diario, los logros y prueba el concurso de los domingos."] = "Теперь время коллекции: заполните журнал, получите достижения и попробуйте воскресное состязание.",
	["Ahora usan: %s. Activa los pesos de %s para que Alfa compare el equipo como lo pide tu build."] = "Сейчас используются: %s. Включите веса «%s», чтобы Alfa сравнивал снаряжение так, как требует ваш билд.",
	["Ahora va por el canal oculto de Alfa."] = "Теперь передается через скрытый канал Alfa.",
	["Ahora va por tu hermandad: el canal oculto de Alfa no está disponible, así que solo te ven quienes comparten en tu hermandad."] = "Теперь передается через вашу гильдию: скрытый канал Alfa недоступен, поэтому вас видят только те, кто делится в вашей гильдии.",
	["Ahora vas a: %s"] = "Сейчас вы идете к: %s",
	["Ahora: %d %% del nivel %d"] = "Сейчас: %d %% уровня %d",
	["Ahora: %s"] = "Сейчас: %s",
	["Ahora: %s · De fábrica: %s"] = "Сейчас: %s · По умолчанию: %s",
	["Ahora: %s."] = "Сейчас: %s.",
	["Ahí no hay ninguna zona: pon el marcador sobre tierra."] = "Здесь нет зоны: поставьте маркер на сушу.",
	["Ahí no se puede poner la flecha."] = "Туда нельзя поставить стрелку.",
	["Ahí nos organizamos para todo. Haz clic en el enlace y cópialo con Ctrl+C."] = "Там мы обо всем договариваемся. Щелкните ссылку и скопируйте ее Ctrl+C.",
	["Ajustar"] = "Настроить",
	["Ajustar los avisos"] = "Настроить предупреждения",
	["Ajustes"] = "Настройки",
	["Ajustes de Alfa en todos los idiomas: las fechas en el orden de cada uno y los nombres de cada especialización bien puestos."] = "Настройки Alfa на всех языках: даты в порядке, принятом в каждом языке, и правильные названия каждой специализации.",
	["Ajustes de Bolsas"] = "Настройки сумок",
	["Ajustes de Lya"] = "Настройки Lya",
	["Ajustes de mazmorras"] = "Настройки подземелий",
	["Ajustes de pesca"] = "Настройки рыбалки",
	["Ajustes del mapa"] = "Настройки карты",
	["Ajustes del medidor"] = "Настройки измерителя",
	["Ajustes en orden: Comodidades y Calidad de vida son una sola página con pestañas, y todo lo de misiones vive en Ajustes > Misiones. Tu configuración se mudó sola, sin perder nada."] = "Порядок в настройках: «Удобства» и «Качество жизни» — теперь одна страница с вкладками, а всё о заданиях находится в Настройки > Задания. Ваши настройки переехали сами, ничего не потерялось.",
	["Al abrirse el mapa de vuelo, vuela al destino que marca tu ruta."] = "Когда открывается карта полетов, летит в пункт, отмеченный маршрутом.",
	["Al acercar o cargar el mapa, cada parte aparece completa de una vez, sin cuadritos sueltos."] = "При приближении или загрузке карты каждая часть появляется целиком сразу, без отдельных квадратиков.",
	["Al acercar se ven las montañas y el relieve, igual que en el minimapa. Apagado: el mapa pintado del juego."] = "При приближении видны горы и рельеф, как на мини-карте. Выключено: нарисованная карта игры.",
	["Al armar tus rutas, Alfa deja fuera las que piden élites."] = "Составляя маршруты, Alfa исключает задания с элитными противниками.",
	["Al cambiar de forma o de actitud, el juego usa otra barra de abajo. Si está vacía, Alfa te avisa una vez y puede llenar sus casillas vacías con las habilidades de esa forma que ya sabes, fuera de combate y sin tocar lo que ya tienes."] = "При смене облика или стойки игра использует другую нижнюю панель. Если она пуста, Alfa один раз предупредит вас и может заполнить ее пустые ячейки уже известными вам способностями этого облика — вне боя и не трогая то, что у вас уже есть.",
	["Al cambiar de forma, el juego cambia tu barra de abajo por la de esa forma, y esta todavía no tiene nada: por eso parece que desaparece. Alfa puede poner en sus casillas vacías las habilidades de esa forma que ya sabes."] = "При смене облика игра заменяет вашу нижнюю панель панелью этого облика, а на ней пока ничего нет — поэтому кажется, что панель исчезает. Alfa может поставить в ее пустые ячейки уже известные вам способности этого облика.",
	["Al comerciante"] = "Торговцу",
	["Al comparar objetos, Alfa valora más lo que pide %s: lo de arriba en la lista de estadísticas."] = "При сравнении предметов Alfa больше ценит то, что требует %s: верх списка характеристик.",
	["Al día"] = "Актуально",
	["Al elegir un build, las flechas de mejora de tus bolsas valoran lo que ese build necesita."] = "Когда вы выбираете билд, стрелки улучшения в сумках учитывают то, что нужно этому билду.",
	["Al empezar aturde a quien lo despertó en el altar: es normal."] = "В начале он оглушает того, кто разбудил его у алтаря: это нормально.",
	["Al enemigo le queda poca vida: Quemadura de las Sombras lo remata."] = "У противника мало здоровья: Ожог тьмы добьет его.",
	["Al enemigo le queda poca vida: remátalo al instante."] = "У противника мало здоровья: добейте его мгновенно.",
	["Al enemigo le queda poca vida: remátalo."] = "У противника мало здоровья: добейте его.",
	["Al entregar una misión, Lya te ofrece contarte cómo terminó."] = "Когда вы сдаете задание, Lya предлагает рассказать, чем оно закончилось.",
	["Al final de la Tercera Guerra, Arthas subió al Trono Helado, se puso el yelmo y se volvió uno con el Rey Exánime."] = "В конце Третьей войны Артас поднялся на Ледяной Трон, надел шлем и стал единым целым с Королем-личом.",
	["Al final de la pelea se enfurece y pega más rápido: guarda curación para ese momento."] = "В конце боя он впадает в ярость и бьет быстрее: приберегите лечение на этот момент.",
	["Al final se enfurece: guarden su mejor daño para el final."] = "В конце она впадает в ярость: приберегите самый сильный урон на конец.",
	["Al final, habla con el Discípulo de Naralex y protégelo mientras camina: así aparece el último jefe."] = "В конце поговорите с Учеником Наралекса и защищайте его, пока он идет: так появится последний босс.",
	["Al hablar con el maestro de vuelo, abre su mapa directamente."] = "При разговоре с распорядителем полетов сразу открывает его карту.",
	["Al hablar con quien da una misión de tu ruta, se acepta sola."] = "Когда вы говорите с тем, кто выдает задание из вашего маршрута, оно принимается само.",
	["Al hablar con quien da una misión de tu ruta, se acepta sola. Mayús la deja para ti."] = "Когда вы говорите с тем, кто выдает задание вашего маршрута, оно принимается само. Shift оставит выбор вам.",
	["Al hablar con un PNJ"] = "При разговоре с NPC",
	["Al hablar con un banquero se abre el banco de Alfa, con depositar rápido. La primera visita de cada personaje muestra el del juego: así recibe su primera pestaña."] = "Разговор с банкиром открывает банк Alfa с быстрым вкладом. При первом визите каждого персонажа показывается банк игры: так он получает первую вкладку.",
	["Al hurtar a los humanoides ganas monedas y a veces cajas cerradas."] = "Обшаривая карманы гуманоидов, ты получаешь монеты, а иногда и запертые ящики.",
	["Al llegar a una ciudad o posada. También repite la nota de entrenar de la guía cuando su ventana está oculta."] = "Когда вы прибываете в город или таверну. Также повторяет заметку гайда об обучении, когда его окно скрыто.",
	["Al morir aparecen cuatro abisarios que caminan juntos por el patio: prepárense para pelear con varios."] = "После его смерти появляются четыре демона Бездны, которые вместе идут по двору: приготовьтесь к бою с несколькими.",
	["Al morir en un campo de batalla, liberas tu espíritu al momento."] = "Если вы погибли на поле боя, дух освобождается сразу.",
	["Al morir llegan muchos aprendices: prepárense para muchos enemigos a la vez."] = "После его смерти прибегает много учеников: приготовьтесь к множеству противников сразу.",
	["Al moverte, la tecla vuelve a la normal"] = "В движении клавиша работает как обычно",
	["Al moverte, solo de lado"] = "В движении — только вбок",
	["Al norte de estas montañas están las Estepas Ardientes y la Montaña Roca Negra, de donde salen los orcos que amenazan Villa del Lago."] = "К северу от этих гор лежат Пылающие степи и Черная гора, откуда приходят орки, угрожающие Приозерью.",
	["Al objetivo le queda poca vida: Ejecutar lo remata usando tu ira."] = "У цели мало здоровья: Казнь добьет ее за счет ярости.",
	["Al objetivo le queda poca vida: el martillo lo remata a distancia."] = "У цели мало здоровья: молот добьет ее издалека.",
	["Al pasar el ratón por un objeto: «Tienes 12 (Lobato: 7 en bolsas, Alt: 5 en banco)», con todos tus personajes."] = "В подсказке предмета: «У вас 12 (Lobato: 7 в сумках, Alt: 5 в банке)», по всем вашим персонажам.",
	["Al pasar el ratón sobre un objeto: su precio en la subasta, lo que paga el comerciante y qué te conviene."] = "При наведении на предмет: его цена на аукционе, сколько платит торговец и что вам выгоднее.",
	["Al pie de Cima del Trueno está el poblado Pezuña de Sangre, donde Baine, el hijo de Cairne, cuida a su gente."] = "У подножия Громового Утеса лежит деревня Кровавого Копыта, где Бейн, сын Кэрна, заботится о своем народе.",
	["Al recibir daño suelta pedazos más pequeños: mátenlos con ataques en área."] = "Получая урон, он откалывает осколки поменьше: убивайте их атаками по области.",
	["Al sacar algo"] = "Когда что-то поймали",
	["Al seguir, Alfa se recarga para cambiar el idioma y esta configuración sigue donde la dejaste."] = "Если продолжить, Alfa перезагрузится, чтобы сменить язык, а настройка продолжится с того же места.",
	["Al subir de nivel (y al entrar, si te quedan puntos), un aviso dice qué talento poner, con el botón para aplicarlo."] = "При повышении уровня (и при входе, если остались очки) оповещение подскажет, какой талант взять, с кнопкой, чтобы применить его.",
	["Al subir de nivel te muestra qué aprender y cuánto cuesta."] = "При повышении уровня показывает, что изучить и сколько это стоит.",
	["Al subir de nivel, un aviso dice qué aprender, cuánto cuesta y con qué entrenador, con el botón Llévame."] = "При повышении уровня оповещение подскажет, что изучить, сколько это стоит и у какого учителя, с кнопкой «Отведи меня».",
	["Al sur de Cuna del Invierno, una garganta escondida está llena de demonios."] = "К югу от Зимних Ключей есть скрытое ущелье, полное демонов.",
	["Al sur de Los Baldíos, el Gran Elevador baja hasta Las Mil Agujas. ¡No mires hacia abajo!"] = "На юге Степей Великий подъемник спускается в Тысячу Игл. Не смотри вниз!",
	["Al sur está Dalaran, la ciudad de los magos. Archimonde la arrasó en la Tercera Guerra, y sus magos la reconstruyen protegidos bajo una cúpula."] = "На юге — Даларан, город магов. Архимонд разрушил его в Третьей войне, и маги отстраивают его под защитным куполом.",
	["Al sur se alza una muralla enorme: el rey Genn Cringris la levantó para aislar Gilneas del resto del mundo."] = "На юге высится огромная стена: король Генн Седогрив возвел ее, чтобы отгородить Гилнеас от остального мира.",
	["Al terminar una guía de nivel, carga la siguiente sin preguntar."] = "Когда гайд прокачки заканчивается, загружает следующий без вопросов.",
	["Al volver con una misión lista, se entrega sola. Si hay recompensas para elegir, eliges tú."] = "Когда вы возвращаетесь с выполненным заданием, оно сдается само. Если нужно выбрать награду, выбираете вы.",
	["Alamuerte forjó en secreto el Alma de Demonio, un disco dorado cargado con el poder de los demás Aspectos, que se lo dieron sin saber para qué lo quería."] = "Смертокрыл тайно выковал Душу Демона — золотой диск, заряженный силой других Аспектов, которые отдали ее, не зная, зачем она ему.",
	["Alamuerte se hizo pasar por Lord Daval Prestor, un noble que casi llegó a rey de Alterac. ¡A esa familia le encantan los disfraces!"] = "Смертокрыл выдавал себя за лорда Давала Престора, дворянина, который едва не стал королем Альтерака. Эта семейка обожает маскарад!",
	["Alcance de las sombras"] = "Дальность теней",
	["Alcanza para %d"] = "Хватит на %d",
	["Alejar"] = "Отдалить",
	["Alejar la cámara"] = "Максимальное отдаление камеры",
	["Alejar más la cámara"] = "Отдалять камеру сильнее",
	["Alertas"] = "Оповещения",
	["Alexandros Mograine empuñaba la Crematoria, y la Plaga le temía como a nadie. Lo traicionó su propio hijo, Renault."] = "Александрос Могрейн владел Испепелителем, и Плеть боялась его как никого другого. Его предал собственный сын, Рено.",
	["Alfa"] = "Alfa",
	["Alfa %s ya está aquí"] = "Alfa %s уже здесь",
	["Alfa %s · cliente %s (%s) · %s · Alfa en %s"] = "Alfa %s · клиент %s (%s) · %s · язык Alfa: %s",
	["Alfa (el estilo propio, por omisión), Clásico WoW (marcos y letras del juego) o Cristal (transparente, con el acento que elijas). El modo compacto y tus colores funcionan en los tres."] = "Alfa (собственный стиль, по умолчанию), Классический WoW (рамки и шрифты игры) или Стекло (прозрачный, с выбранным акцентом). Компактный режим и ваши цвета работают во всех трех.",
	["Alfa arma el reporte y tú lo pegas en el buzón privado del Discord de La Jauría. También con /alfa reportar."] = "Alfa составит отчет, а вы вставите его в личный почтовый ящик в Discord La Jauría. Также командой /alfa reportar.",
	["Alfa arma la ruta más corta para cobrarlas, junta por PNJ. La flecha usa vuelos y tu piedra de hogar cuando conviene, y te avisa si una entrega queda lejos."] = "Alfa составляет самый короткий маршрут для сдачи, группируя по NPC. Стрелка использует полеты и камень возвращения, когда выгодно, и предупреждает, если место сдачи далеко.",
	["Alfa borrará lo que guardó de %s: sus bolsas, su banco y su equipo. Si vuelves a jugar con él, se guarda de nuevo."] = "Alfa удалит все, что сохранил о персонаже %s: сумки, банк и экипировку. Если снова зайдете им в игру, данные сохранятся заново.",
	["Alfa de La Jauría"] = "Альфа La Jauría",
	["Alfa elige las misiones que más XP dan cerca de ti, en tres tandas."] = "Alfa выбирает задания рядом с вами, дающие больше всего опыта, в три захода.",
	["Alfa elige todo: misiones ordenadas por XP por distancia y tus misiones de clase."] = "Alfa выбирает все сам: задания по соотношению опыта к расстоянию и ваши классовые задания.",
	["Alfa es un addon que toxic3000 creó para sus amigos y quiso compartir con todos."] = "Alfa — аддон, который toxic3000 создал для друзей и решил подарить всем.",
	["Alfa estable: en orden y en manada"] = "Стабильная Alfa: порядок и стая",
	["Alfa está armando tu ruta..."] = "Alfa составляет ваш маршрут...",
	["Alfa está eligiendo..."] = "Alfa выбирает...",
	["Alfa está leyendo tu clase"] = "Alfa считывает ваш класс",
	["Alfa está oculto: clic para mostrarlo y abrir su ventana"] = "Alfa скрыт: щелкните, чтобы показать его и открыть окно",
	["Alfa la vuelve a poner al entrar."] = "Alfa снова применит его при входе.",
	["Alfa le agregó lo que ayuda a arreglarlo: versiones, idioma, tu clase y nivel y dónde estás. No lleva tu nombre ni tu reino."] = "Alfa добавил то, что поможет это исправить: версии, язык, ваш класс, уровень и где вы находитесь. Без вашего имени и игрового мира.",
	["Alfa lee el medidor oficial del juego. Enciéndelo y aquí verás el daño de tu grupo; su ventana puedes ocultarla en el Modo de edición."] = "Alfa читает официальный измеритель игры. Включите его, и здесь появится урон вашей группы; его окно можно скрыть в режиме редактирования.",
	["Alfa lo hace toxic3000 para La Jauría. Es software libre (GPL-3.0) y su código está en github.com/toxic3000/alfa-forever."] = "Alfa делает toxic3000 для La Jauría. Это свободное ПО (GPL-3.0), его код находится на github.com/toxic3000/alfa-forever.",
	["Alfa los cambia por el rango nuevo sin moverlos de lugar."] = "Alfa заменит их новым рангом, не сдвигая с места.",
	["Alfa mantiene %d ajustes que elegiste. Abre la ventana para ver o cambiar cada uno."] = "Alfa хранит выбранные вами настройки: %d. Откройте окно, чтобы посмотреть или изменить каждую.",
	["Alfa mantiene %d ajustes tuyos y los vuelve a poner al entrar."] = "Alfa хранит ваши настройки (%d) и снова применяет их при входе.",
	["Alfa mide los caminos (vuelos y piedra de hogar): tarda unos segundos."] = "Alfa измеряет пути (полеты и камень возвращения): это займет несколько секунд.",
	["Alfa no está afiliado a esos proyectos ni ellos lo respaldan; gracias a todos por compartir su trabajo."] = "Alfa не связан с этими проектами, и они его не поддерживают официально; спасибо всем за то, что делятся своей работой.",
	["Alfa no ha cambiado nada todavía. Prueba «Paisaje de la manada» o abre la ventana para ver los ajustes que el menú del juego no enseña."] = "Alfa пока ничего не менял. Попробуйте «Пейзаж стаи» или откройте окно, чтобы увидеть настройки, которых нет в меню игры.",
	["Alfa no pudo armar el camino a %s. Míralo en la Enciclopedia."] = "Alfa не смог построить путь к %s. Посмотрите в «Энциклопедии».",
	["Alfa no tiene datos de esto todavía."] = "У Alfa пока нет данных об этом.",
	["Alfa no tiene el instructor de tu raza: busca «equitación» en PNJ."] = "Alfa не знает учителя вашей расы: найдите «верховая езда» в разделе NPC.",
	["Alfa no toma misiones que no sirven a tu ruta, ni las entrega solas. Lo respeta también «todas las misiones» de Comodidades."] = "Alfa не берет задания, не нужные вашему маршруту, и не сдает их сам. Это соблюдает и «все задания» из «Удобств».",
	["Alfa no toma misiones que no sirven a tu ruta, ni las entrega solas. Lo respeta también «todas las misiones»."] = "Alfa не берёт задания, которые не нужны вашему маршруту, и не сдаёт их сама. «Все задания» тоже это учитывает.",
	["Alfa no toma misiones que no sirven a tu ruta. Tu registro queda limpio."] = "Alfa не берет задания, которые не нужны маршруту. Журнал заданий остается чистым.",
	["Alfa ordena las paradas para que no camines de más. Tarda unos segundos y no traba el juego."] = "Alfa упорядочивает остановки, чтобы вы не ходили лишнего. Это займет несколько секунд и не подвесит игру.",
	["Alfa recuerda lo que llevabas antes de ponerte lo de pesca y te lo vuelve a poner."] = "Alfa запоминает, что было надето до рыболовного снаряжения, и надевает это обратно.",
	["Alfa revisa lo que elegiste cuando el juego termina de cargar. Si los cambias en el menú del juego, se queda con lo nuevo."] = "Alfa проверяет ваш выбор, когда игра заканчивает загрузку. Если вы измените их в меню игры, он оставит новые.",
	["Alfa revisa su base de objetos sin trabar el juego. Tarda unos segundos la primera vez."] = "Alfa просматривает свою базу предметов, не подвешивая игру. В первый раз это займет несколько секунд.",
	["Alfa revisa su base de objetos, se queda con lo que tu clase puede usar cerca de tu nivel y lo compara con lo que llevas, con los pesos de tu build."] = "Alfa просматривает свою базу предметов, оставляет то, что ваш класс может носить около вашего уровня, и сравнивает с надетым по весам вашего билда.",
	["Alfa se está uniendo al canal oculto de La Jauría. En unos segundos ves a quien comparte."] = "Alfa подключается к скрытому каналу La Jauría. Через несколько секунд вы увидите тех, кто делится.",
	["Alfa se muestra en el idioma que elijas, aunque tu juego esté en otro."] = "Alfa отображается на выбранном вами языке, даже если игра на другом.",
	["Alfa se recarga para cambiar el idioma. La configuración sigue donde la dejaste."] = "Alfa перезагружается, чтобы сменить язык. Настройка продолжится с того же места.",
	["Alfa solo leyó tus valores: nada cambia hasta que toques un control."] = "Alfa только прочитал ваши значения: ничего не изменится, пока вы не тронете ползунок или переключатель.",
	["Alfa sugiere con su prioridad para %s, leyendo solo tu personaje: tu recurso, tus recargas, los efectos que el juego activa y la vida del enemigo cuando se puede leer. Con varios enemigos cambia a las de área. Tú decides qué presionar."] = "Alfa подсказывает по своему приоритету (%s), читая только вашего персонажа: ресурс, восстановление способностей, эффекты, которые подсвечивает игра, и здоровье противника, когда его можно прочитать. При нескольких противниках переключается на способности по области. Что нажимать — решаете вы.",
	["Alfa tampoco tiene todavía una prioridad para tu clase con lo que sabes. Los avisos de reacción y el medidor sí funcionan."] = "У Alfa пока тоже нет приоритета для вашего класса с вашими нынешними способностями. Оповещения о реакциях и измеритель работают.",
	["Alfa te avisa aquí de lo importante: equipo por reparar, bolsas llenas, habilidades nuevas, tu buff y tu descanso."] = "Здесь Alfa сообщает о важном: экипировка требует починки, сумки полны, есть новые навыки, ваш бафф и отдых.",
	["Alfa te avisa del equipo gastado, las bolsas llenas, lo que puedes entrenar, tu buff y tu descanso. Aquí eliges cuáles y cuándo."] = "Alfa предупреждает об изношенном снаряжении, полных сумках, том, что можно изучить, вашем баффе и отдыхе. Здесь выбирается, о чем и когда.",
	["Alfa te lleva paso a paso, con la flecha y la ruta en el mapa. Elige la de tu zona y tu nivel."] = "Alfa ведет вас шаг за шагом — стрелкой и маршрутом на карте. Выберите гайд для своей зоны и уровня.",
	["Alfa todavía no tiene builds para tu clase"] = "У Alfa пока нет билдов для вашего класса",
	["Alfa usa código y datos de estos proyectos libres, con sus avisos de autor y sus licencias incluidos en cada carpeta:"] = "Alfa использует код и данные этих свободных проектов; их уведомления об авторских правах и лицензии лежат в каждой папке:",
	["Alfa vuelve a elegir desde donde estás ahora (las misiones fijas se quedan)."] = "Alfa заново выбирает от вашего текущего места (закрепленные задания остаются).",
	["Alfa · Top %d de %s (%s%s)"] = "Alfa · Топ %d: %s (%s%s)",
	["Alfa, Clásico WoW o Cristal, la flecha del lobo y el aullido."] = "Alfa, Классический WoW или Стекло, стрелка-волк и вой.",
	["Alfa: agregar a Cerrar mis misiones"] = "Alfa: добавить в «Закрыть мои задания»",
	["Alfa: capas del mapa"] = "Alfa: слои карты",
	["Alfa: cerrar mis misiones"] = "Alfa: закрыть мои задания",
	["Alfa: quitar de Cerrar mis misiones"] = "Alfa: убрать из «Закрыть мои задания»",
	["Alfa_Codex está apagado en la lista de addons."] = "Alfa_Codex выключен в списке модификаций.",
	["Algo no anda bien en el árbol: los furbolgs que viven en él se están volviendo agresivos."] = "С деревом что-то не так: живущие на нем фурболги становятся агрессивными.",
	["Algunas fórmulas de encantamiento muy buscadas caen de enemigos en las Tierras de la Peste."] = "Некоторые востребованные формулы наложения чар падают с противников в Чумных землях.",
	["Algunas recetas raras se compran a vendedores lejanos o caen de enemigos; vale la pena buscarlas."] = "Некоторые редкие рецепты продают далекие торговцы или они падают с противников; их стоит поискать.",
	["Algunos ajustes, como el HDR, se ven hasta reiniciar los gráficos. Te pide confirmación."] = "Некоторые настройки, например HDR, видны только после перезапуска графики. Попросит подтверждения.",
	["Algunos ogros tienen dos cabezas, y no siempre se ponen de acuerdo entre ellas."] = "У некоторых огров две головы, и они не всегда друг с другом согласны.",
	["Algunos orcos nunca siguieron a Thrall: los Roca Negra de la montaña sirven a los dragones negros."] = "Не все орки пошли за Траллом: орки Черной горы служат черным драконам.",
	["Alianza"] = "Альянс",
	["Alimenta a tu mascota: si está contenta pega más y te es más leal."] = "Корми питомца: довольный, он бьет сильнее и становится преданнее.",
	["Alquimia"] = "Алхимия",
	["Alt"] = "Alt",
	["Alt+clic en un objeto abre su ficha"] = "Alt+щелчок по предмету открывает его страницу",
	["Alta"] = "Высокое",
	["Altas"] = "Высокие",
	["Alto"] = "Высота",
	["Alto [calidad]"] = "Высокий",
	["Alto de las barras"] = "Высота полос",
	["Altos"] = "Высокие",
	["Ambiente mientras pescas"] = "Атмосфера во время рыбалки",
	["Amenaza"] = "Угроза",
	["Anasterian, el rey de los altos elfos, dejó la Alianza tras la Segunda Guerra, y murió frente a Arthas defendiendo la Fuente del Sol."] = "Анастериан, король высших эльфов, покинул Альянс после Второй войны и погиб в бою с Артасом, защищая Солнечный Колодец.",
	["Ancho"] = "Ширина",
	["Andorhal era el granero de Lordaeron. Kel'Thuzad repartió ahí grano apestado y la plaga se extendió por todo el reino."] = "Андорал был житницей Лордерона. Кел'Тузад раздавал там зараженное зерно, и чума распространилась по всему королевству.",
	["Anduin Lothar, el León de Azeroth, llevó a los refugiados de Ventormenta hasta Lordaeron y fue el primer comandante de la Alianza."] = "Андуин Лотар, Лев Азерота, привел беженцев Штормграда в Лордерон и стал первым командующим Альянса.",
	["Anillos"] = "Кольца",
	["Animación anterior"] = "Предыдущая анимация",
	["Animación siguiente"] = "Следующая анимация",
	["Anisotrópico 16x"] = "Анизотропная 16x",
	["Anisotrópico 2x"] = "Анизотропная 2x",
	["Anisotrópico 4x"] = "Анизотропная 4x",
	["Anisotrópico 8x"] = "Анизотропная 8x",
	["Anterior"] = "Предыдущий",
	["Antes de atacar, mira quién está cerca. Pelear con uno a la vez es más seguro."] = "Перед атакой посмотри, кто рядом. Сражаться по одному безопаснее.",
	["Antes de buscar la espada, Arthas mandó quemar sus propios barcos para que sus soldados no pudieran volver a casa."] = "Прежде чем искать меч, Артас приказал сжечь свои корабли, чтобы его солдаты не смогли вернуться домой.",
	["Antes de comprar algo en la subasta, revisa si un vendedor lo tiene más barato."] = "Прежде чем покупать на аукционе, проверь, нет ли этого дешевле у торговца.",
	["Antes de empezar, unas palabras de la manada."] = "Прежде чем начать — пара слов от стаи.",
	["Antes de entrar"] = "Перед входом",
	["Antes de entregarla te falta: %s."] = "Перед сдачей осталось: %s.",
	["Antes de pelear"] = "Перед боем",
	["Antes de pelear: abre con Piroexplosión, tu hechizo más fuerte."] = "Перед боем: начните с Огненной глыбы — вашего самого сильного заклинания.",
	["Antes de salir de caza, configura Alfa a tu medida: el idioma, cómo se ve, qué hace sola por ti y si quieres que la manada te vea en el mapa del juego."] = "Перед охотой настройте Alfa под себя: язык, внешний вид, что Alfa делает за вас и хотите ли вы, чтобы стая видела вас на карте игры.",
	["Antes esto era un pantano. La magia del portal y la guerra lo dejaron rojo, seco y sin vida."] = "Когда-то здесь было болото. Магия портала и война сделали эту землю красной, сухой и безжизненной.",
	["Antes hay que hacer otra misión"] = "Сначала нужно другое задание",
	["Antes necesitas"] = "Сначала нужно",
	["Antes necesitas otra misión"] = "Сначала нужно другое задание",
	["Antes pide %s (%s)"] = "Сначала нужно: %s (%s)",
	["Antes que los elfos, los trols tuvieron grandes imperios en Azeroth, como el Amani en el norte y el Gurubashi en el sur."] = "Еще до эльфов у троллей были великие империи в Азероте, например Амани на севере и Гурубаши на юге.",
	["Antes, el reino de Ventormenta se llamaba Azeroth, igual que el mundo; Ventormenta era solo el nombre de su capital."] = "Раньше королевство Штормград называлось Азерот, как и весь мир; Штормградом звалась только его столица.",
	["Antes: %s"] = "Сначала: %s",
	["Antes: %s."] = "Сначала: %s.",
	["Anunciar"] = "Объявить",
	["Anunciar en el chat"] = "Объявить в чате",
	["Anunciar en el grupo"] = "Объявить группе",
	["Apaga la viñeta, el grano, las barras y el tinte de un clic."] = "Одним щелчком выключает виньетку, зерно, полосы и оттенок.",
	["Apagada"] = "Выключено",
	["Apagadas"] = "Выключены",
	["Apagado"] = "Выключено",
	["Apagado, el grano se queda quieto."] = "Если выключено, зерно неподвижно.",
	["Apagado, solo las acepta y la entrega la haces tú."] = "Если выключено, задания только принимаются, а сдаете их вы сами.",
	["Apagados"] = "Выключены",
	["Apagarlo"] = "Выключить",
	["Aparece al final del evento del Discípulo de Naralex: protege al druida mientras camina."] = "Появляется в конце события Ученика Наралекса: защищайте друида, пока он идет.",
	["Aparece al tocar el gong por tercera vez, después de dos oleadas de arañas."] = "Появляется после третьего удара в гонг, после двух волн пауков.",
	["Aparece con una misión de la Horda (un objeto en el agua). Lanza escarcha."] = "Появляется по заданию Орды (предмет в воде). Применяет заклинания льда.",
	["Aparece en cuanto termines la bienvenida de Alfa."] = "Появится, как только вы завершите приветствие Alfa.",
	["Aparece en el evento de la explosivista: protégela mientras llegan oleadas de troggs."] = "Появляется во время события подрывницы: защищайте ее, пока идут волны троггов.",
	["Aparecen marcos de ejemplo: arrástralos a donde los quieras y ajusta su tamaño. Así se verá tu grupo."] = "Появятся образцы рамок: перетащите их куда нужно и настройте размер. Так будет выглядеть ваша группа.",
	["Aplaudir"] = "Аплодисменты",
	["Aplica la nitidez de abajo aunque no uses el escalado de resolución."] = "Применяет резкость ниже, даже если вы не используете масштабирование разрешения.",
	["Aplicar"] = "Применить",
	["Aplicar %d puntos"] = "Применить очки: %d",
	["Aprende Cocina con un instructor."] = "Изучите кулинарию у учителя.",
	["Aprende Cocina para encender fogatas."] = "Изучите кулинарию, чтобы разводить костры.",
	["Aprende Minería o Herboristería"] = "Изучите горное дело или травничество",
	["Aprende Pesca"] = "Изучите рыбную ловлю",
	["Aprende Pesca con un instructor"] = "Изучите рыбную ловлю у учителя",
	["Aprende Pesca con un instructor de pesca y compra una caña: la guía te lleva."] = "Изучите рыбную ловлю у учителя рыбной ловли и купите удочку: гайд приведет вас.",
	["Aprende Pesca con un instructor, compra una caña y pesca en tu zona de inicio o en la capital. Pide el rango Oficial desde 50."] = "Изучите рыбную ловлю у учителя, купите удочку и рыбачьте в стартовой зоне или в столице. Ступень «Подмастерье» — с 50.",
	["Aprende equitación con %s"] = "Изучите верховую езду у: %s",
	["Aprende las dos, consigue una caña y cocina lo que pescas hasta 75."] = "Изучите обе, раздобудьте удочку и готовьте пойманное до 75.",
	["Aprender %s"] = "Изучить: %s",
	["Aprender de tus búsquedas"] = "Учиться на ваших поисках",
	["Aprender una profesión o llegar a un nivel en ella."] = "Изучить профессию или достичь в ней уровня.",
	["Aprendiste un hechizo que le queda mejor a tus clics:"] = "Вы изучили заклинание, которое лучше подходит для ваших щелчков:",
	["Aprendiz"] = "Ученик",
	["Apréndelos con el entrenador de tu clase, en cualquier capital."] = "Изучите их у учителя вашего класса в любой столице.",
	["Apágalo si no quieres que Alfa toque tus teclas, tu equipo ni tus ajustes al pescar."] = "Выключите, если не хотите, чтобы Alfa трогал ваши клавиши, снаряжение и настройки во время рыбалки.",
	["Aquí"] = "Здесь",
	["Aquí aparecerán los demás módulos de Alfa (bolsas, rutas, mundo y más) en cuanto estén instalados."] = "Здесь появятся другие модули Alfa (сумки, маршруты, мир и другие), как только они будут установлены.",
	["Aquí el juego no da tu posición (por ejemplo, dentro de una mazmorra)."] = "Здесь игра не сообщает ваше положение (например, в подземелье).",
	["Aquí el juego no deja compartir nada. Al salir, tu rastro vuelve a salir solo."] = "Здесь игра не позволяет ничем делиться. После выхода ваш след снова начнет передаваться сам.",
	["Aquí estoy, como siempre. Nunca dejo a nadie atrás."] = "Я здесь, как всегда. Я никого не бросаю.",
	["Aquí está el Portal Oscuro: por él cruzó la Horda desde Draenor para invadir Azeroth en la Primera Guerra."] = "Здесь стоит Темный портал: через него Орда пришла из Дренора, чтобы вторгнуться в Азерот в Первой войне.",
	["Aquí está la tumba de Uther el Iluminado, el maestro de Arthas. Murió a manos de su propio alumno, defendiendo las cenizas del rey Terenas."] = "Здесь гробница Утера Светоносного, наставника Артаса. Он погиб от руки собственного ученика, защищая прах короля Теренаса.",
	["Aquí la lees completa: cómo empieza, qué te piden y cómo termina."] = "Здесь можно прочитать ее целиком: как она начинается, что от вас просят и чем заканчивается.",
	["Aquí no hay nodos que recolectar"] = "Здесь нечего собирать",
	["Aquí sale por qué se activó la habilidad."] = "Здесь видно, почему сработала способность.",
	["Aquí ves cuántas llevas, dónde sale y qué hacer con ella."] = "Здесь видно, сколько у вас есть, где она ловится и что с ней делать.",
	["Aquí ves todo lo que hay que saber, con qué hacer después."] = "Здесь все, что нужно знать, и что делать дальше.",
	["Aquí: %s %.1f, %.1f. Se guarda este punto."] = "Здесь: %s %.1f, %.1f. Эта точка сохранена.",
	["Arañazo: sangrado con el tiempo."] = "Глубокая рана: кровотечение со временем.",
	["Arcano"] = "Тайная магия",
	["Arcano para subir"] = "Тайная магия для прокачки",
	["Archimonde subió a Hyjal para robar la energía del Árbol del Mundo; en vez de eso, el árbol fue su final."] = "Архимонд поднялся на Хиджал, чтобы украсть силу Древа Мира, но вместо этого древо стало его концом.",
	["Arco"] = "Лук",
	["Arcos, ballestas y armas de fuego"] = "Луки, арбалеты и огнестрельное оружие",
	["Arena"] = "Песочный",
	["Arma"] = "Оружие",
	["Arma con tu ruta lo que necesitas para poder tomarla: el nivel o las misiones de antes."] = "Составляет с вашим маршрутом то, что нужно, чтобы взять его: уровень или предыдущие задания.",
	["Arma de asta"] = "Древковое оружие",
	["Arma de dos manos"] = "Двуручное оружие",
	["Arma de dos manos, sellos y juicios: el paladín que mejor sube en solitario."] = "Двуручное оружие, печати и правосудие: паладин, который лучше всех качается в одиночку.",
	["Arma de fuego"] = "Огнестрельное оружие",
	["Arma de puño"] = "Кистевое оружие",
	["Arma el plan para cerrar las misiones de tu registro y te lleva a cada una."] = "Составляет план, чтобы закрыть задания из журнала, и ведет к каждому.",
	["Arma tu grupo de 5 (buscador de grupos o tu manada)."] = "Соберите группу из 5 (поиск группы или ваша стая).",
	["Arma tu primer plan"] = "Составьте первый план",
	["Arma una ruta de %s en %s"] = "Составьте маршрут: %s, %s",
	["Arma y escudo"] = "Оружие и щит",
	["Armadura"] = "Броня",
	["Armaduras"] = "Доспехи",
	["Armando"] = "Составляем",
	["Armando «Cerrar mis misiones»..."] = "Составляем «Закрыть мои задания»...",
	["Armar la ruta"] = "Составить маршрут",
	["Armar lo que falta"] = "Составить недостающее",
	["Armar mi plan"] = "Составить мой план",
	["Armar un plan nuevo"] = "Составить новый план",
	["Armas"] = "Оружие",
	["Armas a dos manos"] = "Оружие с двуручником",
	["Armas a muerte"] = "Оружие: ва-банк",
	["Armas contra jugadores"] = "Оружие для PvP",
	["Armas para grupo"] = "Оружие для группы",
	["Armas pensado para mazmorras: mucho daño en varios enemigos con Golpes de barrido, Golpe mortal para los jefes y más precisión para no fallar."] = "Оружие для подземелий: много урона по нескольким противникам с Размашистыми ударами, Смертельный удар для боссов и больше меткости, чтобы не промахиваться.",
	["Armas pensando primero en no morir: paras más golpes, frenas a los que huyen y terminas con un poco de Protección para recibir menos daño."] = "Оружие, где главное — не умереть: вы чаще парируете удары, замедляете убегающих и в конце берете немного Защиты, чтобы получать меньше урона.",
	["Armas seguro"] = "Оружие: надежно",
	["Armas, armaduras, materiales, recetas y monturas: quién los suelta y quién los vende."] = "Оружие, доспехи, материалы, рецепты и верховые животные: кто их роняет и кто продает.",
	["Arrastra cada marco de combate adonde te acomode. Cuando termines, fíjalos para que no estorben."] = "Перетащите каждую боевую рамку куда удобно. Когда закончите, закрепите их, чтобы не мешали.",
	["Arrastra otra bolsa aquí para cambiarla."] = "Перетащите сюда другую сумку, чтобы заменить.",
	["Arrastra para mover tus marcos. Cambia el tamaño y las columnas en la página Curación."] = "Перетащите, чтобы передвинуть рамки. Размер и столбцы меняются на странице «Исцеление».",
	["Arrastra para mover tus marcos. Haz clic (con o sin Mayús, Ctrl o Alt) para ver qué lanzaría."] = "Перетаскивайте, чтобы двигать рамки. Щелкните (с Shift, Ctrl, Alt или без них), чтобы увидеть, что будет применено.",
	["Arrastra una bolsa aquí para ponerla."] = "Перетащите сюда сумку, чтобы надеть ее.",
	["Arreglos: «Cerrar mis misiones» vuelve a armar tu ruta, la ayuda de rotación vuelve a decirte qué usar y el mapa ya no muestra rectángulos pegados al acercar."] = "Исправления: «Закрыть мои задания» снова строит маршрут, помощник ротации снова подсказывает, что использовать, а карта при приближении больше не показывает наклеенные прямоугольники.",
	["Arriba de la ventana, cada bolsa equipada con su espacio: pasa el ratón para resaltar lo que lleva y arrastra otra bolsa para cambiarla."] = "Вверху окна — каждая надетая сумка и ее место: наведите курсор, чтобы подсветить содержимое, и перетащите другую сумку, чтобы заменить.",
	["Arriba, lo que Alfa recomienda. Un clic y empiezas."] = "Вверху — то, что рекомендует Alfa. Один щелчок, и вы начинаете.",
	["Arriesgado"] = "Рискованно",
	["Arrodillarse"] = "Преклонить колено",
	["Arrojadiza"] = "Метательное оружие",
	["Arrástralo para moverlo"] = "Перетащите, чтобы передвинуть",
	["Artefacto"] = "Артефакт",
	["Artesano"] = "Искусник",
	["Artesanía y comercio"] = "Ремесло и хозяйственные товары",
	["Arthas mató a Kel'Thuzad en Andorhal, pero después lo revivió como liche con el poder de la Fuente del Sol."] = "Артас убил Кел'Тузада в Андорале, но позже воскресил его личом силой Солнечного Колодца.",
	["Arthas mató al archimago Antonidas en Dalaran, y después Archimonde destruyó la ciudad."] = "Артас убил верховного мага Антонидаса в Даларане, а затем Архимонд уничтожил город.",
	["Arthas purgó Stratholme porque su grano estaba infectado. Esa decisión lo separó para siempre de Uther y de Jaina."] = "Артас очистил Стратхольм, потому что его зерно было заражено. Это решение навсегда отдалило его от Утера и Джайны.",
	["Arthas tomó la espada Agonía de Escarcha en Rasganorte creyendo que salvaría a su pueblo. La espada le robó el alma."] = "Артас взял меч Ледяная Скорбь в Нордсколе, веря, что спасет свой народ. Меч забрал его душу.",
	["Arthas y Jaina se querían antes de que la plaga los separara."] = "Артас и Джайна любили друг друга, пока чума их не разлучила.",
	["Asesinato"] = "Ликвидация",
	["Asesinato para subir"] = "Ликвидация для прокачки",
	["Aspecto"] = "Дух",
	["Astranaar es el pueblo élfico en medio de Vallefresno, en una isla del lago."] = "Астранаар — эльфийский городок в сердце Ясеневого леса, на острове посреди озера.",
	["Asusta a todos los que están cerca: si te asusta, intenta no correr hacia otras celdas."] = "Он пугает всех рядом: если вас напугали, постарайтесь не бежать к другим камерам.",
	["Asusta y duerme a los jugadores: si te asusta, intenta no correr hacia más enemigos."] = "Он пугает и усыпляет игроков: если вас напугали, постарайтесь не бежать к другим противникам.",
	["Así queda tu Alfa"] = "Ваш Alfa готов",
	["Así sabes qué hace cada clic antes de tu próxima pelea."] = "Так вы будете знать, что делает каждый щелчок, еще до следующего боя.",
	["Así se lee tu ayuda de rotación"] = "Как читать помощника ротации",
	["Así se ven tus avisos"] = "Так выглядят ваши оповещения",
	["Así se verán tus marcos. Arrástralos para moverlos y cambia su tamaño abajo, en Marcos. Pulsa Listo cuando termines."] = "Так будут выглядеть ваши рамки. Перетащите их, чтобы переместить, и измените размер ниже, в «Рамках». Нажмите «Готово», когда закончите.",
	["Así se verán tus marcos. Arrástralos para moverlos y cambia su tamaño abajo. Pulsa Listo cuando termines."] = "Так будут выглядеть ваши рамки. Перетаскивайте их, а размер меняйте ниже. Нажмите «Готово», когда закончите.",
	["Así terminó «%s»… ¿Te cuento el final?"] = "Вот чем закончилось «%s»… Рассказать концовку?",
	["Atajos"] = "Быстрый доступ",
	["Ataque de tormenta: mucho daño, cada vez que esté listo."] = "Удар бури: много урона, применяйте при каждой готовности.",
	["Ataques más rápidos después de un crítico."] = "Более быстрые атаки после критического удара.",
	["Atardecer"] = "Закат",
	["Atenuar a quien está lejos"] = "Затемнять тех, кто далеко",
	["Atiesh, el Gran Bastón del Guardián, fue de Medivh. En el Clásico se puede rehacer con fragmentos que caen en Naxxramas."] = "Атиеш, Великий посох Стража, принадлежал Медиву. В классике его можно собрать заново из осколков, которые падают в Наксрамасе.",
	["Atravesar objetos pequeños"] = "Проходить сквозь мелкие объекты",
	["Atronar fuerte: juntas varios monstruos y los frenas a todos."] = "Сильный Удар грома: вы собираете нескольких монстров и замедляете их всех.",
	["Atronar más barato para agarrar varios."] = "Более дешевый Удар грома, чтобы удерживать нескольких.",
	["Atronar más fuerte y barato: agarras a varios enemigos a la vez."] = "Более сильный и дешевый Удар грома: вы удерживаете нескольких противников сразу.",
	["Atrás"] = "Назад",
	["Aturde al tanque con su martillo: mantén la vida del tanque alta."] = "Он оглушает танка молотом: держите здоровье танка высоким.",
	["Aturdes a uno mientras peleas con otro."] = "Вы оглушаете одного, пока сражаетесь с другим.",
	["Aturdes al enemigo más peligroso."] = "Вы оглушаете самого опасного противника.",
	["Aturdimiento a demanda."] = "Оглушение по требованию.",
	["Auberdine es el puerto de los elfos de la noche: de ahí salen barcos a Teldrassil y a los Reinos del Este."] = "Аубердин — порт ночных эльфов: отсюда корабли идут на Тельдрассил и в Восточные королевства.",
	["Aullido al abrir Alfa"] = "Вой при открытии Alfa",
	["Aunque el juego ofrezca la ayuda de Blizzard, sugiere con la prioridad de Alfa para tu clase."] = "Даже если игра предлагает помощника Blizzard, подсказывать по приоритету Alfa для вашего класса.",
	["Aura"] = "Аура",
