	["Crecen hacia"] = "Направление роста",
	["Criaturas de nivel %d a %d"] = "Существа %d–%d уровня",
	["Criaturas raras y tesoros: dónde aparecen y lo que sueltan."] = "Редкие существа и сокровища: где появляются и что роняют.",
	["Cristal"] = "Стекло",
	["Créditos y licencias"] = "Авторы и лицензии",
	["Crítico"] = "Крит",
	["Crítico con hechizos"] = "Крит. эффект заклинаний",
	["Críticos enormes: matas antes de que te curen."] = "Огромные критические удары: вы убиваете раньше, чем противника вылечат.",
	["Críticos más fuertes."] = "Более сильные критические удары.",
	["Críticos un poco más fuertes."] = "Чуть более сильные критические удары.",
	["Ctrl"] = "Ctrl",
	["Cuadro de información"] = "Подсказка",
	["Cualquier criatura de su nivel"] = "Любое существо его уровня",
	["Cualquier habilidad tuya que el juego resalte por un efecto."] = "Любая ваша способность, которую игра подсвечивает из-за эффекта.",
	["Cualquier instructor de pesca te la enseña. Luego compra una caña y unas lombrices: con eso empiezas."] = "Ее обучит любой учитель рыбной ловли. Затем купите удочку и червей — и можно начинать.",
	["Cualquier profesión"] = "Любая профессия",
	["Cualquiera"] = "Любой",
	["Cuando al monstruo le quede poca vida, usa Ejecutar (Alfa te avisa)."] = "Когда у монстра останется мало здоровья, используйте Казнь (Alfa подскажет).",
	["Cuando aprendas %s, también."] = "Когда изучите %s — тоже.",
	["Cuando aprendas %s, te avisa al momento de usarlas."] = "Когда изучите %s, Alfa подскажет, когда их применять.",
	["Cuando aprendes un rango nuevo, un aviso ofrece cambiarlo en tus barras."] = "Когда вы изучаете новый ранг, оповещение предложит заменить его на панелях.",
	["Cuando buscas algo en la subasta, Alfa guarda el precio más bajo que ves."] = "Когда вы что-то ищете на аукционе, Alfa запоминает самую низкую увиденную цену.",
	["Cuando el Pozo de la Eternidad explotó, el gran continente antiguo se partió en pedazos. A eso le llaman la Gran División."] = "Когда взорвался Источник Вечности, древний великий континент раскололся на части. Это называют Расколом.",
	["Cuando el juego termina de cargar, Alfa revisa lo que elegiste aquí y lo vuelve a poner si algo lo cambió. Si después los cambias en el menú del juego, Alfa se queda con lo nuevo."] = "Когда игра заканчивает загрузку, Alfa проверяет ваш выбор здесь и возвращает его, если что-то его изменило. Если потом вы измените настройки в меню игры, Alfa оставит новые.",
	["Cuando entras a una posada o ciudad, y cuando tu XP descansada se acaba."] = "Когда вы входите в таверну или город и когда заканчивается опыт за отдых.",
	["Cuando hay un festival, vale la pena darse una vuelta: casi siempre trae mascotas, ropa o comida que no salen el resto del año."] = "Когда идет праздник, стоит заглянуть: почти всегда там есть питомцы, одежда или еда, которых нет в остальное время года.",
	["Cuando hay varias para elegir, toma la que más te sirve."] = "Если есть из чего выбрать, берет самое полезное для вас.",
	["Cuando huelo salchichas se me olvida todo. Bueno, menos tú."] = "Когда я чую сосиски, я забываю обо всем. Ну, кроме тебя.",
	["Cuando la Legión volvió en la Tercera Guerra, Malfurion y Tyrande hicieron sonar el Cuerno de Cenarius para despertar a los druidas dormidos."] = "Когда Легион вернулся в Третьей войне, Малфурион и Тиранда протрубили в Рог Кенария, чтобы разбудить спящих друидов.",
	["Cuando la meta de ahora de tu plan es un lugar, la flecha lo toma sin que hagas clic."] = "Когда текущая цель плана — место, стрелка берет его без щелчка.",
	["Cuando le baja la vida aturde a todos y corre a su cofre a cambiar de arma: espérenlo, no lo persigan."] = "Когда его здоровье падает, он оглушает всех и бежит к сундуку сменить оружие: ждите его, не преследуйте.",
	["Cuando lleves algo, Alfa te dice si conviene venderlo, subastarlo o transformarlo, y cuánto ganas."] = "Когда у вас что-то есть, Alfa подскажет, выгоднее продать это торговцу, выставить на аукцион или переработать, и сколько вы заработаете.",
	["Cuando los orcos se volvieron brujos, dejaron de oír a los elementos. Thrall les devolvió ese camino."] = "Когда орки стали чернокнижниками, они перестали слышать стихии. Тралл вернул им этот путь.",
	["Cuando otro lobo con Alfa comparta su ubicación, aparece aquí y en tu mapa. Para que la manada crezca, invita a tus amigos: que instalen Alfa, acepten compartir y entren al Discord de La Jauría."] = "Когда другой волк с Alfa поделится местоположением, он появится здесь и на вашей карте. Чтобы стая росла, приглашайте друзей: пусть установят Alfa, согласятся делиться и зайдут в Discord La Jauría.",
	["Cuando se abre una misión de clase para ti, te ofrece su guía."] = "Когда для вас открывается классовое задание, предлагает его гайд.",
	["Cuando se escapa"] = "Когда рыба срывается",
	["Cuando se llenan"] = "Когда заполняются",
	["Cuando te quedes sin maná, cambia a forma felina para terminar la pelea."] = "Когда закончится мана, перейдите в облик кошки, чтобы закончить бой.",
	["Cuando tengas pescado que sepas cocinar, aparece aquí."] = "Когда у вас будет рыба, которую вы умеете готовить, она появится здесь.",
	["Cuando tu paso lo pide y hablas con su posadero. Nunca en otra posada."] = "Когда этого требует шаг и вы говорите с его трактирщиком. Никогда в другой таверне.",
	["Cuando tus bolsas se llenan, Hoy te dice qué puedes vender y cuánto te dan."] = "Когда сумки заполняются, «Сегодня» подскажет, что можно продать и сколько вы получите.",
	["Cuando tú o tu grupo peleen, aquí sale quién hace más daño."] = "Когда вы или ваша группа сражаетесь, здесь видно, кто наносит больше всего урона.",
	["Cuando un elfo de la noche muere, su espíritu toma forma de fuego fatuo y corre más rápido hasta su cuerpo."] = "Когда ночной эльф умирает, его дух принимает облик огонька и быстрее бежит к телу.",
	["Cuando una pieza baja de este porcentaje."] = "Когда прочность вещи опускается ниже этого процента.",
	["Cuando venzas a tu primer jefe, tu progreso aparecerá aquí."] = "Когда вы победите первого босса, здесь появится ваш прогресс.",
	["Cuando ya casi se rompe."] = "Когда вещь вот-вот сломается.",
	["Cuello"] = "Шея",
	["Cuenta:"] = "Учетная запись:",
	["Cuero"] = "Кожа",
	["Cuerpo a cuerpo con tótems y golpes elementales: el chamán que mejor sube."] = "Ближний бой с тотемами и стихийными ударами: шаман, который лучше всех качается.",
	["Cuesta %s."] = "Стоит %s.",
	["Cuestan %s: te alcanza."] = "Стоимость: %s, денег хватает.",
	["Cuestan %s; llevas %s."] = "Стоимость: %s; у вас %s.",
	["Cuidado al nadar mar adentro: en aguas profundas te cansas y te puedes ahogar."] = "Осторожно в открытом море: на глубине ты устаешь и можешь утонуть.",
	["Cuidado con atraer varios a la vez: Fuego no tiene tanto control."] = "Осторожно, не притягивайте нескольких сразу: у Огня не так много контроля.",
	["Cumpliste todas sus metas."] = "Вы выполнили все его цели.",
