	["Cursor"] = "Курсор",
	["Cuándo"] = "Когда",
	["Cuándo vuelve sola detrás de tu personaje."] = "Когда она сама возвращается за спину персонажа.",
	["Cuánta lluvia, nieve y polvo se ve cuando hay mal tiempo."] = "Сколько дождя, снега и пыли видно в непогоду.",
	["Cuántas capas de sombra se dibujan: con más capas, las sombras nítidas llegan más lejos."] = "Сколько слоев теней рисуется: чем больше слоев, тем дальше видны четкие тени.",
	["Cuántas casillas caben en cada fila."] = "Сколько ячеек помещается в ряд.",
	["Cuántas casillas libres quedan cuando Alfa te avisa."] = "Сколько свободных ячеек должно остаться, чтобы Alfa предупредил.",
	["Cuántas habilidades después"] = "Сколько способностей дальше",
	["Cuánto daño quita cada bloqueo; también sube el daño de Embate con escudo."] = "Сколько урона снимает каждый блок; также повышает урон Мощного удара щитом.",
	["Cuánto dura un aviso en pantalla"] = "Сколько оповещение держится на экране",
	["Cuánto falta para tu siguiente golpe automático, con cada mano. Ayuda a meter Embate o Golpe heroico sin perder golpes."] = "Сколько осталось до следующей автоатаки каждой рукой. Помогает вставить Мощный удар или Удар героя без потери ударов.",
	["Cuánto más brillan las luces que en una pantalla normal. El juego no pasa del máximo de tu monitor."] = "Насколько свет ярче, чем на обычном экране. Игра не превысит максимум вашего монитора.",
	["Cuánto oro"] = "Сколько золота",
	["Cuánto pasto, flores y hierbas cubren el suelo."] = "Сколько травы, цветов и растений покрывает землю.",
	["Cuánto se ve el fondo de las ventanas de chat; en cero solo queda el borde."] = "Насколько виден фон окон чата; при нуле остается только рамка.",
	["Cuántos"] = "Сколько",
	["Cuántos consejos"] = "Сколько советов",
