	["Cómprala con un vendedor."] = "Купите у торговца.",
	["DPS"] = "DPS",
	["DPS del arma"] = "DPS оружия",
	["Daga"] = "Кинжал",
	["Dale de comer a tu mascota para que esté contenta y pegue más."] = "Кормите питомца, чтобы он был доволен и бил сильнее.",
	["Dale de comer para que esté feliz: pega más fuerte."] = "Покормите его, чтобы он был счастлив: так он бьет сильнее.",
	["Dar a las barras el estilo de Alfa"] = "Оформить панели в стиле Alfa",
	["Dar al chat el estilo de Alfa"] = "Оформить чат в стиле Alfa",
	["Dar al minimapa el estilo de Alfa"] = "Оформить мини-карту в стиле Alfa",
	["Darnassus está en las ramas de Teldrassil. La suma sacerdotisa Tyrande Susurravientos gobierna desde el Templo de la Luna."] = "Дарнас стоит в ветвях Тельдрассила. Верховная жрица Тиранда Шепот Ветра правит из Храма Луны.",
	["Dath'Remar Caminante del Sol guió a los altos elfos hasta Quel'Thalas. De su linaje viene el príncipe Kael'thas."] = "Дат'Ремар Солнечный Скиталец привел высших эльфов в Кель'Талас. Из его рода происходит принц Кель'тас.",
	["Datos"] = "Данные",
