	["Daño de arcos, armas de fuego y ballestas."] = "Урон луков, огнестрельного оружия и арбалетов.",
	["Daño de fuego con el tiempo."] = "Периодический урон от огня.",
	["Daño del arma"] = "Урон оружия",
	["Daño directo de fuego y sombras: matas antes de que el monstruo llegue."] = "Прямой урон огнем и тьмой: вы убиваете раньше, чем монстр до вас доберется.",
	["Daño directo de tus armas y habilidades."] = "Прямой урон вашего оружия и способностей.",
	["Daño en grupo de cinco: pegar fuerte sin robarle los monstruos al tanque."] = "Урон в группе из пяти: бить сильно, не отбирая монстров у танка.",
	["Daño extra después de recibir críticos."] = "Дополнительный урон после получения критических ударов.",
	["Daño extra después de recibir un golpe crítico."] = "Дополнительный урон после получения критического удара.",
