	["Desde siempre"] = "За все время",
	["Desde tu última visita también hubo cambios en %s: los ves en «Ver todo lo nuevo»."] = "С вашего прошлого визита были изменения и в %s: смотрите их в «Все новое».",
	["Desencanta los objetos verdes y azules que no uses para sacar polvos, esencias y fragmentos."] = "Распыляй ненужные зеленые и синие предметы, чтобы получить пыль, сущности и осколки.",
	["Desencantar ≈ %s"] = "Распылить ≈ %s",
	["Desencantar: ≈ %s por objeto%s. Pide Encantamiento %d."] = "Распыление: ≈ %s за предмет%s. Нужно наложение чар %d.",
	["Deseo de muerte: mucho más daño un rato; úsalo en peleas largas."] = "Жажда смерти: намного больше урона на время; используйте в долгих боях.",
	["Desgarrar hace más daño mientras el monstruo sangra; lo necesitas para Heridas profundas."] = "Кровопускание наносит больше урона, пока монстр истекает кровью; оно нужно для Глубоких ран.",
	["Desgarrar hace más daño; lo necesitas para Heridas profundas."] = "Кровопускание наносит больше урона; оно нужно для Глубоких ран.",
	["Desgarrar te prepara más Abrumar: más golpes que no se pueden esquivar."] = "Кровопускание чаще открывает Превосходство: больше ударов, от которых нельзя уклониться.",
	["Deshacer"] = "Отменить",
	["Deshacer preajuste"] = "Отменить набор",
	["Desmarca las metas hechas de este personaje (las que ya se cumplen se vuelven a marcar solas)."] = "Снимает отметки с выполненных целей этого персонажа (уже выполненные отметятся снова сами).",
	["Desmarcar"] = "Снять отметку",
	["Desollar es de las formas más fáciles de hacer oro mientras subes de nivel."] = "Снятие шкур — один из самых простых способов зарабатывать золото при прокачке.",
	["Desollar y Peletería van de la mano: tú consigues el cuero y tú lo trabajas."] = "Снятие шкур и кожевничество идут рука об руку: ты добываешь кожу, ты же ее и обрабатываешь.",
	["Despojar más rápido"] = "Быстрый сбор добычи",
	["Después"] = "Позже",
	["Después de"] = "После",
	["Después de cada golpe, regresa a tu lugar rápido."] = "После каждого отбрасывания быстро возвращайтесь на место.",
	["Después de estos siguen %d más."] = "Дальше еще %d.",
	["Después de otra"] = "После другого задания",
	["Después de tu segunda pelea, aquí ves la de antes."] = "После второго боя здесь виден предыдущий.",
	["Después de un crítico atacas más rápido: más golpes, más ira."] = "После критического удара вы атакуете быстрее: больше ударов, больше ярости.",
	["Después de él se encienden los braseros del altar y llegan oleadas de enemigos: prepárense antes."] = "После него зажигаются жаровни алтаря и приходят волны противников: подготовьтесь заранее.",
	["Después del combate"] = "После боя",
	["Después del primer jefe, un prisionero de tu facción abre la puerta: háblale."] = "После первого босса пленник вашей фракции открывает дверь: поговорите с ним.",
