	["Devolver"] = "Вернуть",
	["Devolver los avisos a su lugar"] = "Вернуть оповещения на место",
	["Devuelve cada ajuste que Alfa tocó al valor que tenía antes y deja de mantenerlos."] = "Возвращает каждую настройку, которую трогал Alfa, к прежнему значению и перестает их поддерживать.",
	["Devuelve los valores que tenías antes del último preajuste."] = "Возвращает значения, которые были до последнего набора.",
	["Diario"] = "Дневник",
	["Diario de mazmorras"] = "Журнал подземелий",
	["Diario de pesca"] = "Журнал рыбалки",
	["Dibuja el arte completo de cada zona recortado a su forma, con las texturas de detalle incluidas. Sin ellas el mapa sigue completo, solo más suave entre zona y zona."] = "Рисует полное изображение каждой зоны, обрезанное по ее форме, со встроенными детальными текстурами. Без них карта остается целой, просто переходы между зонами мягче.",
	["Dibuja la ruta hasta tu objetivo: por dónde caminar, volar o navegar."] = "Рисует маршрут к цели: где идти, лететь или плыть.",
	["Dice en el chat qué misión perderías y te deja aceptarla a ti."] = "Пишет в чат, какое задание вы потеряете, и оставляет решение вам.",
	["Dicen que el Bosque del Ocaso se oscureció por estar tan cerca de Karazhan, y desde entonces vive en penumbra."] = "Говорят, Сумеречный лес потемнел из-за близости к Каражану и с тех пор живет в полумраке.",
	["Dicen que en Thelsamar venden morcilla. ¡Es casi una salchicha! Solo digo."] = "Говорят, в Телсамаре продают кровяную колбасу. Это почти сосиска! Я просто так сказала.",
	["Diestro"] = "Сноровка",
	["Diez mil años atrás, Illidan creó en la cima de Hyjal un nuevo Pozo de la Eternidad, y sobre él se plantó Nordrassil."] = "Десять тысяч лет назад Иллидан создал на вершине Хиджала новый Источник Вечности, и над ним посадили Нордрассил.",
	["Dinero de toda la cuenta"] = "Деньги всей учетной записи",
	["Dinero de tus personajes"] = "Деньги ваших персонажей",
	["Disciplina"] = "Послушание",
	["Disciplina para subir"] = "Послушание для прокачки",
	["Dispara desde lejos: alguien debe ir por él."] = "Он стреляет издалека: кто-то должен к нему подойти.",
	["Disparo apuntado: tu disparo más fuerte."] = "Прицельный выстрел: ваш самый сильный выстрел.",
	["Disparo arcano: instantáneo, úsalo cuando esté listo."] = "Чародейский выстрел: мгновенный, применяйте, как только готов.",
	["Disponible a nivel %d"] = "Доступно на %d-м уровне",
	["Distancia"] = "Дальний бой",
	["Distancia a la que ciudades, torres y cuevas conservan su detalle."] = "Расстояние, на котором города, башни и пещеры сохраняют детализацию.",
	["Distancia a la que el suelo conserva su forma completa."] = "Расстояние, на котором земля сохраняет полную форму.",
	["Distancia de las placas"] = "Дальность индикаторов здоровья",
	["Distancia de visión"] = "Дальность обзора",
	["Distancia del pasto"] = "Дальность травы",
	["Distancia y velocidad"] = "Расстояние и скорость",
	["Doble clic derecho"] = "Двойной щелчок ПКМ",
	["Doble clic derecho para lanzar"] = "Двойной щелчок ПКМ — забросить",
	["Doble clic mientras pescas vuelve a lanzar"] = "Двойной щелчок во время рыбалки забрасывает снова",
	["Dolanaar es la aldea élfica en el camino a Darnassus; su posada huele a bosque."] = "Доланаар — эльфийская деревня по дороге в Дарнас; в ее таверне пахнет лесом.",
	["Domingo de concurso"] = "Воскресное состязание",
	["Dominio de bestias"] = "Чувство зверя",
	["Dominio de bestias para subir"] = "Чувство зверя для прокачки",
	["Donde antes estaba el Pozo de la Eternidad hoy gira el Maelstrom, un remolino eterno en medio del Gran Mar."] = "Там, где был Источник Вечности, теперь кружит Водоворот — вечная воронка посреди Великого моря.",
	["Donde lo sacas: %s."] = "Где ловится: %s.",
	["Donde puedes seguir en varias zonas, toma la recomendada sin preguntar."] = "Если продолжить можно в нескольких зонах, без вопросов выбирает рекомендуемую.",
	["Dormir"] = "Сон",
	["Dos armas"] = "Два оружия",
	["Dos armas y mucha ira. Furia pega más que Armas cuando tiene buen equipo, y Sed de sangre llega al nivel 40. Necesitas dos armas de una mano desde el nivel 20."] = "Два оружия и много ярости. С хорошей экипировкой Неистовство бьет сильнее, чем Оружие, а Кровожадность приходит на 40 уровне. С 20 уровня вам нужны два одноручных оружия.",
	["Dos clics y Alfa te lleva"] = "Два щелчка, и Alfa отведет вас",
	["Dos manos"] = "Двуручное",
	["Dos monstruos a la vez dejan de ser un problema."] = "Два монстра сразу перестают быть проблемой.",
	["Dos profesiones de recolección: oro constante sin perder tiempo, justo cuando más lo necesitas."] = "Две собирательные профессии: стабильное золото без потери времени, как раз когда оно нужнее всего.",
	["Drek'Thar, el viejo chamán ciego del clan Lobo Gélido, le enseñó a Thrall a hablar con los espíritus. ¡Un sabio de los lobos!"] = "Дрек'Тар, старый слепой шаман клана Северного Волка, научил Тралла говорить с духами. Мудрец среди волков!",
	["Drenar alma al rematar te da uno."] = "«Похищение души» при добивании дает один.",
	["Druida"] = "Друид",
	["Druidas, guerreros y pícaros: si tu barra de forma o de actitud está vacía, Alfa te avisa y la llena con un clic."] = "Друиды, воины и разбойники: если панель облика или стойки пуста, Alfa предупредит вас и заполнит ее одним щелчком.",
	["Duelos"] = "Дуэли",
	["Duerme a un jugador y lanza sombras: interrúmpelo."] = "Он усыпляет игрока и применяет темную магию: прерывайте его.",
	["Dun Algaz es el túnel enano que une Los Humedales con Loch Modan."] = "Дун Альгаз — дворфийский туннель между Болотиной и Лок Моданом.",
	["Duplicar"] = "Дублировать",
	["Durabilidad"] = "Прочность",
	["Duración"] = "Длительность",
	["Durante la pelea despierta a guardianes de piedra: alguien debe tanquearlos o mátenlos rápido."] = "Во время боя он пробуждает каменных стражей: кто-то должен их танковать, или убейте их быстро.",
	["Durante siglos los druidas durmieron en el Sueño Esmeralda mientras las Centinelas cuidaban el bosque."] = "Веками друиды спали в Изумрудном Сне, пока Часовые охраняли лес.",
	["Durotan y su clan Lobo Gélido se negaron a beber la sangre de Mannoroth. Gul'dan nunca se lo perdonó."] = "Дуротан и его клан Северного Волка отказались пить кровь Маннорота. Гул'дан так этого и не простил.",
	["Durotar lleva el nombre de Durotan, el padre de Thrall y jefe del clan Lobo Gélido. Thrall honró su memoria al nombrar así la tierra de los orcos."] = "Дуротар назван в честь Дуротана, отца Тралла и вождя клана Северного Волка. Тралл почтил его память, дав это имя земле орков.",
	["Dónde"] = "Где",
	["Dónde aprender Pesca y sus rangos. Se llenan al abrir la guía de pesca."] = "Где изучить рыбную ловлю и ее ступени. Заполняется, когда вы открываете гайд по рыбалке.",
	["Dónde empieza el paisaje lejano simplificado."] = "Где начинается упрощенный дальний пейзаж.",
	["Dónde entregar"] = "Где сдавать",
	["Dónde está"] = "Где находится",
	["Dónde está cada uno, lo que vende, lo que suelta y sus misiones."] = "Где находится каждый, что продает, что роняет и его задания.",
	["Dónde mandarlo"] = "Куда отправить",
	["Dónde sale"] = "Где добыть",
	["Dónde se entrega"] = "Где сдавать",
	["Dónde se ven"] = "Где показывать",
	["Editar"] = "Изменить",
	["Edwin VanCleef, el jefe Defias, era maestro cantero. Cuando la nobleza no pagó la reconstrucción de Ventormenta, juró venganza."] = "Эдвин ван Клиф, главарь Братства Справедливости, был мастером-каменщиком. Когда знать не заплатила за восстановление Штормграда, он поклялся отомстить.",
	["Efecto activo"] = "Активный эффект",
	["Efecto del vacío"] = "Эффект Пустоты",
	["Efectos"] = "Эффекты",
	["Efectos de pantalla del juego"] = "Экранные эффекты игры",
	["Ej.: Comprar bolsas de 10 casillas"] = "Напр.: Купить сумки на 10 ячеек",
	["Ejecutar cuesta menos ira: rematas antes."] = "Казнь стоит меньше ярости: вы добиваете раньше.",
	["Ejecutar más barato para rematar jefes."] = "Более дешевая Казнь, чтобы добивать боссов.",
	["El Alba Argenta pelea contra la Plaga sin el fanatismo de los Escarlatas, y recibe por igual a la Alianza y a la Horda."] = "Серебряный Рассвет сражается с Плетью без фанатизма Алого ордена и одинаково принимает Альянс и Орду.",
	["El Bastión Plumaluna, en una isla frente a la costa, es el puesto de las centinelas élficas."] = "Крепость Оперенной Луны на острове у побережья — застава эльфийских часовых.",
	["El Bosque del Ocaso y las Montañas Crestagrana también son tierras del reino, y piden ayuda porque los soldados no alcanzan."] = "Сумеречный лес и Красногорье — тоже земли королевства, и они просят помощи, потому что солдат не хватает.",
	["El Campamento Mojache es el hogar de la Horda en Feralas."] = "Лагерь Мохаче — дом Орды в Фераласе.",
	["El Castillo de Colmillo Oscuro fue de Arugal, un mago de Dalaran que convocó a los worgen para pelear contra la Plaga y terminó perdiendo la razón."] = "Крепость Темного Клыка принадлежала Аругалу, магу из Даларана, который призвал воргенов против Плети и в итоге лишился рассудка.",
	["El Claro de la Luna es un santuario de druidas; ahí se reúne el Círculo Cenarion."] = "Лунная поляна — святилище друидов; здесь собирается Круг Кенария.",
	["El Codex no sabe de dónde sale; si ya la tienes, la ves en tu diario de monturas."] = "Codex не знает, откуда он берется; если он у вас уже есть, он виден в журнале транспорта.",
	["El Cruce es un puesto de la Horda justo en medio de Los Baldíos, donde se juntan los caminos principales. De ahí su nombre."] = "Перекресток — застава Орды прямо посреди Степей, где сходятся главные дороги. Отсюда и название.",
	["El Culto de los Malditos lo fundó Kel'Thuzad: les prometía a los campesinos de Lordaeron una vida eterna y más justa."] = "Культ Проклятых основал Кел'Тузад: он обещал крестьянам Лордерона вечную и более справедливую жизнь.",
	["El Discord de La Jauría"] = "Discord La Jauría",
	["El Fuerte Cenarion es la base del Círculo Cenarion en Silithus, frente a los qiraji."] = "Крепость Кенария — база Круга Кенария в Силитусе, напротив киражей.",
	["El Gran Manitas Gelbin Mekkatorque es el líder de los gnomos."] = "Главный механик Гельбин Меккаторк — лидер гномов.",
	["El Guardián Remulos, hijo de Cenarius, cuida el Claro de la Luna desde su santuario."] = "Хранитель Ремул, сын Кенария, оберегает Лунную поляну из своего святилища.",
	["El Horado Rajacieno y la Zahúrda Rajacieno son guaridas de los jabaespines, entre Los Baldíos y Las Mil Agujas."] = "Лабиринты Иглошкурых и Курганы Иглошкурых — логова свинобразов между Степями и Тысячей Игл.",
	["El Legado se abre con tu primer punto (casi siempre, al llegar a nivel 25), con la tecla Y o con su botón del menú."] = "«Наследие» открывается с первым очком (почти всегда на 25-м уровне), клавишей Y или кнопкой в меню.",
	["El Loto negro crece solo en zonas de nivel muy alto, y es tan raro que vale una fortuna."] = "Черный лотос растет только в зонах очень высокого уровня и так редок, что стоит целое состояние.",
	["El Loto negro es rarísimo: crece en Cuna del Invierno, las Estepas Ardientes, las Tierras de la Peste del Este y Silithus."] = "Черный лотос — большая редкость: он растет в Зимних Ключах, Пылающих степях, Восточных Чумных землях и Силитусе.",
	["El Martillo Crepuscular tiene campamentos en Silithus, donde intenta invocar a los señores elementales."] = "У Сумеречного Молота есть лагеря в Силитусе, где они пытаются призвать повелителей стихий.",
	["El Núcleo de Magma, en el fondo de la Montaña Roca Negra, es el hogar de Ragnaros, el Señor del Fuego."] = "Огненные Недра в глубине Черной горы — дом Рагнароса, Повелителя Огня.",
	["El Paso de la Muerte no tiene ni un pueblo: solo ogros, bestias y la sombra de Karazhan."] = "На Перевале Мертвого Ветра нет ни одного поселения: только огры, звери и тень Каражана.",
	["El Paso de la Muerte une el Bosque del Ocaso con el Pantano de las Penas."] = "Перевал Мертвого Ветра соединяет Сумеречный лес с Болотом Печали.",
	["El Portal Oscuro está apagado en el Clásico. En Burning Crusade vuelve a abrirse rumbo a Terrallende."] = "В классике Темный портал не действует. В Burning Crusade он снова откроется — в Запределье.",
	["El Portal Oscuro lo abrieron Medivh y Gul'dan juntos, cada uno desde su lado."] = "Темный портал открыли Медив и Гул'дан вместе, каждый со своей стороны.",
	["El Puente Thandol, al norte, une Khaz Modan con Arathi; los Hierro Negro lo dejaron medio destruido."] = "Мост Тандола на севере соединяет Каз Модан с Нагорьем Арати; дворфы Черного Железа оставили его полуразрушенным.",
	["El Puerto de Menethil lleva el apellido de la familia real de Lordaeron. De ahí salen barcos a Theramore y a Auberdine."] = "Гавань Менетилов носит имя королевской семьи Лордерона. Отсюда корабли идут в Терамор и Аубердин.",
	["El Puesto Hachazo es el campamento de la Horda que tala Vallefresno."] = "Застава Расщепленного Дерева — лагерь Орды, который вырубает Ясеневый лес.",
	["El Refugio Roca del Sol es el hogar de los tauren en estas montañas."] = "Приют Солнечного Камня — дом тауренов в этих горах.",
	["El Refugio de la Zaga es el campamento de la Alianza en Arathi, entre ruinas, trols y ogros."] = "Опорный пункт — лагерь Альянса в Нагорье Арати, среди руин, троллей и огров.",
	["El Refugio del Mariscal es el único campamento del cráter, y lo comparten todos."] = "Убежище Маршалла — единственный лагерь в кратере, и он общий для всех.",
	["El SI:7 de Ventormenta y Ravenholdt son nombres que todo pícaro conoce."] = "ШРУ:7 из Штормграда и Черный Ворон — имена, которые знает каждый разбойник.",
	["El Sepulcro es el puesto de los Renegados en el bosque; desde ahí vigilan a los worgen y a los magos de Dalaran."] = "Гробница — застава Отрекшихся в лесу; отсюда они следят за воргенами и магами Даларана.",
	["El Sindicato, los nobles caídos de Alterac, también asalta caminos y granjas por estas tierras."] = "Синдикат, павшая знать Альтерака, тоже грабит дороги и фермы в этих краях.",
	["El Sueño Esmeralda se está volviendo pesadilla: algo corrompe a los dragones verdes que lo cuidan."] = "Изумрудный Сон превращается в кошмар: что-то оскверняет охраняющих его зеленых драконов.",
	["El Tranvía Subterráneo une Forjaz con Ventormenta por debajo de la tierra. Lo construyeron los gnomos."] = "Подземный поезд соединяет Стальгорн и Штормград под землей. Его построили гномы.",
	["El Trono Helado es la armadura de hielo donde quedó atrapado Ner'zhul, en lo alto de la Corona de Hielo."] = "Ледяной Трон — ледяная броня, в которой заточен Нер'зул, на вершине Ледяной Короны.",
	["El Valle Calcinado, al sur de la sierra, quedó quemado y lleno de elementales de fuego."] = "Обугленная долина к югу от гор выжжена и полна огненных элементалей.",
	["El Vigía de Morgan es el puesto de la Alianza en las estepas, desde donde vigilan la Montaña Roca Negra."] = "Застава Моргана — аванпост Альянса в степях, откуда следят за Черной горой.",
	["El aguante es tu mejor amigo: más vida para más Transfusión de vida."] = "Выносливость — ваш лучший друг: больше здоровья для большего числа Жизнеотводов.",
	["El almirante Daelin Valiente, padre de Jaina, cayó en Theramore tras atacar a la Horda. Su hija eligió la paz."] = "Адмирал Делин Праудмур, отец Джайны, погиб у Терамора, напав на Орду. Его дочь выбрала мир.",
	["El archidruida Fandral Corzocelada enseña en el Enclave Cenarion de Darnassus."] = "Верховный друид Фэндрал Олений Шлем учит в Анклаве Кенария в Дарнасе.",
	["El archidruida Fandral Corzocelada plantó Teldrassil con la esperanza de recuperar la inmortalidad que los elfos perdieron en el Monte Hyjal."] = "Верховный друид Фэндрал Олений Шлем посадил Тельдрассил в надежде вернуть бессмертие, которое эльфы потеряли у горы Хиджал.",
	["El archidruida Hamuul Tótem de Runa enseña a los druidas tauren, y fue de los primeros tauren aceptados en el Círculo Cenarion."] = "Верховный друид Хамуул Рунический Тотем учит друидов-тауренов; он был одним из первых тауренов, принятых в Круг Кенария.",
	["El arma principal debe ser la más lenta y fuerte; la secundaria, la más rápida."] = "Оружие в правой руке должно быть самым медленным и сильным, а в левой — самым быстрым.",
	["El aro y la cabecera del minimapa con tu estilo."] = "Кольцо и заголовок мини-карты в вашем стиле.",
	["El banco está lleno: compra otra casilla o pon una bolsa más grande en el banco."] = "Банк заполнен: купите еще ячейку или положите в банк сумку побольше.",
	["El barco goblin une Bahía del Botín con Trinquete, y lo pueden usar los dos bandos."] = "Гоблинский корабль соединяет Пиратскую Бухту с Кабестаном, и им могут пользоваться обе фракции.",
	["El barón Osahendido manda en Stratholme como caballero de la muerte de la Plaga."] = "Барон Ривендер правит Стратхольмом как рыцарь смерти Плети.",
	["El blanco de la interfaz y del cielo de día."] = "Белый цвет интерфейса и дневного неба.",
	["El bonus de tu arma al máximo."] = "Бонус вашего оружия на максимуме.",
	["El borde del minimapa, redondo o cuadrado («Minimapa cuadrado», arriba), y la barra con la zona y la hora toman el estilo que elijas, como la ventana del mapa. Al apagarlo vuelve el de siempre."] = "Рамка мини-карты, круглая или квадратная («Квадратная мини-карта» выше), и панель с зоной и временем принимают выбранный стиль, как окно карты. Если выключить — вернется обычная.",
	["El borde toma el color del perjuicio (magia, maldición, enfermedad o veneno) cuando tú lo puedes quitar."] = "Рамка окрашивается в цвет отрицательного эффекта (магия, проклятие, болезнь или яд), если вы можете его снять.",
	["El botón «Escanear con Alfa» bajo la ventana de la subasta."] = "Кнопка «Сканировать с Alfa» под окном аукциона.",
	["El brillo más alto que da tu monitor; viene en su caja o su ficha."] = "Максимальная яркость вашего монитора; она указана на коробке или в характеристиках.",
	["El brillo suave de luces y cielo en toda la pantalla."] = "Мягкое свечение огней и неба по всему экрану.",
	["El brujo Zalazane les robó las Islas del Eco a los Lanza Negra con su vudú."] = "Колдун Залазан своим вуду отнял Острова Эха у племени Черного Копья.",
	["El buscador de Ajustes ya encuentra todo: también Pesca, Comercio, Ruta, Bolsas, Combate, Curación, Lya y Estilo y sonido."] = "Поиск по настройкам теперь находит всё: и Рыбалку, и Торговлю, и Маршрут, Сумки, Бой, Лечение, Лию, Стиль и звук.",
	["El buscador del motor está apagado (Ajustes > Descubrir): enciéndelo para que Alfa arme guías."] = "«Поиск» движка выключен (Настройки > Открытия): включите его, чтобы Alfa составлял гайды.",
	["El buscador no está disponible."] = "Поиск недоступен.",
	["El camino a Entrañas pasa por las ruinas de la Ciudad Capital de Lordaeron, donde Arthas mató a su padre."] = "Путь в Подгород лежит через руины столицы Лордерона, где Артас убил своего отца.",
	["El camino a la meta en el mapa del mundo y el minimapa: una línea o puntos donde caminas, líneas donde vuelas, navegas o montas, y los tramos que siguen más tenues."] = "Путь к цели на карте мира и мини-карте: линия или точки — где идти пешком, линии — где лететь, плыть или ехать; последующие участки бледнее.",
	["El camino en el mapa y el minimapa"] = "Путь на карте и мини-карте",
	["El camino hasta el destino dibujado en el mapa."] = "Путь до цели, нарисованный на карте.",
	["El camino más sencillo para subir: un arma grande, golpes que hacen sangrar y Golpe mortal al nivel 40. Aguantas bien y matas rápido."] = "Самый простой путь прокачки: большое оружие, удары с кровотечением и Смертельный удар на 40 уровне. Вы хорошо держитесь и быстро убиваете.",
	["El camino que baja de la sierra hacia Los Baldíos está lleno de arañas. ¡Brrr!"] = "Дорога с гор в Степи кишит пауками. Бррр!",
	["El chat"] = "Чат",
	["El chat usa la letra de Alfa (la de Ajustes > Apariencia). El tamaño se sigue cambiando en el menú de la pestaña."] = "Чат использует шрифт Alfa (из Настройки > Внешний вид). Размер по-прежнему меняется в меню вкладки.",
	["El clan"] = "Клан",
	["El clan Lobo Gélido monta lobos de verdad. Por eso es mi clan favorito, no lo voy a negar."] = "Клан Северного Волка ездит на настоящих волках. Поэтому это мой любимый клан, не стану скрывать.",
	["El clan Lobo Gélido vive exiliado en el valle de Alterac. Thrall, hijo de su antiguo jefe, los encontró ahí después de escapar de Durnholde."] = "Клан Северного Волка живет в изгнании в Альтеракской долине. Тралл, сын их бывшего вождя, нашел их там после побега из Дарнхольда.",
	["El clic derecho solo sigue alejando el mapa del juego, como siempre."] = "Обычный правый щелчок, как всегда, отдаляет карту игры.",
	["El clic izquierdo solo selecciona"] = "Левый щелчок только выбирает цель",
	["El clásico para pelear contra jugadores: Golpe mortal corta las curas del rival, Seccionar mejorado lo deja quieto y Cargar mejorado te da ira para empezar."] = "Классика для боя с игроками: Смертельный удар режет исцеление противника, Улучшенное подрезание сухожилий не дает ему двигаться, а Улучшенный рывок дает ярость для начала.",
	["El color de mi clase"] = "Цвет моего класса",
	["El comerciante no lo compra"] = "Торговец это не покупает",
	["El contenido va en una columna centrada y se acomoda solo si cambias la resolución o la escala."] = "Содержимое идет по центру одной колонкой и само подстраивается, если вы меняете разрешение или масштаб.",
	["El corcho quedó lejos · relanza con %s"] = "Поплавок упал далеко · перезабросьте: %s",
	["El corcho quedó lejos · vuelve a lanzar"] = "Поплавок упал далеко · забросьте снова",
	["El cuadro del jugador al pasar el ratón. En combate no sale, para no estorbar."] = "Подсказка игрока при наведении. В бою не показывается, чтобы не мешать.",
	["El cártel Bonvapor controla Bahía del Botín, Trinquete, Gadgetzan y Vista Eterna. Por eso esos puertos reciben a todos."] = "Картель Хитрой Шестеренки заправляет Пиратской Бухтой, Кабестаном, Прибамбасском и Круговзором. Поэтому эти порты принимают всех.",
	["El daño por segundo de tu arma a distancia."] = "Урон в секунду вашего оружия дальнего боя.",
	["El daño por segundo del arma: para el guerrero, lo que más cuenta al subir."] = "Урон оружия в секунду: для воина это важнее всего при прокачке.",
	["El de tu juego"] = "Как в игре",
	["El demosaurio es el gran depredador del cráter: si oyes pasos que retumban, escóndete."] = "Дьявозавр — главный хищник кратера: если слышишь грохочущие шаги, прячься.",
	["El destino de la flecha y sus zonas en el minimapa."] = "Цель стрелки и ее области на мини-карте.",
	["El destino de la flecha, su camino y las otras metas del paso, en el mapa."] = "Цель стрелки, путь к ней и другие цели шага на карте.",
	["El diario de mazmorras del motor está apagado (Ajustes > Descubrir > Mazmorras)."] = "Журнал подземелий движка выключен (Настройки > Открытия > Подземелья).",
	["El diario de mazmorras está apagado"] = "Журнал подземелий выключен",
	["El dragón azul Azuregos ronda Azshara, cuidando la magia antigua que quedó en sus ruinas."] = "Синий дракон Азурегос бродит по Азшаре, охраняя древнюю магию, оставшуюся в ее руинах.",
	["El druida hace de todo: puedes tanquear, curar o pegar según lo que pida el grupo."] = "Друид умеет все: можно танковать, лечить или наносить урон — смотря что нужно группе.",
	["El emperador Dagran Thaurissan gobierna la Ciudad de Hierro Negro, en las Profundidades de Roca Negra."] = "Император Дагран Тауриссан правит городом Черного Железа в Глубинах Черной горы.",
	["El enemigo esquivó: Abrumar no se puede esquivar y pega fuerte."] = "Противник уклонился: от Превосходства нельзя уклониться, и оно бьет сильно.",
	["El enemigo esquivó: este golpe cuerpo a cuerpo está listo."] = "Противник уклонился: этот удар ближнего боя готов.",
	["El enemigo esquivó: este golpe está listo."] = "Противник уклонился: этот удар готов.",
	["El enemigo está encima: golpéalo cuerpo a cuerpo."] = "Противник вплотную: бейте его в ближнем бою.",
	["El enemigo está lanzando un hechizo: Choque de tierra lo corta."] = "Противник читает заклинание: Земной шок прервет его.",
	["El enemigo está lanzando un hechizo: aturdirlo lo corta."] = "Противник читает заклинание: оглушение прервет его.",
	["El enemigo está lanzando un hechizo: córtalo con tu escudo."] = "Противник читает заклинание: прервите его щитом.",
	["El enemigo está lanzando un hechizo: córtalo."] = "Противник читает заклинание: прервите его.",
	["El enemigo está lanzando un hechizo: el golpe lo corta."] = "Противник читает заклинание: удар прервет его.",
	["El enemigo está por caer: drénale el alma y gana un fragmento."] = "Противник вот-вот падет: похитьте его душу и получите осколок.",
	["El enlace del Discord ya está elegido: cópialo con Ctrl+C y pégalo en tu navegador."] = "Ссылка на Discord выделена: скопируйте её Ctrl+C и вставьте в браузер.",
	["El entrenador de oficio más cercano"] = "Ближайший учитель профессии",
	["El espíritu te devuelve maná rápido: descansas muy poco."] = "Дух быстро восполняет ману: вы почти не отдыхаете.",
	["El estilo del mapa (terreno como el minimapa, o el arte clásico) y las opciones de Mundo."] = "Стиль карты (рельеф как на мини-карте или классический рисунок) и настройки мира.",
	["El estilo que elegiste también puede vestir el chat, el minimapa, las barras de abajo y el mapa. Se apaga cuando quieras y todo vuelve a como estaba."] = "Выбранный стиль может оформить и чат, мини-карту, нижние панели и карту. Его можно выключить в любой момент — и все вернется как было.",
	["El final"] = "Концовка",
	["El final de cada misión"] = "Концовка каждого задания",
	["El final lo verás al entregarla."] = "Концовку вы увидите, когда сдадите задание.",
	["El fondo se ve deformado a través del agua."] = "Дно сквозь воду выглядит искаженным.",
	["El fuego pega a todos los de cerca: mantén la vida alta de quienes pelean cuerpo a cuerpo."] = "Огонь бьет всех рядом: держите высоким здоровье бойцов ближнего боя.",
	["El general Drakkisath guarda la entrada a la Guarida Alanegra, en lo alto de la Cumbre de Roca Negra."] = "Генерал Драккисат охраняет вход в Логово Крыла Тьмы на вершине пика Черной горы.",
	["El gran cruzado de la Cruzada Escarlata, Saidan Dathrohan, es en realidad el demonio Balnazzar. Lo encuentras en Stratholme."] = "Великий воитель Алого ордена Сайдан Датрохан на самом деле демон Бальназзар. Он ждет тебя в Стратхольме.",
	["El guerrero que más daño hace en mazmorras. Con un tanque delante, tus dos armas no paran, y Ejecutar mejorado remata a los jefes."] = "Воин с самым большим уроном в подземельях. С танком впереди ваши два оружия не останавливаются, а Улучшенная казнь добивает боссов.",
	["El hacha de Grom Grito Infernal tiene nombre propio, y dicen que aúlla cuando corta el aire. ¡Aullar es cosa seria!"] = "У топора Грома Адского Крика есть собственное имя, и говорят, он воет, рассекая воздух. Вой — дело серьезное!",
	["El hierro negro solo se funde en la Forja Negra de las Profundidades de Roca Negra."] = "Черное железо плавят только в Черной Кузне в Глубинах Черной горы.",
	["El hijo de Cairne, Baine, cuida el poblado Pezuña de Sangre en Mulgore."] = "Сын Кэрна, Бейн, оберегает деревню Кровавого Копыта в Мулгоре.",
	["El idioma, el estilo, lo que Alfa hace sola por ti y La Jauría, con «Cambiar» en cada cosa. También con /alfa bienvenida."] = "Язык, стиль, что Alfa делает за вас и La Jauría — с кнопкой «Сменить» у каждого пункта. Также командой /alfa bienvenida.",
	["El izquierdo selecciona y el derecho abre el menú."] = "Левая выбирает цель, правая открывает меню.",
	["El izquierdo selecciona y el derecho abre el menú. Tus buffs para otros se suman aquí al aprenderlos."] = "Левая выбирает цель, правая открывает меню. Ваши баффы для других появятся здесь, когда вы их изучите.",
	["El izquierdo selecciona y el derecho abre el menú. Tú eliges el resto."] = "Левая выбирает цель, правая открывает меню. Остальное выбираете вы.",
	["El izquierdo selecciona y el derecho abre el menú: lo básico, porque tu clase no lanza hechizos sobre sus compañeros."] = "Левая выбирает цель, правая открывает меню: только основное, ведь ваш класс не применяет заклинания к союзникам.",
	["El juego elige entre estas según la situación; el ícono te muestra cuál conviene ahora."] = "Игра выбирает между ними по ситуации; значок показывает, какую лучше применить сейчас.",
	["El juego la hizo brillar: es buen momento para usarla."] = "Игра подсветила ее: самое время применить.",
	["El juego manda la imagen en HDR."] = "Игра выводит изображение в HDR.",
	["El juego no aceptó el lote."] = "Игра не приняла партию.",
	["El juego no aceptó esa tecla."] = "Игра не приняла эту клавишу.",
	["El juego no aceptó la prueba."] = "Игра не приняла проверку.",
	["El juego no da tu posición aquí (en una instancia, por ejemplo)."] = "Игра не сообщает здесь ваше положение (например, в подземелье).",
	["El juego no deja cambiar talentos ahora mismo"] = "Игра сейчас не позволяет менять таланты",
	["El juego no deja cocinar desde aquí."] = "Игра не позволяет готовить отсюда.",
	["El juego no deja enviar mensajes en este momento (un encuentro o una partida). Tu rastro vuelve a salir solo cuando termine."] = "Сейчас игра не позволяет отправлять сообщения (бой с боссом или матч). Ваш след снова начнет передаваться сам, когда все закончится.",
	["El juego no deja que las cuentas de prueba envíen mensajes de addon ni usen canales propios. Tu grupo sí se ve."] = "Игра не позволяет пробным учетным записям отправлять сообщения аддонов и пользоваться своими каналами. Ваша группа все равно видна.",
	["El juego no dejó cambiar las demás."] = "Игра не позволила изменить остальные.",
	["El juego no dejó compartir el marcador ahora. Prueba en un momento."] = "Сейчас игра не позволила поделиться маркером. Попробуйте чуть позже.",
	["El juego no dejó comprar ese rango."] = "Игра не позволила изучить этот ранг.",
	["El juego no dejó entrar al canal oculto de Alfa y, sin hermandad, no hay otro camino para compartir. Alfa lo vuelve a intentar sola en unos minutos. Tu grupo sí se ve."] = "Игра не пустила в скрытый канал Alfa, а без гильдии другого способа делиться нет. Alfa сам попробует снова через несколько минут. Ваша группа все равно видна.",
	["El juego no dice si la tienes"] = "Игра не сообщает, есть ли он у вас",
	["El juego no dio tus puntos todavía: se ven desde que ganas el primero."] = "Игра еще не выдала ваши очки: они видны с момента, как вы заработаете первое.",
	["El juego no la ofrece ahora mismo."] = "Сейчас игра ее не предлагает.",
	["El juego no lo dice ahora."] = "Игра сейчас этого не сообщает.",
	["El juego no permite usar el medidor ahora."] = "Сейчас игра не позволяет использовать измеритель.",
	["El juego no trae la ayuda de Blizzard, así que Alfa sugiere con su prioridad para %s, leyendo solo tu personaje: tu recurso, tus efectos y lo que el juego te deja usar. Con 3 o más enemigos cambia a las de área. Tú decides qué presionar."] = "В игре нет помощника Blizzard, поэтому Alfa подсказывает по своему приоритету (%s), читая только вашего персонажа: ресурс, эффекты и то, что игра позволяет применить. При 3 противниках и больше переключается на способности по области. Что нажимать, решаете вы.",
	["El juego oculta los números exactos mientras peleas: la barra y la cifra se ven, el detalle al salir de combate."] = "Во время боя игра скрывает точные числа: полоса и цифра видны, подробности — после выхода из боя.",
	["El juego rechazó confirmar los cambios. Se deshicieron para que tu árbol quede como estaba."] = "Игра отказалась подтвердить изменения. Они отменены, и ваше дерево осталось как было.",
	["El juego solo deja cambiarla fuera de combate."] = "Игра позволяет изменить это только вне боя.",
	["El juego todavía no carga tu árbol"] = "Игра еще не загрузила ваше дерево",
	["El juego todavía no carga tu árbol."] = "Игра еще не загрузила ваше дерево.",
	["El juego todavía no cargó tus talentos. Espera unos segundos o abre la ventana de talentos (tecla N) una vez."] = "Игра еще не загрузила ваши таланты. Подождите несколько секунд или откройте окно талантов (клавиша N) один раз.",
	["El juego todavía no dio la lista de retos: ábrelo con la tecla Y."] = "Игра еще не выдала список испытаний: откройте его клавишей Y.",
	["El juego todavía no la abre: se abre con tu primer punto del Legado (casi siempre, al llegar a nivel 25)."] = "Игра его пока не открывает: оно откроется с вашим первым очком «Наследия» (почти всегда на 25-м уровне).",
	["El juego todavía no tiene los datos de algunos objetos. En un momento aparecen."] = "У игры пока нет данных о некоторых предметах. Они появятся через мгновение.",
	["El juego todavía oculta los números o los nombres (pasa en combate y dentro de mazmorras). Inténtalo al salir."] = "Игра все еще скрывает числа или имена (так бывает в бою и в подземельях). Попробуйте после выхода.",
	["El lago Lordamere separa el Bosque de Argénteos de las Laderas de Trabalomas y de las Montañas de Alterac."] = "Озеро Лордамир отделяет Серебряный бор от Предгорий Хилсбрада и Альтеракских гор.",
	["El lago de Loch Modan existe gracias a una enorme presa enana. Si se rompiera, el agua arrasaría las tierras de abajo."] = "Озеро Лок Модана существует благодаря огромной дворфийской плотине. Если она прорвется, вода смоет земли внизу.",
	["El lago del Claro de la Luna se llama Elune'ara, en honor a la diosa de la luna."] = "Озеро на Лунной поляне называется Элуна'ара — в честь богини луны.",
	["El lago helado de Kel'Theril guarda ruinas de los Altonato."] = "Замерзшее озеро Кел'Терил хранит руины высокорожденных.",
	["El lobo de la intro aúlla de pie sobre la peña, con un aullido largo que otro lobo contesta; y al entrar, Lya llega corriendo a decirte que te extrañó."] = "Волк в заставке воет стоя на скале — долгий вой, на который отвечает другой волк; а когда ты входишь в игру, Lya прибегает и говорит, что скучала по тебе.",
	["El lobo te recibe al entrar"] = "Волк встречает вас при входе",
	["El lobo te recibe cada vez que entras al juego, redibujado: cabeza, orejas y hocico de lobo de verdad."] = "Волк встречает вас при каждом входе в игру — перерисованный: голова, уши и морда настоящего волка.",
	["El maestro de vuelo, la posada, reparar, el banco y más, con la flecha."] = "Распорядитель полетов, таверна, ремонт, банк и другое — со стрелкой.",
	["El maestro de vuelo, la posada, reparar, el banco y más: el más cercano, con la flecha y la ruta."] = "Распорядитель полетов, таверна, ремонт, банк и другое: ближайший, со стрелкой и маршрутом.",
	["El maestro de vuelo, la posada, reparar, el banco... el más cercano (/alfa cerca ayuda)."] = "Распорядитель полетов, таверна, ремонт, банк... ближайший (/alfa cerca ayuda).",
	["El mago Rhonin y el dragón Korialstrasz ayudaron a liberar a Alexstrasza en Grim Batol, y ahí quedó destruida el Alma de Demonio."] = "Маг Ронин и дракон Кориалстраз помогли освободить Алекстразу в Грим Батоле, и там же была уничтожена Душа Демона.",
	["El mago que más daño hace: hechizos de fuego y críticos que queman."] = "Маг с самым большим уроном: огненные заклинания и обжигающие критические удары.",
	["El mapa a tu gusto"] = "Карта на ваш вкус",
	["El mapa abre sin errores con M y se arrastra suave, aunque empieces encima de un ícono."] = "Карта открывается по M без ошибок и плавно перетаскивается, даже если начать над значком.",
	["El mapa de Alfa"] = "Карта Alfa",
	["El mapa de Alfa muestra el terreno real, con puntos de vuelo, mazmorras, barcos, zepelines y portales."] = "Карта Alfa показывает настоящий рельеф с точками полетов, подземельями, кораблями, дирижаблями и порталами.",
	["El mapa de Alfa, el del juego y el minimapa. Si algo te estorba, apágalo aquí; los otros módulos de Alfa agregan sus capas a esta misma lista."] = "Карта Alfa, карта игры и мини-карта. Если что-то мешает, выключите здесь; другие модули Alfa добавляют свои слои в этот же список.",
	["El mapa del mundo entero con zoom, tus marcadores y un solo control para todo lo que se pinta."] = "Карта всего мира с масштабом, вашими маркерами и одним переключателем для всего, что на ней рисуется.",
	["El mapa no se abre en combate."] = "Карта не открывается в бою.",
	["El mapa se ve más limpio: sin líneas finas entre sus pedazos ni halos oscuros en las orillas de las zonas."] = "Карта стала чище: никаких тонких линий между её частями и тёмных ореолов по краям зон.",
	["El mar paga"] = "Море платит",
	["El marco de las barras de experiencia y reputación; el relleno conserva sus colores."] = "Рамка полос опыта и репутации; заполнение сохраняет свои цвета.",
	["El marco del menú del juego y de las bolsas, abajo a la derecha."] = "Рамка меню игры и сумок, внизу справа.",
	["El mariscal Dughan cuida Villadorada y siempre anda buscando quien le eche la mano con los problemas de Elwynn."] = "Маршал Дуган охраняет Златоземье и всегда ищет, кто поможет с бедами Элвиннского леса.",
	["El medallón bajo cada marca del mapa y del minimapa: el de Alfa o solo el símbolo, sin medallón."] = "Медальон под каждой меткой на карте и мини-карте: от Alfa или только символ, без медальона.",
	["El medidor de daño aguanta en combate y la ayuda de rotación ya no te pide interrumpir lo que no se puede."] = "Измеритель урона держится в бою, а помощник ротации больше не просит прерывать то, что прервать нельзя.",
	["El medidor no está disponible"] = "Измеритель недоступен",
	["El mejor que tengas"] = "Лучшая, что есть",
	["El mekigeniero Termochufe, el traidor de Gnomeregan, sigue escondido dentro de la ciudad: es su último jefe."] = "Анжинер Термоштепсель, предатель Гномрегана, все еще прячется в городе: он его последний босс.",
	["El menú de la lupa del mapa del juego tiene también todas las capas de Alfa."] = "В меню лупы на карте игры тоже есть все слои Alfa.",
	["El mineral se funde en barras en cualquier forja."] = "Руду переплавляют в слитки в любой кузне.",
	["El minimapa"] = "Мини-карта",
	["El minimapa de Recolección descansa cuando no tiene nada que mostrar."] = "Мини-карта Сбора отдыхает, когда ей нечего показать.",
	["El minimapa pasa de redondo a cuadrado, con un borde fino. No se recomienda junto con girar el minimapa."] = "Мини-карта становится не круглой, а квадратной, с тонкой рамкой. Не рекомендуется вместе с вращением мини-карты.",
	["El mismo arreglo llegó a los asistentes de Ruta y de Curación."] = "То же исправление пришло в помощники «Маршрута» и «Исцеления».",
	["El mitril abunda en las Tierras Inhóspitas, las Tierras del Interior y Tanaris."] = "Мифрила много в Бесплодных землях, Внутренних землях и Танарисе.",
	["El modelo no lleva nada aquí."] = "На модели здесь ничего нет.",
	["El modo pesca se abre al salir de combate."] = "Режим рыбалки откроется после выхода из боя.",
	["El modo prueba se usa fuera de combate."] = "Тестовый режим работает вне боя.",
	["El motor no aceptó la guía."] = "Движок не принял гайд.",
	["El motor no puede armar guías ahora."] = "Движок сейчас не может составлять гайды.",
	["El mundo entero en un mapa"] = "Весь мир на одной карте",
	["El mundo pierde el color mientras eres espíritu."] = "Мир теряет цвет, пока вы в виде духа.",
	["El más cercano cuando le toque, por tiempo de camino."] = "Ближайший, когда до него дойдет очередь, по времени пути.",
	["El más cercano, por tiempo de camino"] = "Ближайший по времени пути",
	["El más cercano: %s"] = "Ближайший: %s",
	["El módulo Curación no está cargado."] = "Модуль «Исцеление» не загружен.",
	["El nombre de cada zona sobre el mapa de Alfa."] = "Название каждой зоны на карте Alfa.",
	["El número abajo a la izquierda de cada pieza de equipo."] = "Число в левом нижнем углу каждой вещи экипировки.",
	["El número es el orden en que se toma. Pasa el ratón por un talento para ver qué hace."] = "Число — порядок, в котором берется талант. Наведите курсор на талант, чтобы узнать, что он дает.",
	["El número que cuenta hacia atrás. Apagado, solo la barra."] = "Обратный отсчет цифрами. Выключено: только полоса.",
	["El objeto"] = "Предмет",
	["El objeto que usa el paso actual, o el objeto de misión que junta, brilla en tus bolsas. Un objeto que necesita un paso más adelante lleva un candado, para que no lo vendas."] = "Предмет, который использует текущий шаг, или собираемый предмет задания светится в сумках. Предмет, нужный на одном из следующих шагов, получает замок, чтобы вы его не продали.",
	["El orden importa más que los números: busca piezas con las primeras de la lista."] = "Порядок важнее чисел: ищите вещи с первыми характеристиками из списка.",
	["El paisaje lejano deja de perderse en la niebla espesa."] = "Дальний пейзаж больше не теряется в густом тумане.",
	["El paisaje lejano deja de perderse en la niebla espesa. A veces se nota dónde termina lo que está cargado."] = "Дальний пейзаж больше не теряется в густом тумане. Иногда видно, где кончается загруженная область.",
	["El paquete de datos de Alfa (Alfa_Codex) está desactivado: actívalo en la lista de addons y recarga."] = "Пакет данных Alfa (Alfa_Codex) отключен: включите его в списке модификаций и перезагрузите интерфейс.",
	["El paso de ahora de tu guía te lleva a entrenar."] = "Текущий шаг гайда ведет вас к учителю.",
	["El pequeño rey Anduin Wrynn lleva su nombre en honor a Anduin Lothar, el héroe que salvó a su pueblo."] = "Юного короля Андуина Ринна назвали в честь Андуина Лотара, героя, спасшего его народ.",
	["El primer clic abre la Cocina del juego; el siguiente cocina el lote. Tienes que estar junto a un fuego."] = "Первый щелчок открывает окно «Кулинария» в игре, следующий готовит партию. Нужно стоять у огня.",
	["El primer jefe de guerra de la Horda fue Mano Negra. Su hijo Rend Mano Negra hoy sirve a Nefarian en la Cumbre de Roca Negra."] = "Первым вождем Орды был Чернорук. Его сын Ренд Чернорук теперь служит Нефариану на пике Черной горы.",
	["El primer punto del Legado suele llegar al nivel 25, y con él se abre el Legado."] = "Первое очко «Наследия» обычно приходит на 25-м уровне, и с ним открывается «Наследие».",
	["El próximo: %s"] = "Следующая: %s",
	["El pícaro más fácil para subir: pega de frente, esquiva mucho y aguanta mejor que los demás."] = "Самый простой разбойник для прокачки: бьет в лоб, часто уклоняется и держится лучше остальных.",
	["El rango Experto viene en un libro que vende el pescador de Bahía del Botín, en Tuercespina."] = "Ступень «Умелец» — в книге, которую продает рыбак в Пиратской Бухте, в Тернистой долине.",
	["El rango de niveles de cada zona, con color según tu nivel."] = "Диапазон уровней каждой зоны, с цветом по вашему уровню.",
	["El rastreador te dice el siguiente paso y la flecha te lleva."] = "Трекер подсказывает следующий шаг, а стрелка ведет вас.",
	["El registro de daño del juego está apagado"] = "Учет урона в игре выключен",
	["El registro de daño del juego está apagado: enciéndelo para ver el top de tu grupo."] = "Учет урона в игре выключен: включите его, чтобы видеть топ группы.",
	["El registro del Legado"] = "Шкала наград «Наследия»",
	["El reino humano de Alterac traicionó a la Alianza en la Segunda Guerra: su rey, Aiden Perenolde, se alió con la Horda. Por eso el reino desapareció."] = "Человеческое королевство Альтерак предало Альянс во Второй войне: его король Эйден Перенольд перешел на сторону Орды. Поэтому королевство и исчезло.",
	["El reino limita los mensajes de addon salientes: %s"] = "Игровой мир ограничивает исходящие сообщения аддонов: %s",
	["El rey Llane Wrynn murió en la Primera Guerra a manos de Garona, la espía de la Horda."] = "Король Ллейн Ринн погиб в Первой войне от руки Гароны, шпионки Орды.",
	["El rey Magni Barbabronce gobierna Forjaz; sus hermanos son Muradin y Brann, el explorador."] = "Король Магни Бронзобород правит Стальгорном; его братья — Мурадин и исследователь Бранн.",
	["El rey Thoradin unió a las tribus humanas en Arathor, y los altos elfos les enseñaron magia para vencer juntos a los trols Amani."] = "Король Торадин объединил людские племена в Араторе, а высшие эльфы научили их магии, чтобы вместе победить троллей Амани.",
	["El rey Varian Wrynn es hijo de Llane, el rey que murió en la Primera Guerra."] = "Король Вариан Ринн — сын Ллейна, короля, погибшего в Первой войне.",
	["El rey Varian desapareció camino a una reunión de paz. Mientras tanto reina su hijo Anduin, todavía niño, con el alto señor Bolvar Fordragón como regente."] = "Король Вариан пропал по дороге на мирные переговоры. Пока правит его юный сын Андуин, а регентом при нем — верховный лорд Болвар Фордрагон.",
	["El sanador de los chamanes: curas en cadena y tótems que ayudan a todo el grupo."] = "Лекарь среди шаманов: цепное исцеление и тотемы, помогающие всей группе.",
	["El sanador de los druidas: curas a cualquier grupo y sobrevives bien, aunque en solitario matas lento."] = "Лекарь среди друидов: вы лечите любую группу и хорошо выживаете, хотя в одиночку убиваете медленно.",
	["El sanador de los paladines: curas fuertes y mucha armadura, ideal para grupos."] = "Лекарь среди паладинов: сильное исцеление и много брони, идеально для групп.",
	["El sanador puro: curas grandes y curas para todo el grupo."] = "Чистый лекарь: мощное исцеление и исцеление всей группы.",
	["El servicio"] = "Услуга",
	["El sistema de equipo de Alfa no está disponible."] = "Система экипировки Alfa недоступна.",
	["El sol aquí no perdona: las Tierras Inhóspitas son tierra de coyotes, buitres y basiliscos."] = "Солнце здесь беспощадно: Бесплодные земли — край койотов, стервятников и василисков.",
	["El suelo y los muros se ven nítidos aunque estén lejos o de lado."] = "Земля и стены остаются четкими, даже вдали или под углом.",
	["El talento que toca"] = "Следующий талант",
	["El tanque clásico: bloqueas mucho, generas amenaza con Revancha y Embate con escudo, y tienes Último recurso para cuando todo sale mal."] = "Классический танк: вы часто блокируете, создаете угрозу Реваншем и Мощным ударом щитом, а на случай, если все пошло не так, есть «Ни шагу назад».",
	["El tanque más difícil de matar: todos los talentos de defensa, Muro de escudo mejorado y Último recurso pronto. Perfecto para empezar a tanquear."] = "Самый живучий танк: все таланты защиты, Улучшенная глухая оборона и раннее «Ни шагу назад». Идеально, чтобы начать танковать.",
	["El terreno real en el mapa"] = "Настоящий рельеф на карте",
	["El texto es demasiado largo."] = "Текст слишком длинный.",
	["El texto llegó cortado o cambiado: cópialo otra vez."] = "Текст пришел обрезанным или измененным: скопируйте его снова.",
	["El tipo de nodos que une la ruta."] = "Тип узлов, которые соединяет маршрут.",
	["El tono de los fondos: Grafito es el de Alfa, Noche el más oscuro y Pizarra un gris neutro."] = "Тон фона: «Графит» — фирменный тон Alfa, «Ночь» — самый темный, «Сланец» — нейтральный серый.",
	["El top de DPS de tu grupo o banda en una ventana pequeña, con la pelea actual y la anterior."] = "Топ DPS группы или рейда в маленьком окне — текущий и предыдущий бой.",
	["El torio abunda en el Cráter de Un'Goro y en Cuna del Invierno."] = "Тория много в кратере Ун'Горо и в Зимних Ключах.",
	["El velo de pantalla de algunas zonas y hechizos de las sombras."] = "Пелена на экране в некоторых зонах и от заклинаний тьмы.",
	["El vendedor más cercano"] = "Ближайший торговец",
	["El verdadero nombre de Thrall es Go'el, el que le dieron sus padres."] = "Настоящее имя Тралла — Го'эл, его дали ему родители.",
	["El viejo ermitaño Abercrombie parece amable... hasta que descubres a quién intenta revivir."] = "Старый отшельник Аберкромби кажется добрым... пока не узнаешь, кого он пытается оживить.",
	["El «zug zug» de los peones quiere decir algo así como «de acuerdo». ¡Zug zug, jefe!"] = "«Зуг-зуг» у батраков значит что-то вроде «ладно». Зуг-зуг, вождь!",
	["El árbol de ruta de Alfa, misiones que se liberan y un catálogo de objetos."] = "Дерево маршрутов Alfa, задания по мере открытия и каталог предметов.",
	["El ícono grande es lo que conviene presionar ahora y los pequeños, lo que sigue. Si late, el juego activó esa habilidad; el barrido oscuro es su recarga. Tú decides: Alfa nunca aprieta nada."] = "Большой значок — то, что лучше нажать сейчас, маленькие — что дальше. Если он пульсирует, игра подсветила эту способность; темное затемнение — ее восстановление. Решаете вы: Alfa никогда ничего не нажимает.",
	["El último punto: paras un poco más."] = "Последнее очко: вы парируете чуть чаще.",
	["Elegida por ti en los ajustes."] = "Выбрано вами в настройках.",
	["Elegida por tus talentos."] = "Выбрано по вашим талантам.",
	["Elegido"] = "Выбрано",
	["Elegido por ti"] = "Выбрано вами",
	["Elegir capas"] = "Выбрать слои",
	["Elegir la siguiente guía"] = "Выбрать следующий гайд",
	["Elegir lo que pide tu paso"] = "Выбирать то, что просит шаг",
	["Elegir mi camino"] = "Выбрать мой путь",
	["Elegir mi primera guía"] = "Выбрать первый гайд",
	["Elegir mi tecla"] = "Выбрать клавишу",
	["Elegir otra guía"] = "Выбрать другой гайд",
	["Elegir para copiar"] = "Выделить для копирования",
	["Elegir qué sigue"] = "Выбрать, что дальше",
	["Elegir todo"] = "Выделить все",
	["Elegir una guía"] = "Выбрать гайд",
	["Elegir una guía por ti"] = "Выбирать гайд за вас",
	["Elegiste: %s"] = "Выбрано: %s",
	["Elemental"] = "Стихии",
	["Elemental para subir"] = "Стихии для прокачки",
	["Elfos de la noche"] = "Ночные эльфы",
	["Elige abajo qué cocinar y cuánto: la cola espera tu clic para cada lote."] = "Выберите ниже, что и сколько готовить: очередь ждет вашего щелчка для каждой партии.",
	["Elige algo de la lista"] = "Выберите что-нибудь из списка",
	["Elige el objeto"] = "Выберите предмет",
	["Elige el objeto en la Enciclopedia."] = "Выберите предмет в «Энциклопедии».",
	["Elige la opción que nombra tu guía, o abre la tienda o el entrenamiento que necesitas."] = "Выбирает вариант, который называет гайд, или открывает нужный магазин или обучение.",
	["Elige qué guardar: lo que ya tienes en el banco, los materiales, una categoría o todo lo que no sea equipo. Se mueve de una vez, fuera de combate."] = "Выберите, что положить: то, что уже есть в банке, материалы, категорию или все, кроме снаряжения. Переносится за один раз, вне боя.",
	["Elige qué quieres hacer y Alfa te lleva paso a paso."] = "Выберите, чем хотите заняться, и Alfa проведет вас шаг за шагом.",
	["Elige qué se ve en el mapa: guía, misiones, raros, viajes, zonas y lo que agregan otros módulos."] = "Выберите, что видно на карте: гайд, задания, редкие, путешествия, зоны и то, что добавляют другие модули.",
	["Elige sola la única opción de los PNJ sin misiones."] = "Сам выбирает единственный вариант у NPC без заданий.",
	["Elige solo misiones que ya puedes tomar."] = "Выбирает только задания, которые уже можно взять.",
	["Elige tu camino. Si no sabes, empieza por subir de nivel: Alfa te dice qué conviene."] = "Выберите путь. Если не знаете, начните с прокачки: Alfa подскажет, что выгодно.",
	["Elige tu estilo"] = "Выберите стиль",
	["Elige tu tecla para pescar"] = "Выберите клавишу для рыбалки",
	["Elige tus clics"] = "Выберите щелчки",
	["Elige tus clics, acomoda tus marcos y pruébalos. Te toma un minuto."] = "Выберите щелчки, расставьте рамки и проверьте их. Это займет минуту.",
	["Elige tú la zona."] = "Зону выбираете вы.",
	["Elige un camino: Alfa arma tu plan y te guía paso a paso."] = "Выберите путь: Alfa составит план и проведет вас шаг за шагом.",
	["Elige un marcador."] = "Выберите маркер.",
	["Elige un servicio."] = "Выберите услугу.",
	["Elige una captura"] = "Выберите улов",
	["Elige una guía para empezar"] = "Выберите гайд, чтобы начать",
	["Elige una mazmorra."] = "Выберите подземелье.",
	["Elige una misión"] = "Выберите задание",
	["Elige una profesión"] = "Выберите профессию",
	["Elige una profesión."] = "Выберите профессию.",
	["Elige uno y lo ves al instante en esta ventana y en todas las de Alfa, también la flecha."] = "Выберите один и сразу увидите его в этом окне и во всех окнах Alfa, включая стрелку.",
	["Eliges una"] = "Выберите одно",
	["Ella duerme a todo el grupo y luego resucita a Mograine: es normal, no se asusten."] = "Она усыпляет всю группу, а затем воскрешает Могрейна: это нормально, не паникуйте.",
	["Elune, la diosa de la luna, es la fe de los elfos de la noche. Sus sacerdotisas son las Hermanas de Elune, y Tyrande es su suma sacerdotisa."] = "Элуна, богиня луны, — вера ночных эльфов. Ее жрицы — Сестры Элуны, а Тиранда — их верховная жрица.",
	["Embate con escudo: mucho daño y amenaza."] = "Мощный удар щитом: много урона и угрозы.",
	["Embate deja de reiniciar tu ataque: un golpe extra entre golpe y golpe."] = "Мощный удар больше не сбрасывает вашу атаку: дополнительный удар между ударами.",
	["Embate sin perder tu ataque automático."] = "Мощный удар без потери автоатаки.",
	["Embate sin perder tu ataque."] = "Мощный удар без потери атаки.",
	["Embate sin perder tu golpe automático."] = "Мощный удар без потери автоатаки.",
	["Embate sin reiniciar tu ataque: un golpe extra."] = "Мощный удар без сброса атаки: дополнительный удар.",
	["Embate: un golpe fuerte entre golpe y golpe."] = "Мощный удар: сильный удар между автоатаками.",
	["Empezar"] = "Начать",
	["Empezar de cero"] = "Начать заново",
	["Empezar de nuevo"] = "Начать заново",
	["Empezar otra"] = "Начать другой",
	["Empezar otra sesión"] = "Начать другой сеанс",
	["Empezó %s"] = "Начало: %s",
	["Empezó %s."] = "Начало: %s.",
	["Empieza al usar este objeto"] = "Начинается при использовании этого предмета",
	["Empieza aquí"] = "Начните здесь",
	["Empieza con %s, que se consigue en la mazmorra."] = "Начинается с предмета %s, который добывается в подземелье.",
	["Empieza con %s, que suelta %s."] = "Начинается с предмета %s — его роняет %s.",
	["Empieza con tu hechizo más lento desde lejos y termina con los instantáneos."] = "Начинайте издалека с самого медленного заклинания и заканчивайте мгновенными.",
	["Empieza dentro"] = "Начинается внутри",
	["Empieza una misión"] = "Начинает задание",
	["Empiezas: nivel %d"] = "Начало: уровень %d",
	["En %s"] = "В: %s",
	["En 9 idiomas"] = "На 9 языках",
	["En Burning Crusade, Karazhan abre sus puertas como banda."] = "В Burning Crusade Каражан откроет двери как рейд.",
	["En Burning Crusade, el Vuelo Bronce pide ayuda en las Cavernas del Tiempo contra dragones que quieren cambiar la historia."] = "В Burning Crusade бронзовые драконы просят помощи в Пещерах Времени против драконов, которые хотят изменить историю.",
	["En Burning Crusade, las Cavernas del Tiempo te regresan a estas laderas para ver la huida de Thrall de Durnholde."] = "В Burning Crusade Пещеры Времени вернут тебя на эти склоны, чтобы увидеть побег Тралла из Дарнхольда.",
	["En Caer Darrow, junto al lago, todavía rondan los fantasmas de sus antiguos vecinos."] = "В Каэр Дарроу у озера до сих пор бродят призраки бывших жителей.",
	["En Ciudad Manitas, dentro de Forjaz, viven los gnomos que escaparon de Gnomeregan."] = "В Городе Механиков в Стальгорне живут гномы, сбежавшие из Гномрегана.",
	["En Costa Oscura la Liga de Expedicionarios desentierra fósiles gigantes."] = "На Темных берегах Лига исследователей раскапывает гигантские окаменелости.",
	["En Costa Oscura viven lechúcicos, criaturas mitad búho y mitad oso que veneran la luna."] = "На Темных берегах живут лунные совухи — наполовину совы, наполовину медведи, почитающие луну.",
	["En Desolace está el cementerio de los kodos, donde los viejos kodos van a morir."] = "В Пустошах есть Кладбище кодо, куда старые кодо уходят умирать.",
	["En Durotar ya te topas con el Filo Ardiente, un culto de brujos orcos que sigue adorando a los demonios."] = "Уже в Дуротаре ты встречаешь Пылающий Клинок — культ орков-чернокнижников, которые все еще поклоняются демонам.",
	["En Elwynn, una señora vende gatitos de compañía. ¡Yo me llevo bien con los gatos... casi siempre!"] = "В Элвиннском лесу одна дама продает котят-питомцев. Я с кошками лажу... почти всегда!",
	["En Entrañas venden cucarachas de mascota. Cada quien sus gustos."] = "В Подгороде продают тараканов-питомцев. На вкус и цвет...",
	["En Feralas está uno de los grandes árboles por los que los dragones verdes entran al Sueño Esmeralda."] = "В Фераласе растет одно из великих деревьев, через которые зеленые драконы входят в Изумрудный Сон.",
	["En Forever, Onyxia, la Cumbre Hyjal y Barrow Deeps dan retos del Legado al vencerlas."] = "В Forever Ониксия, Вершина Хиджала и Barrow Deeps дают испытания «Наследия» за победу.",
	["En Forever, el banco vende casillas de bolsa una tras otra: más espacio para tus tesoros."] = "В Forever банк продает ячейки для сумок одну за другой: больше места для твоих сокровищ.",
	["En Forever, los rangos de honor y la reputación de los campos de batalla también dan retos del Legado."] = "В Forever звания чести и репутация полей боя тоже дают испытания «Наследия».",
	["En Forever, los retos del Legado dan puntos a toda tu cuenta, y cada personaje los gasta en sus árboles. Ábrelo con la tecla Y."] = "В Forever испытания «Наследия» дают очки всей учетной записи, а каждый персонаж тратит их в своих деревьях. Открой клавишей Y.",
	["En Forjaz, la sala de la Liga de Expedicionarios tiene un museo con fósiles enormes. Brann Barbabronce es su explorador más famoso."] = "В Стальгорне в зале Лиги исследователей есть музей с огромными окаменелостями. Бранн Бронзобород — ее самый знаменитый исследователь.",
	["En Gadgetzan, el cocinero Dirge enseña una de las mejores recetas del Clásico, con carne de quimerok."] = "В Прибамбасске повар Дирдж учит одному из лучших рецептов классики — из мяса химерока.",
	["En Jaedenar se esconde el Consejo de la Sombra, brujos que sirven a la Legión Ardiente."] = "В Джеденаре скрывается Совет Теней — чернокнижники, служащие Пылающему Легиону.",
	["En Jardín Noble se esconden huevos de colores por los pueblos iniciales; dentro hay dulces y a veces ropa de primavera."] = "В Сад чудес в стартовых городках прячут разноцветные яйца; внутри сладости, а иногда весенняя одежда.",
	["En Kharanos, la posada y la destilería Cebatruenos son la parada obligada para calentarse... por dentro y por fuera."] = "В Караносе таверна и пивоварня Громоваров — обязательная остановка, чтобы согреться... и снаружи, и изнутри.",
	["En Molino Ámbar se refugian magos de Dalaran, y no les gustan nada las visitas de los Renegados."] = "В Янтарной мельнице укрываются маги Даларана, и визиты Отрекшихся им совсем не по душе.",
	["En Naxxramas, el gran Alexandros Mograine reaparece como uno de los Cuatro Jinetes de la Plaga. Qué triste destino para un héroe."] = "В Наксрамасе великий Александрос Могрейн возвращается одним из Четырех всадников Плети. Какая грустная судьба для героя.",
	["En Nethergarde, unos magos de sangre te cambian partes de las bestias de aquí por elixires que te potencian un buen rato."] = "В Крепости Стражей Пустоты маги крови меняют части местных зверей на эликсиры, которые надолго усиливают тебя.",
	["En Orgrimmar, el Valle de la Sabiduría guarda la fortaleza de Thrall, y el Valle del Honor reúne a guerreros y cazadores."] = "В Оргриммаре в Аллее Мудрости стоит крепость Тралла, а в Аллее Чести собираются воины и охотники.",
	["En Pico Nidal manda el thane Falstad Martillo Salvaje, señor de los jinetes de grifo."] = "В Заоблачном пике правит тан Фалстад Громовой Молот, повелитель всадников на грифонах.",
	["En Pico Nidal viven los enanos Martillo Salvaje, famosos por volar sobre grifos."] = "В Заоблачном пике живут дворфы Громового Молота, знаменитые полетами на грифонах.",
	["En Seradane hay uno de los grandes árboles que llevan al Sueño Esmeralda, y los dragones verdes lo custodian."] = "В Серадане растет одно из великих деревьев, ведущих в Изумрудный Сон, и его стерегут зеленые драконы.",
	["En Tanaris están las Cavernas del Tiempo, donde el Vuelo Bronce de Nozdormu vigila la historia."] = "В Танарисе находятся Пещеры Времени, где бронзовые драконы Ноздорму охраняют историю.",
	["En Tirisfal está la entrada al Monasterio Escarlata, uno de los lugares más visitados por los aventureros de nivel medio."] = "В Тирисфальских лесах вход в Монастырь Алого ордена — одно из самых посещаемых мест у искателей приключений среднего уровня.",
	["En Uldaman están los Discos de Norgannon, registros de los titanes que cuentan cómo crearon a los terráneos, los antepasados de piedra de los enanos."] = "В Ульдамане хранятся Диски Норганнона — записи титанов о том, как они создали земельников, каменных предков дворфов.",
	["En Vallefresno, Grom Grito Infernal mató al semidiós Cenarius cuando la Horda empezó a talar el bosque."] = "В Ясеневом лесу Гром Адский Крик убил полубога Кенария, когда Орда начала вырубать лес.",
	["En Vallefresno, Grom volvió a beber sangre demoníaca; Thrall lo rescató y Grom pudo redimirse antes de morir."] = "В Ясеневом лесу Гром снова выпил кровь демона; Тралл спас его, и Гром смог искупить вину перед смертью.",
	["En Ventormenta hay un barrio de enanos, uno de magos y un parque donde se reúnen los elfos de la noche."] = "В Штормграде есть квартал дворфов, квартал магов и парк, где собираются ночные эльфы.",
	["En Warcraft III, si le das muchos clics a una unidad empieza a decir cosas chistosas. Yo, en cambio, te doy consejos."] = "В Warcraft III, если много раз щелкнуть по юниту, он начинает говорить смешные вещи. А я вместо этого даю советы.",
	["En arco"] = "Дугой",
	["En bancos de peces de: %s."] = "В косяках рыбы: %s.",
	["En camino"] = "В пути",
	["En cero los números suben derechos; más alto, salen disparados hacia los lados."] = "При нуле числа поднимаются прямо; чем выше, тем сильнее разлетаются в стороны.",
	["En combate"] = "В бою",
	["En combate el juego oculta los números exactos: las barras y las cifras se ven igual, el detalle y el anuncio, al salir."] = "В бою игра скрывает точные числа: полосы и цифры все равно видны, а подробности и объявление — после выхода из боя.",
	["En combate el mapa del juego no se abre desde Alfa: usa el de Alfa."] = "В бою карта игры не открывается из Alfa: используйте карту Alfa.",
	["En combate no aparece el cuadro de los personajes y criaturas del mundo (el de los marcos sí)."] = "В бою не показывается подсказка персонажей и существ в мире (подсказка рамок — показывается).",
	["En combate no hay prueba: sal de la pelea y vuelve a este paso."] = "В бою проверка недоступна: выйдите из боя и вернитесь к этому шагу.",
	["En combate no puedo buscar: inténtalo al terminar la pelea."] = "В бою я не могу искать: попробуйте после боя.",
	["En combate no se puede: espera a terminar."] = "В бою нельзя: дождитесь конца боя.",
	["En combate · la pesca espera"] = "В бою · рыбалка подождет",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard y las %d que siguen. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "В бою значок показывает способность, которую предлагает помощник Blizzard, и %d следующих. Что нажимать, решаете вы: Alfa никогда ничего не нажимает за вас.",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "В бою значок показывает способность, которую предлагает помощник Blizzard. Что нажимать, решаете вы: Alfa никогда ничего не нажимает за вас.",
	["En combate: espera a terminar"] = "В бою: дождитесь окончания",
	["En curso"] = "В процессе",
	["En el Casco Antiguo está el SI:7, los espías y pícaros al servicio del reino."] = "В Старом городе находится ШРУ:7 — шпионы и разбойники на службе королевства.",
	["En el Clásico mandan Thrall en Orgrimmar, Cairne en Cima del Trueno, Sylvanas en Entrañas y Vol'jin con los Lanza Negra."] = "В классике Тралл правит в Оргриммаре, Кэрн — в Громовом Утесе, Сильвана — в Подгороде, а Вол'джин ведет племя Черного Копья.",
	["En el Clásico nadie sabe dónde anda Alamuerte; los que dan la cara son sus hijos, Onyxia y Nefarian."] = "В классике никто не знает, где Смертокрыл; показываются только его дети — Ониксия и Нефариан.",
	["En el Clásico necesitas flechas o balas: lleva siempre de más en tu carcaj o tu bolsa de munición."] = "В классике нужны стрелы или пули: всегда носи запас в колчане или подсумке.",
	["En el Clásico necesitas un cuchillo de desollar en tus bolsas."] = "В классике нужен нож для снятия шкур в сумках.",
	["En el Clásico solo puedes tener dos profesiones principales, pero Cocina, Pesca y Primeros auxilios se aprenden aparte."] = "В классике можно иметь только две основные профессии, но кулинария, рыбная ловля и первая помощь изучаются отдельно.",
	["En el Clásico, Costasur contra Molino Tarren era la pelea entre bandos más famosa del mundo."] = "В классике Южнобережье против Мельницы Таррен было самым знаменитым противостоянием фракций в мире.",
	["En el Clásico, a nivel 20 aprendes a teletransportarte a las capitales, y a 40 a abrir portales para los demás."] = "В классике на 20-м уровне ты учишься телепортироваться в столицы, а на 40-м — открывать порталы для других.",
	["En el Clásico, a nivel 20 haces la misión de los venenos; después los mejoras con tu entrenador."] = "В классике на 20-м уровне ты выполняешь задание на яды, а потом улучшаешь их у учителя.",
	["En el Clásico, a nivel 40 haces la misión de tu caballo de guerra, y a 60 la cadena épica del destrero."] = "В классике на 40-м уровне ты выполняешь задание на боевого коня, а на 60-м — эпическую цепочку на скакуна.",
	["En el Clásico, a nivel 40 recibes un corcel vil, y a 60 una cadena épica en La Masacre te da uno aún más temible."] = "В классике на 40-м уровне ты получаешь коня Скверны, а на 60-м эпическая цепочка в Забытом городе дает еще более грозного.",
	["En el Clásico, abrir las puertas de Ahn'Qiraj pidió un esfuerzo de guerra de todo el servidor: montañas de materiales y una cadena larguísima."] = "В классике открытие ворот Ан'Киража потребовало военных усилий всего сервера: горы материалов и очень длинная цепочка заданий.",
	["En el Clásico, algunos peces solo pican de noche o de día."] = "В классике некоторые рыбы клюют только ночью или только днем.",
	["En el Clásico, cada raza de sacerdote tiene un hechizo propio. Pregúntale a tu entrenador cuál te toca."] = "В классике у жрецов каждой расы есть свое заклинание. Спроси у учителя, какое твое.",
	["En el Clásico, después de vendarte queda un rato en que no puedes usar otra venda."] = "В классике после перевязки какое-то время нельзя использовать другой бинт.",
	["En el Clásico, el Cetro de las Arenas Movedizas abrió las puertas de Ahn'Qiraj tras una larguísima cadena de misiones."] = "В классике Скипетр Зыбучих Песков открыл ворота Ан'Киража после очень длинной цепочки заданий.",
	["En el Clásico, el arco épico de los cazadores sale de una cadena contra demonios que empieza en el Claro de la Luna."] = "В классике эпический лук охотников дает цепочка против демонов, которая начинается на Лунной поляне.",
	["En el Clásico, el chat de Los Baldíos era famoso por sus pláticas eternas... y por preguntar dónde estaba la esposa de Mankrik."] = "В классике чат Степей славился бесконечными разговорами... и вопросами, где жена Манкрика.",
	["En el Clásico, el nivel máximo es 60 y llegar lleva su tiempo. Por eso cada nivel se festeja."] = "В классике максимальный уровень — 60, и путь к нему долгий. Поэтому каждый уровень стоит отпраздновать.",
	["En el Clásico, el rango de honor 14 es Gran Mariscal para la Alianza y Gran Señor de la Guerra para la Horda."] = "В классике 14-е звание чести — Великий маршал у Альянса и Верховный военачальник у Орды.",
	["En el Clásico, la Feria de la Luna Negra a veces se instala en Mulgore, cerca del poblado Pezuña de Sangre."] = "В классике Ярмарка Новолуния иногда приезжает в Мулгор, к деревне Кровавого Копыта.",
	["En el Clásico, la Feria de la Luna Negra a veces se instala junto a Villadorada."] = "В классике Ярмарка Новолуния иногда приезжает к Златоземью.",
	["En el Clásico, la Horda la forman orcos, trols Lanza Negra, tauren y Renegados; la Alianza, humanos, enanos, gnomos y elfos de la noche."] = "В классике Орду составляют орки, тролли Черного Копья, таурены и Отрекшиеся; Альянс — люди, дворфы, гномы и ночные эльфы.",
	["En el Clásico, la Plaga invadió el mundo con necrópolis flotantes antes de que se abriera Naxxramas."] = "В классике Плеть вторглась в мир на летающих некрополях еще до открытия Наксрамаса.",
	["En el Clásico, la actitud defensiva se gana con una misión al nivel 10, y la rabiosa con otra al nivel 30."] = "В классике Оборонительную стойку дает задание на 10-м уровне, а Стойку берсерка — другое, на 30-м.",
	["En el Clásico, la casa de subastas de Forjaz es la más movida de toda la Alianza."] = "В классике аукцион Стальгорна — самый оживленный во всем Альянсе.",
	["En el Clásico, la forma de oso se gana con una misión a nivel 10 y la acuática con otra a nivel 16; luego vienen la felina y la de viaje."] = "В классике облик медведя дает задание на 10-м уровне, а водный облик — другое, на 16-м; потом идут облик кошки и походный облик.",
	["En el Clásico, la montura de nivel 40 es mucho más rápida que correr, y la épica de nivel 60 todavía más."] = "В классике транспорт 40-го уровня намного быстрее бега, а эпический на 60-м — еще быстрее.",
	["En el Clásico, la tela se puede donar en tu capital a cambio de reputación."] = "В классике ткань можно сдавать в своей столице в обмен на репутацию.",
	["En el Clásico, las bandas grandes son de 40 jugadores, y Zul'Gurub y las Ruinas de Ahn'Qiraj, de 20."] = "В классике большие рейды рассчитаны на 40 игроков, а Зул'Гуруб и Руины Ан'Киража — на 20.",
	["En el Clásico, los Renegados se quitan el miedo, el encanto y el sueño con su voluntad."] = "В классике Отрекшиеся силой воли стряхивают страх, очарование и сон.",
	["En el Clásico, los domingos por la tarde Bahía del Botín organizaba un concurso de pesca: ganaba quien entregara primero cuarenta peces de una especie especial."] = "В классике по воскресеньям после обеда Пиратская Бухта устраивала рыболовное состязание: побеждал тот, кто первым сдаст сорок рыб особого вида.",
	["En el Clásico, los enanos pueden buscar tesoros con un rastreo propio. ¡Ideal para encontrar cofres!"] = "В классике дворфы умеют искать сокровища особым поиском. Идеально для сундуков!",
	["En el Clásico, los enanos se convierten en piedra para quitarse venenos y sangrados, y son buenos con las armas de fuego."] = "В классике дворфы обращаются в камень, чтобы избавиться от ядов и кровотечений, и хорошо обращаются с огнестрельным оружием.",
	["En el Clásico, los gnomos pueden ser guerreros, pícaros, magos o brujos."] = "В классике гномы могут быть воинами, разбойниками, магами или чернокнижниками.",
	["En el Clásico, los gnomos son más listos que el resto, tienen talento para la ingeniería y se zafan de lo que los inmoviliza."] = "В классике гномы умнее остальных, у них талант к инженерному делу, и они выскальзывают из всего, что их обездвиживает.",
	["En el Clásico, los humanos ganan reputación más rápido gracias a su diplomacia, y tienen buen ojo para ver a los sigilosos."] = "В классике люди быстрее набирают репутацию благодаря дипломатии и хорошо замечают незаметных.",
	["En el Clásico, los maestros de armas de las capitales te enseñan a usar armas nuevas."] = "В классике мастера оружия в столицах учат пользоваться новым оружием.",
	["En el Clásico, los orcos resisten mejor los aturdimientos y sus mascotas pegan más fuerte."] = "В классике орки лучше сопротивляются оглушению, а их питомцы бьют сильнее.",
	["En el Clásico, los tauren tienen más vida, un pisotón que aturde a los enemigos cercanos y mano verde con las hierbas."] = "В классике у тауренов больше здоровья, есть топот, оглушающий ближайших противников, и легкая рука с травами.",
	["En el Clásico, los trols se regeneran rápido, entran en frenesí, pegan más fuerte a las bestias y son buenos con arcos y armas arrojadizas."] = "В классике тролли быстро восстанавливаются, впадают в берсерк, сильнее бьют зверей и хорошо обращаются с луками и метательным оружием.",
	["En el Clásico, muchas comidas te dejan bien alimentado y te suben estadísticas un buen rato."] = "В классике многие блюда дают сытость и надолго повышают характеристики.",
	["En el Clásico, para pasar de 225 hay una misión de triaje en Theramore o en Sentencia."] = "В классике, чтобы пройти дальше 225, есть задание по сортировке раненых в Тераморе или в Молоте.",
	["En el Clásico, quienes terminaron la cadena del cetro y tocaron el gong de Ahn'Qiraj ganaron un título y una montura únicos."] = "В классике те, кто прошел цепочку скипетра и ударил в гонг Ан'Киража, получили уникальное звание и транспорт.",
	["En el Clásico, solo elfos de la noche y tauren pueden ser druidas."] = "В классике друидами могут быть только ночные эльфы и таурены.",
	["En el Clásico, solo humanos y enanos pueden ser paladines."] = "В классике паладинами могут быть только люди и дворфы.",
	["En el Clásico, solo orcos, trols y tauren pueden ser chamanes."] = "В классике шаманами могут быть только орки, тролли и таурены.",
	["En el Clásico, tu Reencarnación te revive a ti mismo, pero necesita un ankh en tus bolsas."] = "В классике «Перерождение» позволяет тебе воскреснуть самостоятельно, но нужен анкх в сумках.",
	["En el Enclave Cenarion los druidas enseñan a los suyos el camino de la naturaleza."] = "В Анклаве Кенария друиды учат своих пути природы.",
	["En el Festival Lunar, la gente viene al Claro de la Luna a honrar a sus ancestros."] = "Во время Лунного фестиваля люди приходят на Лунную поляну почтить предков.",
	["En el Festival Lunar, un emisario en las capitales te puede llevar al Claro de la Luna para celebrar con los druidas."] = "Во время Лунного фестиваля посланник в столицах может перенести тебя на Лунную поляну, чтобы праздновать с друидами.",
	["En el Festival de Fuego del Solsticio de Verano hay hogueras en muchos pueblos: honrar las de tu bando da premios, y apagar las del otro también."] = "Во время Огненного солнцеворота во многих городках горят костры: почтить костры своей фракции — награда, потушить чужие — тоже.",
	["En el Festival de Invierno venden bolas de nieve. ¡Lánzaselas a tus amigos, que yo las atrapo!"] = "На Зимний Покров продают снежки. Кидай их в друзей, а я буду ловить!",
	["En el Festival de Invierno, el Gran Padre Invierno reparte regalos en Forjaz y Orgrimmar, y bajo el árbol aparecen paquetes el día 25."] = "На Зимний Покров Дедушка Зима раздает подарки в Стальгорне и Оргриммаре, а 25-го под елкой появляются свертки.",
	["En el Festival de la Cosecha, la Horda honra a Grom Grito Infernal y la Alianza a Uther, en sus monumentos."] = "На Праздник урожая Орда чтит Грома Адского Крика, а Альянс — Утера, у их памятников.",
	["En el Núcleo de Magma se desuellan perros del núcleo para un cuero muy especial."] = "В Огненных Недрах с гончих Недр снимают совершенно особую кожу.",
	["En el Santuario Esmeralda, los druidas intentan sanar el bosque enfermo."] = "В Изумрудном святилище друиды пытаются исцелить больной лес.",
	["En el Valle de Alterac pelean la Guardia Pico Tormenta de los enanos y el clan Lobo Gélido. Yo ya sé a quién le voy."] = "В Альтеракской долине сражаются Стража Грозовой Вершины дворфов и клан Северного Волка. Я уже знаю, за кого болею.",
	["En el Valle de la Fuerza están el banco y la casa de subastas: el corazón del comercio de la Horda."] = "В Аллее Силы банк и аукцион — сердце торговли Орды.",
	["En el camino"] = "По пути",
	["En el centro de aquel Kalimdor estaba el Pozo de la Eternidad, un lago de pura magia. Unos trols que vivían a su orilla cambiaron con los siglos y se volvieron los elfos de la noche."] = "В центре того Калимдора лежал Источник Вечности, озеро чистой магии. Тролли, жившие на его берегах, за века изменились и стали ночными эльфами.",
	["En el centro de la garganta hay un enorme pozo de lava, la Caldera, donde trabajan esclavos de los Hierro Negro."] = "В центре ущелья огромная лавовая яма — Котел, где трудятся рабы Черного Железа.",
	["En el centro del cráter humea un volcán donde viven elementales de fuego."] = "В центре кратера дымится вулкан, где живут огненные элементали.",
	["En el chat"] = "В чате",
	["En el corazón del Templo de la Luna hay un pozo lunar, donde las sacerdotisas rezan a Elune."] = "В сердце Храма Луны есть лунный колодец, у которого жрицы молятся Элуне.",
	["En el cráter, un tal Linken perdió la memoria y busca su espada y su escudo: un guiño a cierto héroe de orejas puntiagudas."] = "В кратере некий Линкен потерял память и ищет свои меч и щит — отсылка к одному остроухому герою.",
	["En el este de las Tierras Inhóspitas viven dragones negros y sus siervos. Pasa lejitos si no llevas compañía."] = "На востоке Бесплодных земель живут черные драконы и их слуги. Обходи стороной, если идешь без компании.",
	["En el este del lago viven ogros que les hacen la vida difícil a los enanos de Thelsamar."] = "На востоке озера живут огры, которые портят жизнь дворфам Телсамара.",
	["En el gran salar del este, goblins y gnomos organizan carreras; la rivalidad es feroz."] = "На большой соляной равнине на востоке гоблины и гномы устраивают гонки; соперничество там жестокое.",
	["En el juego"] = "В игре",
	["En el lago de Villa del Lago hay múrlocs, ¡como en casi todo lago de Azeroth!"] = "В озере Приозерья есть мурлоки — как почти в каждом озере Азерота!",
	["En el mapa"] = "На карте",
	["En el mapa de Alfa, clic: seguirla con la flecha o guardarla como marcador."] = "На карте Alfa щелчок: следовать по стрелке или сохранить как маркер.",
	["En el mapa del mundo"] = "На карте мира",
	["En el marco del objetivo"] = "На рамке цели",
	["En el minimapa"] = "На мини-карте",
	["En el mundo"] = "В мире",
	["En el nivel 10 domas tu bestia."] = "На 10-м уровне вы приручите зверя.",
	["En el nivel 20 aprendes venenos."] = "Яды изучаются на 20-м уровне.",
	["En el norte de estas tierras, la Cruzada Escarlata domina un pueblo amurallado y lo defiende con fanatismo."] = "На севере этих земель Алый орден занимает обнесенный стеной город и фанатично его защищает.",
	["En el oeste de Las Mil Agujas anidan dracoleones salvajes."] = "На западе Тысячи Игл гнездятся дикие виверны.",
	["En el pueblo de los druidas del Claro de la Luna conviven Alianza y Horda: el Círculo Cenarion recibe a todos."] = "В деревне друидов на Лунной поляне Альянс и Орда живут бок о бок: Круг Кенария принимает всех.",
	["En el sur de Desolace, demonios y sátiros se reúnen en un aquelarre."] = "На юге Пустошей демоны и сатиры собираются на шабаш.",
	["En el sur de Tanaris hay colmenas de silítidos, primos de los de Silithus."] = "На юге Танариса есть ульи силитидов — родичей тех, что в Силитусе.",
	["En el sureste, la Mano de Tyr es la ciudad más fuerte que le queda a la Cruzada Escarlata."] = "На юго-востоке Длань Тира — самый сильный город, оставшийся у Алого ордена.",
	["En espera"] = "Ожидание",
	["En esta zona"] = "В этой зоне",
	["En estas laderas está Durnholde, donde Aedelas Blackmoore crió a Thrall como gladiador."] = "На этих склонах стоит Дарнхольд, где Эделас Блэкмур растил Тралла гладиатором.",
	["En estas tierras cayó Anduin Lothar, el León de Azeroth, durante la Segunda Guerra."] = "На этих землях во Второй войне пал Андуин Лотар, Лев Азерота.",
	["En estas tierras estuvo Strom, la capital de Arathor, el primer gran reino humano."] = "На этих землях стоял Стром, столица Аратора, первого великого королевства людей.",
	["En este pantano se hundió el Templo de Atal'Hakkar: los dragones verdes lo hundieron para frenar a los sacerdotes de Hakkar."] = "В этом болоте затонул Храм Атал'Хаккара: зеленые драконы погрузили его, чтобы остановить жрецов Хаккара.",
	["En grifo, la línea de tu vuelo en el mapa: por dónde vas, dónde aterrizas y el tiempo que falta."] = "На грифоне — линия твоего полёта на карте: где ты сейчас, где приземлишься и сколько осталось лететь.",
	["En grupo"] = "В группе",
	["En grupo casi siempre hay varios enemigos: pegas a dos a la vez."] = "В группе почти всегда несколько противников: вы бьете двоих сразу.",
	["En grupo y aguantando: Furia justa te da más amenaza."] = "В группе и в роли танка: Праведное неистовство дает больше угрозы.",
	["En grupo, cura al tanque antes que a nadie."] = "В группе лечите танка раньше всех.",
	["En grupo, cura al tanque primero y no saques monstruos tú."] = "В группе лечите танка в первую очередь и сами не притягивайте монстров.",
	["En grupo, cura antes de que la vida baje mucho: es más barato."] = "В группе лечите, пока здоровье не упало сильно: так дешевле.",
	["En grupo, deja tus tótems de maná y de curas cerca del grupo."] = "В группе ставьте тотемы маны и исцеления рядом с группой.",
	["En la Arena Gurubashi aparece de vez en cuando un cofre que todos se pelean. ¡Sálvese quien pueda!"] = "На Арене Гурубаши время от времени появляется сундук, за который дерутся все. Спасайся, кто может!",
	["En la Enciclopedia"] = "В «Энциклопедии»",
	["En la Feria canjeas vales por premios; los vales se ganan entregando cosas que hiciste con tu profesión o que juntaste cazando."] = "На Ярмарке ты меняешь купоны на призы; купоны дают за вещи, сделанные твоей профессией или добытые на охоте.",
	["En la Feria de la Luna Negra, la adivina Sayge te hace unas preguntas y te da una fortuna que sube tus estadísticas un buen rato."] = "На Ярмарке Новолуния гадалка Сейдж задает пару вопросов и дает предсказание, которое надолго повышает характеристики.",
	["En la Fortaleza de Grommash, Thrall recibe a quien venga; muy cerca está Eitrigg, el viejo orco amigo de Tirion."] = "В Крепости Громмаш Тралл принимает всех; рядом стоит Эйтригг, старый орк, друг Тириона.",
	["En la Guerra de las Arenas Movedizas, el archidruida Fandral perdió a su hijo Valstann a manos de los qiraji."] = "В Войне Зыбучих Песков верховный друид Фэндрал потерял сына Валстанна в бою с киражами.",
	["En la Segunda Guerra, la Horda sumó a los trols Amani, a los ogros y a dragones rojos esclavizados."] = "Во Второй войне к Орде присоединились тролли Амани, огры и порабощенные красные драконы.",
	["En la Semana de los Niños, los huérfanos de Ventormenta y Orgrimmar te piden que los lleves de paseo; al final te dan una mascota."] = "На Детской неделе сироты Штормграда и Оргриммара просят сводить их на прогулку; в конце они дарят питомца.",
	["En la Tercera Guerra, orcos, humanos y elfos se unieron aquí contra Archimonde, y Nordrassil sacrificó su energía para destruirlo."] = "В Третьей войне орки, люди и эльфы объединились здесь против Архимонда, и Нордрассил пожертвовал своей силой, чтобы уничтожить его.",
	["En la Terraza de los Artesanos de Darnassus están los maestros de profesiones."] = "На Террасе Ремесленников в Дарнасе находятся учителя профессий.",
	["En la Vega se encuentran páginas sueltas de un libro de Nesingwary; junta un capítulo completo y llévaselo."] = "В Тернистой долине попадаются разрозненные страницы книги Несингвари; собери целую главу и отнеси ему.",
	["En la batalla de Hyjal, Malfurion hizo sonar el Cuerno de Cenarius y miles de fuegos fatuos rodearon a Archimonde hasta destruirlo."] = "В битве при Хиджале Малфурион протрубил в Рог Кенария, и тысячи огоньков окружили Архимонда, пока не уничтожили его.",
	["En la casa de subastas, mira los precios unos días antes de vender: cambian según la hora y quién esté jugando."] = "На аукционе понаблюдай за ценами несколько дней перед продажей: они меняются в зависимости от времени и того, кто играет.",
	["En la cima del Monte Hyjal crece Nordrassil, el Árbol del Mundo, que los dragones bendijeron."] = "На вершине горы Хиджал растет Нордрассил, Древо Мира, благословленное драконами.",
	["En la costa de Durotar, soldados de Kul Tiras ocupan el Fuerte Tiragarde: una espina clavada en la tierra de la Horda."] = "На побережье Дуротара солдаты Кул-Тираса занимают Крепость Тирагарда — заноза в земле Орды.",
	["En la costa de Tanaris se esconden piratas de los Mares del Sur."] = "На побережье Танариса прячутся пираты Южных морей.",
	["En la costa del pantano hay naga, y no reciben bien a los curiosos."] = "На побережье болота есть наги, и любопытных они не жалуют.",
	["En la costa este vive una tribu trol amiga de la Horda, enemiga de los trols de Jintha'Alor."] = "На восточном побережье живет племя троллей, дружное с Ордой и враждебное троллям Джинта'Алора.",
	["En la costa oeste de Vallefresno, las Cavernas de Brazanegra fueron un templo de Elune; hoy están hundidas y llenas de naga."] = "На западном побережье Ясеневого леса Непроглядная Пучина когда-то была храмом Элуны; теперь она затоплена и полна наг.",
	["En la costa se ven ruinas de antiguos palacios élficos, medio hundidos en el mar."] = "На побережье видны руины древних эльфийских дворцов, наполовину ушедших в море.",
	["En la cueva del barco hay muchos piratas: no bajen todos de golpe al muelle."] = "В пещере с кораблем много пиратов: не спрыгивайте на причал все сразу.",
	["En la excavación de Ironband, los troggs salieron de la tierra y se quedaron con todo."] = "На раскопках Айронбенда трогги вылезли из-под земли и захватили все.",
	["En la granja de los Saldean, la vieja yegua Blanchy necesita avena. Es de las misiones más tiernitas de los Páramos."] = "На ферме Салдинов старой кобыле Бланш нужен овес. Одно из самых трогательных заданий Западного Края.",
	["En la guarida de Onyxia, a los lados hay nidos con huevos: si alguien los pisa salen dragoncitos... muchísimos."] = "В логове Ониксии по бокам гнезда с яйцами: если на них наступить, вылупятся дракончики... очень много.",
	["En la pelea, el juego te avisa"] = "В бою игра вас предупредит",
	["En la sala de la Liga de Expedicionarios de Forjaz hay biblioteca, mapas y un museo con fósiles gigantes."] = "В зале Лиги исследователей в Стальгорне есть библиотека, карты и музей с гигантскими окаменелостями.",
	["En la segunda parte mátenla a ella primero: cura mucho."] = "Во второй части убейте ее первой: она много лечит.",
	["En la subasta cuenta el precio más bajo que vio, menos la comisión (%d%%, estimada). Al desencantar usa tablas del juego clásico, también estimadas."] = "Для аукциона берется самая низкая увиденная цена минус комиссия (%d%%, примерно). Для распыления используются таблицы классической игры, тоже примерные.",
	["En la subasta, unos %s."] = "На аукционе — около %s.",
	["En la ventana y aquí. Si no estás entre ellos, tu fila sale al final."] = "В окне и здесь. Если вас среди них нет, ваша строка будет в конце.",
	["En las Cuevas de los Lamentos, el druida Naralex soñó con devolverle el verdor a Los Baldíos, y su sueño se volvió pesadilla."] = "В Пещерах Стенаний друид Наралекс мечтал вернуть Степям зелень, но его сон обернулся кошмаром.",
	["En las Guerras Trol, los altos elfos enseñaron magia a cien humanos para vencer juntos a los Amani. Fueron los primeros magos de la humanidad."] = "В Тролльих войнах высшие эльфы научили магии сотню людей, чтобы вместе победить Амани. Это были первые маги человечества.",
	["En las Mazmorras de Ventormenta los presos se amotinaron, y la guardia pide ayuda para calmar el desastre."] = "В Тюрьме Штормграда заключенные подняли бунт, и стража просит помочь навести порядок.",
	["En las Pozas de la Visión, bajo una de las mesetas, entrenan los magos y sacerdotes Renegados."] = "В Прудах Видений под одной из мес обучаются маги и жрецы Отрекшихся.",
	["En las cuevas de Cuna del Invierno viven yetis peludos y gruñones."] = "В пещерах Зимних Ключей живут косматые и ворчливые йети.",
	["En las cuevas de Feralas viven yetis, y los ogros Gordunni tienen sus campamentos en el norte."] = "В пещерах Фераласа живут йети, а у огров Гордунни лагеря на севере.",
	["En las cuevas nevadas de Dun Morogh viven trols de las nieves que no quieren a los enanos ni tantito."] = "В снежных пещерах Дун Морога живут снежные тролли, которые дворфов на дух не переносят.",
	["En las dos armas"] = "На обоих оружиях",
	["En las granjas del oeste hay calderos de la Plaga que siguen esparciendo la peste; la Alianza manda aventureros a destruirlos."] = "На западных фермах котлы Плети продолжают распространять чуму; Альянс посылает искателей приключений их уничтожить.",
	["En las ruinas de la ciudad de Alterac hoy mandan los ogros y el Sindicato, la banda de nobles caídos del viejo reino."] = "В руинах города Альтерак теперь хозяйничают огры и Синдикат — банда павшей знати старого королевства.",
	["En lo alto de la sierra hay un pico sagrado para los druidas elfos, donde anidan aves enormes."] = "Высоко в горах есть пик, священный для эльфийских друидов, где гнездятся огромные птицы.",
	["En lo más alto de la Montaña Roca Negra manda Nefarian, hijo de Alamuerte."] = "На самой вершине Черной горы правит Нефариан, сын Смертокрыла.",
	["En los mapas"] = "На картах",
	["En lugar de las del juego"] = "Вместо сумок игры",
	["En marcha"] = "В процессе",
	["En marcha hacia %s"] = "В пути: %s",
	["En mazmorra"] = "В подземелье",
	["En mazmorras y bandas"] = "В подземельях и рейдах",
	["En memoria"] = "В память",
	["En memoria de una gran perrita"] = "В память об одной замечательной собачке",
	["En mi zona"] = "В моей зоне",
	["En movimiento"] = "В движении",
	["En orco, «Lok'tar ogar» quiere decir «victoria o muerte»."] = "По-орочьи «Lok'tar ogar» значит «победа или смерть».",
	["En otra zona: %s"] = "В другой зоне: %s",
	["En pantalla"] = "На экране",
	["En pausa"] = "На паузе",
	["En pausa dentro de la instancia"] = "Пауза внутри подземелья",
	["En pausa por ahora"] = "Пока на паузе",
	["En pausa: hay otro addon de pesca activo"] = "Пауза: включен другой аддон рыбалки",
	["En plena Segunda Guerra, Gul'dan abandonó a la Horda para buscar la Tumba de Sargeras. Ahí lo despedazaron los demonios que encontró."] = "В разгар Второй войны Гул'дан бросил Орду, чтобы найти Гробницу Саргераса. Там его разорвали найденные им демоны.",
	["En posadas y ciudades acumulas XP descansada: ganas el doble de XP por enemigo hasta gastarla. Si cierras sesión aquí, también se acumula."] = "В тавернах и городах накапливается опыт за отдых: за каждого противника вы получаете вдвое больше опыта, пока он не закончится. Если выйти из игры здесь, он тоже накапливается.",
	["En posadas y ciudades juntas XP descansada: ganas el doble por enemigo hasta gastarla."] = "В тавернах и городах копится опыт за отдых: вдвое больше опыта за противника, пока он не кончится.",
	["En qué orden aparecen."] = "В каком порядке они появляются.",
	["En qué se gastan"] = "На что тратятся",
	["En silencio"] = "Без звука",
	["En solitario es lento: usa la varita para rematar."] = "В одиночку медленно: добивайте жезлом.",
	["En solitario, deja curas que duran en el tiempo y pelea con Cólera."] = "В одиночку накладывайте периодическое исцеление и сражайтесь Гневом.",
	["En solitario, pelea con choques y cúrate entre monstruos."] = "В одиночку сражайтесь шоками и лечитесь между монстрами.",
	["En su ficha toca «Agregar a mi ruta»."] = "На его странице нажмите «Добавить в мой маршрут».",
	["En sus inicios, una batalla del Valle de Alterac podía durar horas... ¡y hasta días!"] = "В первые дни битва в Альтеракской долине могла длиться часами... и даже днями!",
	["En tu arma"] = "На оружии",
	["En tu marco"] = "На вашей рамке",
	["En tu plan"] = "В вашем плане",
	["En tu registro"] = "В журнале заданий",
	["En tus bolsas"] = "В сумках",
	["En tus bolsas, el botín, el chat o cualquier enlace: Alt+clic abre la guía para conseguirlo o, si no hay, su ficha en la enciclopedia."] = "В сумках, добыче, чате или по любой ссылке: Alt+щелчок открывает гайд, как это получить, а если гайда нет — страницу в энциклопедии.",
	["En tus bolsas: úsala para aprenderla"] = "В сумках: используйте, чтобы изучить",
	["En un aviso"] = "Оповещением",
	["En un aviso y en el chat"] = "Оповещением и в чате",
	["En un cañón de Vallefresno, Grom mató al señor demonio Mannoroth y liberó a los orcos de su sangre maldita."] = "В каньоне Ясеневого леса Гром убил повелителя демонов Маннорота и освободил орков от его проклятой крови.",
	["En un valle de Frondavil cayeron infernales del cielo, y todavía se ven sus cráteres."] = "В одну из долин Оскверненного леса с неба падали инферналы, и их кратеры видны до сих пор.",
	["En un vuelo con escalas, una línea bajo el temporizador dice dónde es la siguiente parada y cuánto falta para llegar. Necesita el temporizador de vuelo encendido."] = "В полете с пересадками строка под таймером показывает, где следующая остановка и сколько до нее лететь. Нужен включенный таймер полета.",
	["En una aldea del sur del bosque, los vecinos parecen normales de día... y de noche se convierten en worgen."] = "В деревне на юге леса жители днем кажутся обычными... а ночью превращаются в воргенов.",
	["En una de las mesetas, los tauren honran a los espíritus de sus ancestros."] = "На одной из мес таурены чтят духов своих предков.",
	["En una instancia: la flecha vuelve al salir"] = "В подземелье: стрелка вернется после выхода",
	["En una isla de Azshara vive el duque Hydraxis, señor del agua; su gente te ayuda a apagar las runas del Núcleo de Magma."] = "На острове у Азшары живет герцог Гидраксис, повелитель воды; его народ помогает потушить руны Огненных Недр.",
	["En una pestaña nueva"] = "В новой вкладке",
	["En unos segundos aparece tu build."] = "Через несколько секунд появится ваш билд.",
	["En uso"] = "Используется",
	["En uso, a tu gusto"] = "Используется, на ваш вкус",
	["En vivo"] = "Вживую",
	["En vivo si estás con un banquero; si no, la última foto."] = "Вживую, если вы у банкира; иначе — последний снимок.",
	["En vuelo a %s"] = "Полёт в %s",
	["En vuelo: la flecha sigue al bajar"] = "В полете: стрелка продолжит после приземления",
	["En vuelo: la flecha sigue al bajar."] = "В полете: стрелка продолжит после посадки.",
	["Enanos"] = "Дворфы",
	["Encanta tu arma antes de pelear."] = "Зачаруйте оружие перед боем.",
	["Encantada"] = "Зачаровано",
	["Encantamiento"] = "Наложение чар",
	["Encantar a otros es un servicio: anúnciate en el chat de comercio de la ciudad."] = "Наложение чар для других — это услуга: предлагай ее в торговом чате города.",
	["Encender el registro"] = "Включить учет",
	["Encender la pesca"] = "Включить рыбалку",
	["Encender las recomendadas"] = "Включить рекомендуемые",
	["Encender una fogata"] = "Развести костер",
	["Encenderla"] = "Включить",
	["Encenderlos"] = "Включить их",
	["Encendida: entra al plan aunque el filtro la deje fuera. Apagada: queda fuera."] = "Вкл.: попадает в план, даже если фильтр ее исключает. Выкл.: остается вне плана.",
	["Encendido"] = "Включено",
	["Encendido: el doble clic mientras pescas lanza de nuevo y, con Mayús, Ctrl o Alt, recoge. Apagado: al revés."] = "Включено: двойной щелчок во время рыбалки забрасывает снова, а с Shift, Ctrl или Alt — вытаскивает. Выключено: наоборот.",
	["Enciclopedia"] = "Энциклопедия",
	["Enciende las comodidades recomendadas"] = "Включите рекомендуемые удобства",
	["Enciende los cambios de abajo en el cuadro que sale al pasar el ratón por un personaje o criatura."] = "Включает изменения ниже в подсказке, которая появляется при наведении курсора на персонажа или существо.",
	["Enciende los cambios de abajo en el probador (Ctrl + clic en un objeto)."] = "Включает изменения ниже в примерочной (Ctrl + щелчок по предмету).",
	["Enciende los cambios de abajo; cada uno se puede apagar por separado. Algunos addons acomodan sus botones al cuadrado después de /reload."] = "Включает изменения ниже; каждое можно выключить отдельно. Некоторые аддоны подстраивают свои кнопки под квадрат после /reload.",
	["Enciende primero la guía en el minimapa."] = "Сначала включите гайд на мини-карте.",
	["Enciende primero los servicios."] = "Сначала включите услуги.",
	["Enciéndela para ver en combate qué habilidad conviene ahora y cuáles siguen, en un ícono pequeño que puedes mover."] = "Включите, чтобы в бою видеть, какую способность лучше применить сейчас и какие дальше, на маленьком подвижном значке.",
	["Enciéndelo en el menú del juego: Opciones > %s > «%s». Alfa no lo cambia por ti: el medidor del juego lo lee en combate y fallaría."] = "Включите это в меню игры: Настройки > %s > «%s». Alfa не меняет это за вас: игровой измеритель читает настройку в бою, и возникла бы ошибка.",
	["Enciéndelos abajo, en Marcos, para ver a tu grupo con su vida y curar con un clic."] = "Включите их ниже, в разделе «Рамки», чтобы видеть здоровье группы и лечить одним щелчком.",
	["Enciéndelos en la página Curación."] = "Включите их на странице «Исцеление».",
	["Enciéndelos para ver a tu grupo con su vida y curar con un clic."] = "Включите их, чтобы видеть здоровье группы и лечить одним щелчком.",
	["Enemigo raro"] = "Редкий противник",
	["Enemigos menores"] = "Слабые противники",
	["Enfoque interno: tu siguiente hechizo es gratis y más crítico."] = "Внутреннее сосредоточение: следующее заклинание бесплатно и чаще критическое.",
	["Enraíza al monstruo y aléjate antes de lanzar tus hechizos largos."] = "Обездвижьте монстра корнями и отойдите, прежде чем произносить долгие заклинания.",
	["Entendido"] = "Понятно",
	["Entereza"] = "Стойкость",
	["Entorno"] = "Окружение",
	["Entra al juego con él una vez."] = "Зайдите в игру этим персонажем один раз.",
	["Entra con el registro limpio: entrega lo que ya tienes."] = "Входите с чистым журналом: сдайте то, что уже есть.",
	["Entra en el plan que termina y entrega tus misiones por el camino más corto, con lo que pide antes."] = "Попадает в план, который выполняет и сдает ваши задания кратчайшим путем, вместе с тем, что для него нужно заранее.",
	["Entrada"] = "Вход",
	["Entrada enemiga"] = "Вход на вражеской территории",
	["Entradas de mazmorras"] = "Входы в подземелья",
	["Entradas en el minimapa"] = "Входы на мини-карте",
	["Entradas y salidas"] = "Входы и выходы",
	["Entraron %s, con lo que piden antes de entregarlas."] = "Добавлены %s — вместе с тем, что нужно до их сдачи.",
	["Entraste a %s"] = "Вы вошли: %s",
	["Entraste a %s."] = "Вы вошли: %s.",
	["Entrañas son las criptas y catacumbas bajo la antigua capital de Lordaeron."] = "Подгород — это склепы и катакомбы под древней столицей Лордерона.",
	["Entrañas tiene barrios para magos, pícaros, guerreros y boticarios, y en el anillo central están el banco y la casa de subastas."] = "В Подгороде есть кварталы магов, разбойников, воинов и аптекарей, а в центральном кольце — банк и аукцион.",
	["Entre Entrañas y Grom'gol también hay zepelín: así bajas al sur sin cruzar todo el continente."] = "Между Подгородом и Гром'голом тоже летает дирижабль: так можно попасть на юг, не пересекая весь континент.",
	["Entre los druidas están los de la Garra, que se vuelven osos, y los del Espolón, que toman forma de cuervo."] = "Среди друидов есть друиды Когтя, которые становятся медведями, и друиды Пера, принимающие облик ворона.",
	["Entrega tus %d misiones listas"] = "Сдайте готовые задания: %d",
	["Entregada"] = "Сдано",
