	["Entró %s, con lo que pide antes de entregarla."] = "Добавлено %s — вместе с тем, что нужно до его сдачи.",
	["Envenena y lanza rayos: quita el veneno si puedes."] = "Он отравляет и бьет молниями: снимайте яд, если можете.",
	["Equilibrada"] = "Сбалансированный",
	["Equilibrado"] = "Сбалансированно",
	["Equilibrado: se ve bien y corre bien en casi cualquier equipo."] = "Сбалансированный: хорошо выглядит и хорошо идет почти на любом ПК.",
	["Equilibrio"] = "Баланс",
	["Equilibrio para subir"] = "Баланс для прокачки",
	["Equipa tu caña de pescar"] = "Возьмите удочку в руки",
	["Equipo"] = "Экипировка",
	["Equipo %d %%"] = "Снаряжение %d %%",
	["Equipo a punto de romperse."] = "Экипировка вот-вот сломается.",
	["Equipo de pesca"] = "Рыболовное снаряжение",
	["Equipo y cebos"] = "Снаряжение и приманки",
	["Equipo y estadísticas"] = "Снаряжение и характеристики",
	["Equipo, consumibles, misiones, materiales... con encabezados que se pliegan."] = "Снаряжение, расходуемые предметы, задания, материалы... под сворачиваемыми заголовками.",
	["Equitación"] = "Верховая езда",
	["Equitación de aprendiz (nivel 40)"] = "Верховая езда: ученик (40-й уровень)",
	["Equitación de oficial (la rápida, nivel 60)"] = "Верховая езда: подмастерье (быстрая, 60-й уровень)",
	["Eranikus, el consorte de Ysera, quedó atrapado en la pesadilla; su sombra ronda el Templo de Atal'Hakkar."] = "Эраникус, супруг Изеры, оказался в ловушке кошмара; его тень бродит по Храму Атал'Хаккара.",
	["Eres de la manada"] = "Вы в стае",
	["Eres nivel %d"] = "У вас %d-й уровень",
	["Eres nivel %d y se recomienda el %d: desde ahí cuenta así."] = "Ваш уровень — %d, рекомендуется %d: начиная с него, считается так.",
	["Eres nivel %d."] = "У вас %d-й уровень.",
	["Error"] = "Ошибка",
	["Errores de Lua de Alfa en esta sesión:"] = "Ошибки Lua в Alfa за этот сеанс:",
	["Errores de Lua de Alfa en esta sesión: ninguno"] = "Ошибки Lua в Alfa за этот сеанс: нет",
	["Es corta y está dentro de Ventormenta. Los presos están en celdas a los lados: avancen despacio."] = "Короткое подземелье внутри Штормграда. Заключенные сидят в камерах по бокам: продвигайтесь медленно.",
	["Es de la otra facción"] = "Это задание другой фракции",
	["Es de una misión."] = "Это предмет для задания.",
	["Es el jefe que pide una misión de la Alianza: revisa tus misiones antes de entrar."] = "Этот босс нужен для задания Альянса: проверьте свои задания перед входом.",
	["Es el primer jefe y es sencillo. Al morir, el prisionero de tu facción abre la puerta del patio."] = "Это первый босс, и он простой. После его смерти пленник вашей фракции открывает дверь во двор.",
	["Es el primer reto: con él se abre el Legado."] = "Это первое испытание: с него открывается «Наследие».",
	["Es el punto %d de %d de tu build."] = "Это очко %d из %d вашего билда.",
	["Es el que toca ahora."] = "Его нужно взять сейчас.",
	["Es el último del Cementerio. Lanza llamas a su alrededor: si peleas de lejos, quédate lejos."] = "Последний босс Кладбища. Он выпускает пламя вокруг себя: если сражаетесь на расстоянии, держитесь подальше.",
	["Es el único lobo a la vista."] = "Это единственный волк в поле зрения.",
	["Es grande y es fácil perderse: sigan a una sola persona y no corran solos."] = "Подземелье большое, в нем легко заблудиться: следуйте за одним человеком и не убегайте поодиночке.",
	["Es la máquina de Sneed: rómpela y él saldrá a pelear."] = "Это машина Снида: сломайте ее, и он выйдет сражаться.",
	["Es la primera mazmorra de la Horda: corta y buena para aprender a jugar en grupo."] = "Это первое подземелье Орды: короткое и хорошее для обучения игре в группе.",
	["Es la primera mazmorra grande de la Alianza: avancen despacio y tiren un grupo a la vez."] = "Это первое большое подземелье Альянса: продвигайтесь медленно и выманивайте по одной группе.",
	["Es larga y tiene dos entradas. Muchos enemigos son de piedra y pegan fuerte."] = "Длинное подземелье с двумя входами. Многие противники каменные и бьют сильно.",
	["Es larga y tiene muchos robots: algunos ponen bombas o hacen sonar alarmas que traen más enemigos."] = "Длинное подземелье с множеством роботов: некоторые ставят бомбы или включают тревогу, которая зовет еще противников.",
	["Es lento: si peleas de lejos, atácalo mientras se acerca."] = "Он медленный: если сражаетесь на расстоянии, атакуйте его, пока он приближается.",
	["Es muy veloz: frénalo si tu clase puede."] = "Он очень быстрый: замедлите его, если ваш класс это умеет.",
	["Es opcional. Si dices que sí, los lobos de La Jauría que usan Alfa ven a tu personaje en el mapa de WoW, como ves a tu grupo, y pueden llegar a donde estás con la flecha; y tú a ellos. Alfa solo comparte dónde anda tu personaje dentro del juego: la zona, el punto en el mapa, su nivel y su clase. Nada de tu ubicación real, tu computadora ni tu cuenta."] = "Это необязательно. Если вы согласитесь, волки La Jauría, которые пользуются Alfa, будут видеть вашего персонажа на карте WoW, как вы видите свою группу, и смогут добраться до вас по стрелке, а вы — до них. Alfa передает только то, где ваш персонаж находится в игре: зону, точку на карте, его уровень и класс. Никогда — ваше реальное местоположение, компьютер или учетную запись.",
	["Es opcional: tu personaje aparece en el mapa de WoW de los lobos de La Jauría que usan Alfa, y ellos en el tuyo, para encontrarse y llegar con la flecha. Solo se comparte dónde anda tu personaje dentro del juego (zona, punto en el mapa, nivel y clase), nunca tu ubicación real ni nada de tu computadora, y nunca dentro de mazmorras. Va por un canal oculto que no sale en el chat, aunque alguien que entre a él con otro addon podría verlo. Tu grupo se ve siempre. Lo cambias cuando quieras en La Jauría."] = "Это по желанию: ваш персонаж появляется на карте WoW у волков La Jauría, которые пользуются Alfa, а они — на вашей, чтобы находить друг друга и добираться по стрелке. Передаётся только то, где ваш персонаж находится в игре (зона, точка на карте, уровень и класс), никогда не ваше реальное местоположение и ничего с вашего компьютера, и никогда в подземельях. Это идёт через скрытый канал, который не показывается в чате, хотя тот, кто войдёт в него с другим аддоном, может это увидеть. Вашу группу видно всегда. Изменить можно в любой момент в La Jauría.",
	["Es para niveles %s y vas en el %d: te faltan %d niveles."] = "Для уровней %s, а у вас %d: осталось %d ур.",
	["Es para otra raza."] = "Для другой расы.",
	["Es raro del Cementerio y no siempre aparece."] = "Редкий босс Кладбища, появляется не всегда.",
	["Es raro del Cementerio y no siempre aparece. Envenena: quita el veneno."] = "Редкий босс Кладбища, появляется не всегда. Отравляет: снимайте яд.",
	["Es raro del Cementerio y no siempre aparece. Puede silenciar a quien lanza hechizos."] = "Редкий босс Кладбища, появляется не всегда. Может накладывать немоту на заклинателей.",
	["Es raro y aparece pocas veces. Usa fuego a su alrededor."] = "Редкий, появляется нечасто. Использует огонь вокруг себя.",
	["Es raro y está en una cueva escondida. Es un murciélago que pega rápido."] = "Редкий, находится в скрытой пещере. Это летучая мышь, которая быстро бьет.",
	["Es raro y no siempre aparece. Pega muy fuerte para su nivel: tírenlo con cuidado."] = "Редкий, появляется не всегда. Бьет очень сильно для своего уровня: выманивайте его осторожно.",
	["Es raro y no siempre está. Golpea fuerte a todos los que tiene enfrente."] = "Редкий, бывает не всегда. Сильно бьет всех перед собой.",
	["Es raro. Pone un tótem de tierra: rómpelo."] = "Редкий. Ставит тотем земли: разбейте его.",
	["Es raro: no siempre está. Duerme a los jugadores y explota con magia a su alrededor."] = "Редкий: бывает не всегда. Усыпляет игроков и взрывается магией вокруг себя.",
	["Es sencillo: buen momento para beber agua antes del último jefe."] = "Простой босс: хороший момент попить воды перед последним боссом.",
	["Es un brujo que lanza hechizos: interrúmpelo si tu clase puede (Patada, Golpe de escudo, Choque de tierra...)."] = "Это заклинатель: прерывайте его, если ваш класс это умеет (Пинок, Удар щитом, Земной шок...).",
	["Es un chamán con tótems: rompan los tótems, son fáciles de matar."] = "Это шаман с тотемами: разбейте тотемы, их легко уничтожить.",
	["Es un enano con escudo: aguanta mucho pero no tiene trucos."] = "Это дворф со щитом: очень живучий, но без хитростей.",
	["Es un enemigo fuerte de la mina: trátenlo como un jefe pequeño."] = "Сильный противник в шахте: относитесь к нему как к маленькому боссу.",
	["Es un grupo: cada uno suelta su propio botín."] = "Это группа: каждый роняет свою добычу.",
	["Es un paladín: se cura con luz sagrada. Interrumpe su curación."] = "Это паладин: лечит себя Светом небес. Прерывайте его лечение.",
	["Es un sátiro rápido que envenena: si tu clase quita venenos, úsalo."] = "Это быстрый сатир, который отравляет: если ваш класс снимает яды, используйте это.",
	["Es un trogg que lanza rayos: interrúmpelo."] = "Это трогг, который бьет молниями: прерывайте его.",
	["Es una mejora para ti"] = "Это улучшение для вас",
	["Es una montura de tu clase: pregunta a tu instructor de clase cuándo y cómo se consigue."] = "Это классовый транспорт: спросите у учителя своего класса, когда и как его получить.",
	["Es una tortuga gigante con mucha armadura: pega lento pero duro."] = "Это гигантская черепаха с толстой броней: бьет медленно, но сильно.",
	["Es una tortuga muy dura, pero solo golpea: no tiene trucos."] = "Очень крепкая черепаха, но она только бьет: без хитростей.",
	["Esa cadena no trae ninguna estadística que Alfa puntúe."] = "В этой строке нет характеристик, которые оценивает Alfa.",
	["Esa fila todavía no se abre: faltan puntos en esa rama."] = "Этот ряд еще не открыт: в этой ветке не хватает очков.",
	["Esa tecla ya tiene dueño"] = "Эта клавиша уже занята",
	["Esbirros enemigos"] = "Прислужники противников",
	["Escala de estadísticas"] = "Шкала характеристик",
	["Escalas:"] = "Остановки:",
	["Escaneando..."] = "Сканирование...",
	["Escanear ahora"] = "Сканировать сейчас",
	["Escanear con Alfa"] = "Сканировать с Alfa",
	["Escaneo completo: %s objetos con precio (%s subastas)."] = "Полное сканирование: предметов с ценой — %s (лотов: %s).",
	["Escarcha"] = "Лед",
	["Escarcha para subir"] = "Лед для прокачки",
	["Esconde las placas y los nombres de los PNJ mientras pescas (los enemigos hostiles conservan su nombre), para ver y tocar mejor el corcho."] = "Скрывает индикаторы и имена NPC во время рыбалки (враждебные противники сохраняют имена), чтобы поплавок было лучше видно и легче было по нему щелкнуть.",
	["Esconde lo que pide más habilidad de la que tienes. Sin esto se ve gris y tenue."] = "Скрывает то, что требует навыка выше вашего. Без этой настройки оно показано серым и бледным.",
	["Escribe %s o haz clic en el lobo del minimapa para abrirla. Empieza en Hoy, con lo que toca a tu clase; %s muestra u oculta la ventana de guía."] = "Введите %s или щелкните по волку на мини-карте, чтобы открыть его. Оно открывается на вкладке «Сегодня» с тем, что нужно вашему классу; %s показывает или скрывает окно гайда.",
	["Escribe %s y cuéntanos en el Discord de La Jauría."] = "Введите %s и расскажите нам в Discord La Jauría.",
	["Escribe al menos dos letras."] = "Введите хотя бы две буквы.",
	["Escribe arriba el nombre de una mazmorra para buscarla."] = "Введите название подземелья сверху, чтобы найти его.",
	["Escribe cuánto oro (1 o más)."] = "Введите, сколько золота (1 или больше).",
	["Escribe el número que quieras y presiona Enter."] = "Введите нужное число и нажмите Enter.",
	["Escribe el top %d en el chat de tu grupo o banda."] = "Пишет топ-%d в чат группы или рейда.",
	["Escribe en el chat del grupo cuando terminas un objetivo de una misión compartida. Viene apagado para no llenar el chat de nadie."] = "Пишет в чат группы, когда вы выполняете цель общего задания. По умолчанию выключено, чтобы ни у кого не засорять чат.",
	["Escribe tu nota."] = "Напишите заметку.",
	["Escribe un nivel (2 o más)."] = "Введите уровень (2 или больше).",
	["Escribe un nombre corto para reconocerla."] = "Введите короткое название, чтобы его узнавать.",
	["Escribir a %s"] = "Написать: %s",
	["Escuchar"] = "Слушать",
	["Escuchar el aullido"] = "Послушать вой",
	["Escudo"] = "Щит",
	["Escudo de relámpagos"] = "Щит молний",
	["Escudo y defensa: aguantas a todos los monstruos para que tu grupo no sufra."] = "Щит и защита: вы держите всех монстров, чтобы группа не страдала.",
	["Escudo y luz sagrada: un tanque muy resistente que recupera su propio maná."] = "Щит и Свет: очень крепкий танк, который сам восполняет свою ману.",
	["Escudos y curas preventivas: aguantas mucho y apoyas al grupo."] = "Щиты и упреждающее исцеление: вы долго держитесь и поддерживаете группу.",
	["Ese build es para otra clase."] = "Этот билд для другого класса.",
	["Ese talento necesita antes otro talento completo (la flecha del árbol)."] = "Для этого таланта сначала нужен другой талант целиком (стрелка в дереве).",
	["Ese texto es demasiado largo para un build."] = "Этот текст слишком длинный для билда.",
	["Ese texto es demasiado largo para una cadena de escala."] = "Этот текст слишком длинный для строки шкалы.",
	["Ese texto no es una ruta de Alfa."] = "Этот текст не является маршрутом Alfa.",
	["Esmeralda"] = "Изумрудный",
	["Eso no es una cadena de build de Alfa. Empieza con ALFA1;"] = "Это не строка билда Alfa. Она начинается с ALFA1;",
	["Eso no es una cadena de escala de estadísticas. Empieza con ( Pawn: v1: \"Nombre\": ..."] = "Это не строка шкалы характеристик. Она начинается с ( Pawn: v1: \"Название\": ...",
