	["Estilo y sonido"] = "Стиль и звук",
	["Esto no se puede cambiar en combate. Inténtalo al terminar la pelea."] = "Это нельзя изменить в бою. Попробуйте после окончания схватки.",
	["Esto no se puede vincular."] = "Это нельзя вставить ссылкой.",
	["Estos filtros los dibuja Alfa, no el juego: quedan detrás de toda la interfaz (nunca la tapan) y también se ven con la interfaz oculta (Alt+Z), para tus capturas."] = "Эти фильтры рисует Alfa, а не игра: они под всем интерфейсом (никогда его не закрывают) и видны даже со скрытым интерфейсом (Alt+Z) — для ваших скриншотов.",
	["Está en el Cementerio. Pone un dolor de sombras que hace daño con el tiempo."] = "Находится на Кладбище. Накладывает теневую боль, которая наносит урон со временем.",
	["Está en el agua, junto a la cascada: llévenlo a tierra antes de pelear."] = "Он в воде, у водопада: выманите его на сушу перед боем.",
	["Está en la Armería. Cuando grita, gira con su hacha y golpea a todos los que están cerca: aléjate."] = "Находится в Оружейной. Когда он кричит, то вращается с топором и бьет всех рядом: отойдите.",
	["Está en la Biblioteca y llega con sus perros: mátenlos primero o usen ataques en área."] = "Находится в Библиотеке и приходит со своими псами: убейте их первыми или используйте атаки по области.",
	["Está escondido en la Catedral. Pone maldiciones y se cura: interrúmpelo."] = "Спрятан в Соборе. Накладывает проклятия и лечит себя: прерывайте его.",
	["Está lleno de jabaespines y sus túneles de espinos: tiren de pocos a la vez."] = "Здесь полно свинобразов и их колючих туннелей: выманивайте понемногу.",
	["Está rodeado de goblins que trabajan: tiren a esos goblins primero, de uno en uno."] = "Его окружают гоблины-рабочие: сначала выманите этих гоблинов, по одному.",
	["Está rodeado de múrlocs: tiren a sus amigos antes que a él."] = "Его окружают мурлоки: выманите его приятелей раньше него.",
	["Estás aquí"] = "Вы здесь",
	["Estás con un banquero: desde su ventana depositas lo que quieras con un clic."] = "Вы у банкира: из его окна можно положить что угодно одним щелчком.",
	["Estás dentro"] = "Вы внутри",
	["Estás descansando"] = "Вы отдыхаете",
	["Estás en combate. Los talentos solo se cambian fuera de combate: termina la pelea y vuelve a intentarlo."] = "Вы в бою. Таланты меняются только вне боя: закончите бой и попробуйте снова.",
	["Estás en combate: busca el equipo al terminar la pelea."] = "Вы в бою: ищите экипировку после окончания боя.",
