	["Guerrero"] = "Воин",
	["Guiarme"] = "Вести меня",
	["Gul'dan fue el primer brujo orco, y su historia no terminó nada bien. Tú úsalo con más cabeza."] = "Гул'дан был первым орком-чернокнижником, и его история закончилась совсем не хорошо. Пользуйся этой силой с умом.",
	["Gul'dan fundó el Consejo de la Sombra, un grupo de brujos que movía a la Horda desde las sombras."] = "Гул'дан основал Совет Теней — группу чернокнижников, которая управляла Ордой из тени.",
	["Guía"] = "Гайд",
	["Guía a tu manada"] = "Ведите свою стаю",
	["Guía abierta en una pestaña nueva: sigue la flecha."] = "Гайд открыт в новой вкладке: следуйте за стрелкой.",
