	["Habilidades más baratas."] = "Более дешевые способности.",
	["Habilidades más baratas: más golpes de amenaza."] = "Более дешевые способности: больше ударов на угрозу.",
	["Habilidades nuevas por aprender: %d. Tu entrenador te espera."] = "Новых способностей для изучения: %d. Тебя ждет учитель.",
	["Habilidades por entrenar"] = "Навыки к изучению",
	["Habilidades que vigila la ayuda de Blizzard"] = "Способности, за которыми следит помощник Blizzard",
	["Habitual"] = "Привычка",
	["Habla con %s"] = "Разговор: %s",
	["Habla con el maestro de vuelo de cada pueblo nuevo: así aprendes la ruta."] = "Говори с распорядителем полетов в каждом новом городке: так ты открываешь маршрут.",
	["Habla con un banquero para comprarla."] = "Поговорите с банкиром, чтобы купить.",
	["Hablar"] = "Разговор",
	["Hace heridas que sangran: vigila la vida del tanque."] = "Наносит кровоточащие раны: следите за здоровьем танка.",
	["Hace mil años, en la Guerra de las Arenas Movedizas, los elfos y los dragones encerraron a los qiraji tras el Muro del Escarabajo."] = "Тысячу лет назад, в Войне Зыбучих Песков, эльфы и драконы заперли киражи за Стеной Скарабея.",
	["Hace más de diez mil años todas las tierras eran un solo continente: Kalimdor, que en élfico quiere decir «tierra de la eterna luz de las estrellas»."] = "Больше десяти тысяч лет назад все земли были одним континентом — Калимдором, что по-эльфийски значит «земля вечного звездного света».",
	["Hace sangrar al enemigo: ponlo al empezar la pelea."] = "Вызывает кровотечение у противника: наложите в начале боя.",
	["Hace sangrar mucho: vale la pena con enemigos que duran."] = "Сильное кровотечение: стоит того против живучих противников.",
	["Hace siglos, Aegwynn venció a un avatar de Sargeras y escondió su cuerpo en la Tumba de Sargeras, en las Islas Abruptas."] = "Века назад Эгвин победила аватара Саргераса и спрятала его тело в Гробнице Саргераса на Расколотых островах.",
	["Hacen falta al menos 3 lugares distintos de ese recurso en la zona."] = "Нужно хотя бы 3 разных места с этим ресурсом в зоне.",
	["Hacer mazmorras con tu grupo da botín, misiones y reputación: es farmeo con plática incluida."] = "Подземелья с группой дают добычу, задания и репутацию: это фарм с разговорами в придачу.",
	["Hacer oro"] = "Заработать золото",
	["Haces de luz entre árboles, nubes y montañas."] = "Лучи света сквозь деревья, облака и горы.",
	["Hacha de dos manos"] = "Двуручный топор",
	["Hacha de una mano"] = "Одноручный топор",
	["Hacia %s"] = "В %s",
	["Hacia %s (niv. %s)"] = "В %s (ур. %s)",
	["Hacia abajo"] = "Вниз",
	["Hacia arriba"] = "Вверх",
	["Hacia dónde se acomodan tus compañeros."] = "В какую сторону выстраиваются союзники.",
	["Hacia:"] = "Куда:",
	["Hacia: %s"] = "Куда: %s",
	["Halloween recuerda el día en que los Renegados se liberaron del Rey Exánime: por eso queman al Hombre de Mimbre."] = "Тыквовин отмечает день, когда Отрекшиеся освободились от Короля-лича: поэтому они сжигают Плетеного человека.",
	["Hamuul Tótem de Runa, el archidruida de Cima del Trueno, fue de los primeros tauren aceptados en el Círculo Cenarion."] = "Хамуул Рунический Тотем, верховный друид Громового Утеса, был одним из первых тауренов, принятых в Круг Кенария.",
	["Hasta dónde llegan las montañas lejanas."] = "Как далеко видны дальние горы.",
	["Hasta dónde puedes alejar la cámara con la rueda. El juego puede limitarlo: Alfa muestra el valor que de verdad quedó."] = "Насколько далеко можно отдалить камеру колесом. Игра может это ограничить: Alfa показывает реально примененное значение.",
	["Hasta dónde se dibuja el mundo. Es lo que más FPS cuesta."] = "Как далеко прорисовывается мир. Сильнее всего влияет на FPS.",
	["Hasta dónde se dibuja el pasto. Más lejos, menos «alfombra» que aparece al caminar."] = "Как далеко прорисовывается трава. Чем дальше, тем меньше «ковра», появляющегося при ходьбе.",
	["Hasta el alfa se cae. Lo importante es levantarse. ¡Vamos!"] = "Даже альфа падает. Главное — подняться. Вперед!",
	["Hasta el nivel 20 usa un arma de dos manos; luego cambia a dos armas de una mano."] = "До 20 уровня используйте двуручное оружие, затем перейдите на два одноручных.",
	["Hasta mi nivel"] = "До моего уровня",
	["Hasta qué distancia se ven las placas de nombre. El juego puede limitarlo."] = "На каком расстоянии видны индикаторы здоровья. Игра может это ограничить.",
	["Hasta qué nivel"] = "До какого уровня",
	["Hay enemigos que se convierten en lobos y otros que asustan: no corran si los asustan, esperen."] = "Одни противники превращаются в волков, другие пугают: если вас напугали, не паникуйте, переждите.",
	["Hay mucha agua: si nadas bajo el agua, mira tu barra de respiración y sube a tomar aire."] = "Здесь много воды: плавая под водой, следите за полосой дыхания и всплывайте за воздухом.",
	["Hay muchas tribus trol: Amani, Gurubashi, Furiarena, Zandalar... y casi todas pelean entre sí."] = "Племен троллей много: Амани, Гурубаши, Бешеные Пески, Зандалар... и почти все враждуют между собой.",
	["Hay muchos no-muertos y jabaespines: lleven algo para quitar enfermedades si su grupo puede."] = "Здесь много нежити и свинобразов: возьмите средство от болезней, если ваша группа может.",
	["Hay muchos troggs y elementales de fuego juntos: tiren de uno o dos grupos a la vez, no más."] = "Трогги и огненные элементали стоят рядом: выманивайте одну-две группы за раз, не больше.",
	["Hay nueve clases en el Clásico, pero solo la Alianza tiene paladines y solo la Horda tiene chamanes."] = "В классике девять классов, но паладины есть только у Альянса, а шаманы — только у Орды.",
	["Hay una guía de Alfa"] = "Есть гайд Alfa",
	["Haz clic derecho (o Mayús+clic) en el mapa donde quieras uno: le pones nombre, ícono y color, y la flecha te lleva cuando quieras."] = "Щелкните правой кнопкой (или Shift+щелчок) по карте там, где нужен маркер: задайте имя, значок и цвет, и стрелка поведет вас туда, когда захотите.",
	["Haz clic en un marco de ejemplo"] = "Щелкните по образцу рамки",
	["Haz clic y pulsa la tecla que quieras (Esc cancela). Clic derecho la quita."] = "Щелкните и нажмите нужную клавишу (Esc — отмена). Правый щелчок убирает ее.",
	["Haz clic y pulsa la tecla, un botón del ratón o la rueda (con Mayús, Ctrl o Alt si quieres). Esc cancela; clic derecho la quita."] = "Щелкните и нажмите клавишу, кнопку мыши или колесо (с Shift, Ctrl или Alt, если хотите). Esc — отмена; правый щелчок — убрать.",
	["Haz doble clic derecho en el mundo para lanzar la caña, sin usar la tecla. Nunca en combate ni en vuelo."] = "Дважды щелкните правой кнопкой мыши в мире, чтобы забросить удочку без клавиши. Никогда в бою и в полете.",
	["Hecha"] = "Пройдено",
	["Hecha %d veces"] = "Пройдено раз: %d",
	["Hechas"] = "Пройденные",
	["Hechizo del preajuste"] = "Заклинание из набора",
	["Hechizo desconocido"] = "Неизвестное заклинание",
	["Hechizo elegido por ti"] = "Заклинание на ваш выбор",
	["Hechizo nuevo para tus clics de Curación. Ábrelo en /alfa curacion."] = "Новое заклинание для ваших щелчков «Исцеления». Откройте /alfa curacion.",
	["Hechizos de sombras que hacen daño con el tiempo: el sacerdote que mejor sube en solitario, casi sin descansar."] = "Заклинания тьмы с периодическим уроном: жрец, который лучше всех качается в одиночку, почти без отдыха.",
	["Hechizos de tu mascota"] = "Заклинания питомца",
	["Hechizos desde lejos y raíces para que el monstruo no te alcance. Al final llega la forma de lechúcico."] = "Заклинания издалека и корни, чтобы монстр до вас не добрался. В конце приходит облик лунного совуха.",
	["Hecho"] = "Готово",
	["Hemet Nesingwary organiza safaris por toda la Vega: sus encargos de cazar panteras, tigres y raptores son famosos."] = "Хемет Несингвари устраивает сафари по всей Тернистой долине: его заказы на пантер, тигров и ящеров знамениты.",
	["Hemorragia: suma puntos de combo y el enemigo recibe más daño."] = "Кровоизлияние: дает очки серии, и противник получает больше урона.",
	["Hender armadura más barato."] = "Более дешевый Раскол брони.",
	["Hender armadura más barato: amenaza constante."] = "Более дешевый Раскол брони: постоянная угроза.",
	["Hender armadura más barato: más amenaza a varios enemigos."] = "Более дешевый Раскол брони: больше угрозы на нескольких противниках.",
	["Hender armadura: amenaza constante y el enemigo recibe más daño."] = "Раскол брони: постоянная угроза, и противник получает больше урона.",
	["Herboristería"] = "Травничество",
	["Herboristería combina bien con Alquimia, y también con Desollar o Minería para recolectar el doble."] = "Травничество хорошо сочетается с алхимией, а также со снятием шкур или горным делом, чтобы собирать вдвое больше.",
	["Herramienta"] = "Инструмент",
	["Herramientas"] = "Инструменты",
	["Herrería"] = "Кузнечное дело",
	["Herrería fabrica armas y armadura de placas muy buenas para tu nivel, y Minería te da el material gratis."] = "Кузнечное дело создает отличное оружие и латы для вашего уровня, а Горное дело дает материалы бесплатно.",
	["Herrería fabrica escudos y piezas resistentes."] = "Кузнечное дело создает щиты и прочные вещи.",
	["Herrería fabrica escudos y placas con defensa y aguante, justo lo que un tanque necesita."] = "Кузнечное дело создает щиты и латы с защитой и выносливостью — как раз то, что нужно танку.",
	["Herrería y Minería van de la mano: tú sacas el metal y tú lo forjas."] = "Кузнечное дело и горное дело идут рука об руку: ты добываешь металл, ты же его и куешь.",
	["Hielo"] = "Лед",
	["Hierbas"] = "Травы",
	["Historias"] = "Истории",
	["Historias de tus misiones"] = "Истории твоих заданий",
	["Historias guardadas"] = "Сохраненные истории",
	["Historias y datos curiosos"] = "Истории и любопытные факты",
	["Hogger es un gnoll de Elwynn tan temido que, para muchos aventureros, fue su primer gran reto."] = "Хоггер — гнолл Элвиннского леса, которого так боятся, что для многих искателей приключений он стал первым серьезным испытанием.",
	["Hombros"] = "Плечи",
	["Honor"] = "Честь",
	["Horarios de barcos y zepelines"] = "Расписание кораблей и дирижаблей",
	["Horda"] = "Орда",
	["Hoy"] = "Сегодня",
	["Hoy en números"] = "Сегодня в цифрах",
	["Hoy te guía"] = "«Сегодня» ведет вас",
	["Hoy te pone tu siguiente paso primero, y en combate ninguna ventana de Alfa te deja atrapado."] = "«Сегодня» показывает ваш следующий шаг первым, а в бою ни одно окно Alfa больше не запирает вас.",
	["Hoy, Aventura, Personaje, Mundo, Oficios y Manada en una sola ventana: %s o el lobo del minimapa."] = "«Сегодня», «Приключения», «Персонаж», «Мир», «Профессии» и «Стая» в одном окне: %s или волк на мини-карте.",
	["Hoy, a tu clase"] = "«Сегодня» — для вашего класса",
	["Huele a pan recién hecho por aquí… se me antoja."] = "Здесь пахнет свежим хлебом… так и хочется.",
	["Huele a salchichas asadas por aquí… ¿o es mi imaginación?"] = "Здесь пахнет жареными сосисками… или мне кажется?",
	["Huella"] = "След лапы",
	["Humanos"] = "Люди",
	["Humo, agua y efectos se funden con lo que tocan en lugar de cortarse en seco."] = "Дым, вода и эффекты плавно сливаются с тем, чего касаются, а не обрываются резко.",
	["Huracán: golpea a todos a tu alrededor."] = "Вихрь: бьет всех вокруг вас.",
	["Háblame de mi gente"] = "Расскажи о моем народе",
	["Iconos de viaje en el minimapa"] = "Значки перемещений на мини-карте",
	["Idioma"] = "Язык",
	["Igual que Alfa"] = "Как в Alfa",
	["Igual que lo tuyo"] = "Как у вас",
	["Igual que los otros señores: lanza rayos y se cura. Interrumpe su curación."] = "Как и другие повелители: бьет молниями и лечит себя. Прерывайте его лечение.",
	["Illidan absorbió el poder del Cráneo de Gul'dan y se volvió mitad demonio. Por eso Malfurion lo desterró."] = "Иллидан поглотил силу Черепа Гул'дана и стал наполовину демоном. Поэтому Малфурион изгнал его.",
	["Illidan guardó agua del Pozo antes de su caída y creó uno nuevo en Hyjal. Por eso Malfurion lo encerró bajo tierra durante diez mil años."] = "Иллидан сберег воду Источника перед его гибелью и создал новый на Хиджале. Поэтому Малфурион заточил его под землей на десять тысяч лет.",
	["Illidan se fue a Terrallende, lo que quedó de Draenor, y ahí se hizo de un ejército propio."] = "Иллидан ушел в Запределье — то, что осталось от Дренора, — и собрал там собственную армию.",
	["Illidan, el gemelo de Malfurion, amaba a Tyrande, pero ella eligió a su hermano. Esa herida lo acompañó por diez mil años."] = "Иллидан, близнец Малфуриона, любил Тиранду, но она выбрала его брата. Эта рана была с ним десять тысяч лет.",
	["Imagen HDR"] = "Вывод HDR",
	["Importa una cadena de escala de estadísticas y usa, renombra, exporta o borra las escalas que tienes."] = "Импортируйте строку шкалы характеристик, а также используйте, переименовывайте, экспортируйте или удаляйте имеющиеся шкалы.",
	["Importado"] = "Импортировано",
	["Importado: %s. Ya puedes seguirlo."] = "Импортирован: %s. Можно следовать ему.",
	["Importar"] = "Импорт",
	["Importar un build"] = "Импортировать билд",
	["Importar una ruta"] = "Импортировать маршрут",
	["Importar..."] = "Импорт...",
	["Inclina la cámara al subir y bajar cuestas."] = "Наклоняет камеру на подъемах и спусках.",
	["Ingeniería"] = "Инженерное дело",
	["Ingeniería da aturdimientos y trucos que ganan duelos; Minería da el material."] = "Инженерное дело дает оглушения и хитрости, которые выигрывают дуэли; Горное дело дает материалы.",
	["Ingeniería da granadas y redes para controlar al rival; Minería da el material."] = "Инженерное дело дает гранаты и сети для контроля противника; Горное дело дает материалы.",
	["Ingeniería da granadas, redes y bombas que deciden peleas contra jugadores; Minería da el material."] = "Инженерное дело дает гранаты, сети и бомбы, которые решают бои с игроками; Горное дело дает материалы.",
	["Ingeniería te salva con trucos de escape; Sastrería hace tu ropa."] = "Инженерное дело спасает хитростями для побега; Портняжное дело шьет вам одежду.",
	["Inicio"] = "Главная",
	["Inicio de Alfa"] = "Главная Alfa",
	["Inicio del horizonte"] = "Начало горизонта",
	["Insignias de La Jauría: los Alfas y los miembros llevan su lobo en el cuadro, en La Jauría y en el mapa; y quienes comparten se ven con una huella."] = "Значки La Jauría: Альфы и участники носят своего волка в подсказке, в La Jauría и на карте; а те, кто делится, видны как след лапы.",
	["Instantánea: úsala cada vez que esté lista."] = "Мгновенная: применяйте при каждой готовности.",
	["Instructor"] = "Учитель",
	["Instructor de %s"] = "Учитель: %s",
