	["Interceptar más seguido: el rival no se escapa."] = "Перехват чаще: противник не сбежит.",
	["Interfaz"] = "Интерфейс",
	["Interfaz del juego"] = "Интерфейс игры",
	["Interrumpes hechizos y los silencias."] = "Вы прерываете заклинания и накладываете немоту.",
	["Interrumpes y silencias hechizos."] = "Вы прерываете заклинания и накладываете немоту.",
	["Intimidación: tu mascota aturde al enemigo."] = "Устрашение: ваш питомец оглушает противника.",
	["Invita a tu clan con un clic, y arreglos"] = "Приглашайте в клан одним щелчком — и исправления",
	["Invitaciones a hermandades"] = "Приглашения в гильдии",
	["Invitaciones de grupo de desconocidos"] = "Приглашения в группу от незнакомцев",
	["Invitar"] = "Пригласить",
