	["Invitar al grupo"] = "Пригласить в группу",
	["Invitar, comerciar, susurrar…"] = "Пригласить, обменяться, шепнуть…",
	["Invitaste a %s a tu grupo."] = "Вы пригласили %s в группу.",
	["Invoca un espíritu de jabalí: mátenlo o que alguien lo tanquee."] = "Призывает дух вепря: убейте его или пусть кто-то его танкует.",
	["Invócalo antes de pelear."] = "Призовите его перед боем.",
	["Ir"] = "Идти",
	["Ir a la zona recomendada"] = "Идти в рекомендуемую зону",
	["Ir a un lugar"] = "Пойти в место",
	["Ir a: %s"] = "Идти к: %s",
	["Ir al mapa del juego"] = "Перейти к карте игры",
	["Ir al resumen"] = "К итогам",
	["Ir por el camino es más seguro que cortar por en medio: los caminos tienen menos enemigos."] = "Идти по дороге безопаснее, чем срезать напрямик: на дорогах меньше противников.",
	["Ira al romper un miedo: los rivales te asustan mucho."] = "Ярость при снятии страха: противники часто вас пугают.",
	["Ira aunque el rival huya o te frene."] = "Ярость, даже если противник убегает или замедляет вас.",
	["Ira constante en peleas largas contra jefes."] = "Постоянная ярость в долгих боях с боссами.",
	["Ira constante."] = "Постоянная ярость.",
	["Ira constante: nunca te quedas sin poder usar habilidades."] = "Постоянная ярость: вам всегда хватает на способности.",
	["Ira gratis cada pocos segundos, aunque nadie te pegue."] = "Бесплатная ярость каждые несколько секунд, даже если вас никто не бьет.",
	["Izquierdo"] = "Левая",
	["Jaina Valiente fue alumna de Antonidas antes de fundar Theramore."] = "Джайна Праудмур была ученицей Антонидаса, прежде чем основала Терамор.",
	["JcJ"] = "PvP",
	["JcJ (12): rangos de honor 3, 7, 10, 13 y 14; exaltado con las 4 facciones de los campos de batalla; las semanas 4, 7 y 10 del viaje de temporada Campo de Honor."] = "PvP (12): звания чести 3, 7, 10, 13 и 14; превознесение у 4 фракций полей боя; недели 4, 7 и 10 сезонного пути «Поле чести».",
	["Jefe"] = "Босс",
	["Jefe %d por descubrir"] = "Босс %d еще не открыт",
	["Jefe final"] = "Последний босс",
	["Jefes"] = "Боссы",
	["Jefes vencidos"] = "Побежденные боссы",
	["Jefes vencidos, mazmorras hechas y botín anotado de este personaje. No toca tus ajustes."] = "Побежденные боссы, пройденные подземелья и записанная добыча этого персонажа. Настройки не затрагиваются.",
	["Jefes, botín y la entrada de cada mazmorra y banda."] = "Боссы, добыча и вход в каждое подземелье и рейд.",
	["Juega con cada personaje una vez y Alfa recordará sus bolsas y su banco."] = "Зайдите каждым персонажем один раз, и Alfa запомнит его сумки и банк.",
	["Juega siempre en actitud defensiva con escudo."] = "Всегда играйте в Оборонительной стойке со щитом.",
	["Juguetes y consumibles de pesca"] = "Рыболовные игрушки и расходники",
	["Junta %d de %s"] = "Соберите %d × %s",
	["Junta 100 capturas."] = "Поймайте 100 рыб.",
	["Junta 1000 capturas."] = "Поймайте 1000 рыб.",
	["Junta 500 capturas."] = "Поймайте 500 рыб.",
	["Junta dos monstruos y usa Golpes de barrido: así subes más rápido."] = "Притягивайте двух монстров и используйте Размашистые удары: так прокачка идет быстрее.",
	["Junta dos o tres monstruos, usa Atronar y Revancha: subes seguro y sin descansar."] = "Притягивайте двух-трех монстров, используйте Удар грома и Реванш: прокачка безопасная и без отдыха.",
	["Junta lo gris y lo blanco para vender: suma más de lo que parece."] = "Собирай серые и белые предметы на продажу: набегает больше, чем кажется.",
	["Junta los montones y acomoda tus objetos con un clic."] = "Складывает стопки и упорядочивает предметы одним щелчком.",
	["Junta los montones y acomoda tus objetos. No funciona en combate."] = "Складывает стопки и упорядочивает предметы. Не работает в бою.",
	["Junta materiales de tu profesión donde más hay."] = "Собирайте материалы для профессии там, где их больше всего.",
	["Junta materiales de tu profesión, con unas misiones de XP en medio."] = "Собирайте материалы для профессии, с парой заданий на опыт по пути.",
	["Junta misiones de la misma zona: haces varias en un solo viaje."] = "Собирай задания в одной зоне: выполнишь несколько за одну вылазку.",
	["Junta varios monstruos: tus golpes sagrados alcanzan a todos."] = "Притягивайте нескольких монстров: ваши удары Света достают всех.",
	["Juntando todo lo del juego. Es solo la primera vez que la abres."] = "Собираем все данные игры. Это только при первом открытии.",
	["Juntar %s"] = "Накопить %s",
	["Juntar los materiales de mi profesión"] = "Собрать материалы для моей профессии",
	["Juntar materiales para vender"] = "Собрать материалы на продажу",
	["Juntar nodos cercanos al alejar"] = "Объединять близкие узлы при отдалении",
	["Juntar oro"] = "Накопить золото",
	["Junto a la lupa del mapa del juego: las capas, el modo limpio y «Mapa de Alfa» para cambiar al de Alfa."] = "Рядом с лупой на карте игры: слои, чистый режим и «Карта Alfa», чтобы переключиться на нее.",
	["Junto a tu guía hay un botón para buscar lo que tienes cerca: vuelo, banco, subasta, reparar, comerciantes y entrenadores."] = "Рядом с гайдом есть кнопка, чтобы найти то, что рядом: полет, банк, аукцион, ремонт, торговцев и учителей.",
	["Kael'thas fue miembro del Kirin Tor de Dalaran antes de guiar a los elfos de sangre."] = "Кель'тас был членом Кирин-Тора в Даларане, прежде чем повел за собой эльфов крови.",
	["Karazhan, la torre de Medivh, el último Guardián, se levanta sobre un cruce de líneas de magia natural."] = "Каражан, башня Медива, последнего Хранителя, стоит на пересечении природных линий магии.",
	["Kargath, el campamento de la Horda, lleva el nombre de un viejo caudillo orco del clan Mano Destrozada."] = "Лагерь Орды Каргат назван в честь старого вождя орков из клана Изувеченной Длани.",
	["Kel'Thuzad era un archimago de Dalaran. Lo expulsaron por estudiar nigromancia y acabó al servicio del Rey Exánime."] = "Кел'Тузад был верховным магом Даларана. Его изгнали за изучение некромантии, и он оказался на службе у Короля-лича.",
	["Kel'Thuzad tiene un gato, el señor Bigglesworth, que lo acompaña en Naxxramas. ¡Ni se te ocurra hacerle daño!"] = "У Кел'Тузада есть кот, мистер Бигглсворт, который сопровождает его в Наксрамасе. Даже не думай его обижать!",
	["Khadgar fue el aprendiz de Medivh. Al pelear contra su maestro poseído envejeció de golpe y se quedó con el pelo blanco."] = "Кадгар был учеником Медива. В бою с одержимым учителем он мгновенно постарел и поседел.",
	["Khaz Modan es la tierra de los enanos, desde las nieves de Dun Morogh hasta los valles de Loch Modan."] = "Каз Модан — земля дворфов, от снегов Дун Морога до долин Лок Модана.",
	["Kil'jaeden encerró el alma de Ner'zhul en un bloque de hielo y lo arrojó a Rasganorte: así nació el Rey Exánime."] = "Кил'джеден заключил душу Нер'зула в глыбу льда и швырнул ее в Нордскол: так родился Король-лич.",
	["Kil'jaeden engañó a Ner'zhul, el chamán más sabio de Draenor, y su aprendiz Gul'dan terminó de entregar a los orcos a la Legión."] = "Кил'джеден обманул Нер'зула, мудрейшего шамана Дренора, а его ученик Гул'дан довершил дело, отдав орков Легиону.",
	["Korialstrasz, el consorte de Alexstrasza, anduvo entre los mortales como Krasus, un mago del consejo de Dalaran."] = "Кориалстраз, супруг Алекстразы, ходил среди смертных как Красус, маг совета Даларана.",
	["Kul Tiras es un reino isleño de marineros. Su gran almirante, Daelin Valiente, era el padre de Jaina."] = "Кул-Тирас — островное королевство мореходов. Его великий адмирал Делин Праудмур был отцом Джайны.",
	["La %s también está en el menú del juego."] = "Настройка «%s» есть и в меню игры.",
	["La Abadía de Villanorte es de las más antiguas del reino; ahí empiezan su camino muchos aventureros humanos."] = "Аббатство Североземья — одно из старейших в королевстве; здесь начинают путь многие люди-искатели приключений.",
	["La Alianza nació en la Segunda Guerra, cuando los reinos humanos, los enanos y los altos elfos se unieron contra la Horda."] = "Альянс родился во Второй войне, когда людские королевства, дворфы и высшие эльфы объединились против Орды.",
	["La B, Mayús+B, la tecla de cada bolsa y los comerciantes abren la ventana de Alfa. Apágalo para volver a las del juego."] = "B, Shift+B, клавиша каждой сумки и торговцы открывают окно Alfa. Выключите, чтобы вернуть сумки игры.",
	["La Capilla de la Esperanza de la Luz resistió a la Plaga en una batalla legendaria; hoy es el gran refugio del Alba Argenta."] = "Часовня Последней Надежды выстояла против Плети в легендарной битве; сегодня это главное убежище Серебряного Рассвета.",
	["La Catedral de la Luz es el corazón de la fe en Ventormenta; sus sacerdotes atienden a toda la Alianza."] = "Собор Света — сердце веры в Штормграде; его жрецы служат всему Альянсу.",
	["La Cresta de la Llama es el puesto de la Horda en las estepas, en lo alto de las rocas."] = "Огненный Гребень — застава Орды в степях, высоко на скалах.",
	["La Cruzada Escarlata nació del dolor de Lordaeron tras la plaga, pero su odio la volvió tan cruel como lo que combate."] = "Алый орден родился из горя Лордерона после чумы, но ненависть сделала его таким же жестоким, как то, с чем он борется.",
	["La Cruzada Escarlata tiene aquí su monasterio. Para ellos todo no-muerto debe arder, también los Renegados."] = "Здесь монастырь Алого ордена. Для них вся нежить должна сгореть, включая Отрекшихся.",
	["La Cuenca de Arathi, el campo de batalla, está en estas tierras: se pelea por la granja, la mina, el aserradero, los establos y la herrería."] = "На этих землях находится поле боя Низина Арати: там сражаются за ферму, рудник, лесопилку, стойла и кузницу.",
	["La Feria de la Luna Negra tiene su propia reputación, y se sube con sus vales y sus encargos."] = "У Ярмарки Новолуния своя репутация, и она растет за купоны и поручения.",
	["La Fortaleza de Grommash, en Orgrimmar, lleva el nombre de Grom Grito Infernal, el héroe que liberó a los orcos de la sangre demoníaca."] = "Крепость Громмаш в Оргриммаре носит имя Грома Адского Крика, героя, освободившего орков от демонической крови.",
	["La Fuente del Sol, el corazón de Quel'Thalas, nació de un frasco de agua del Pozo de la Eternidad que los altos elfos se llevaron."] = "Солнечный Колодец, сердце Кель'Таласа, родился из флакона воды Источника Вечности, который высшие эльфы унесли с собой.",
	["La Garganta de Fuego quedó así por culpa del Hierro Negro: su hechicero-thane Thaurissan invocó a Ragnaros y la tierra se incendió."] = "Тлеющее ущелье стало таким по вине Черного Железа: их тан-чародей Тауриссан призвал Рагнароса, и земля загорелась.",
	["La Gran Forja nunca se apaga: es el corazón de Forjaz y el orgullo de tu gente."] = "Великая Кузня никогда не гаснет: это сердце Стальгорна и гордость твоего народа.",
	["La Gran Forja, en el corazón de Forjaz, nunca se apaga."] = "Великая Кузня в сердце Стальгорна никогда не гаснет.",
	["La Guardia Nocturna es la milicia de Villa Oscura: protege el pueblo de lobos, no-muertos y worgen."] = "Ночной Дозор — ополчение Темнолесья: он защищает городок от волков, нежити и воргенов.",
	["La Guerra de los Ancestros fue la primera invasión de la Legión Ardiente a Azeroth, hace unos diez mil años."] = "Война Древних была первым вторжением Пылающего Легиона в Азерот, около десяти тысяч лет назад.",
	["La Hermandad del Torio son enanos Hierro Negro que se separaron de su clan. Son maestros herreros y negocian con quien los respete."] = "Братство Тория — дворфы Черного Железа, порвавшие со своим кланом. Они мастера-кузнецы и торгуют с любым, кто их уважает.",
	["La Hermandad del Torio, en La Garganta de Fuego, enseña planos que muchos herreros sueñan."] = "Братство Тория в Тлеющем ущелье обучает чертежам, о которых мечтают многие кузнецы.",
	["La Horda arrasó Ventormenta en la Primera Guerra. Los albañiles que la reconstruyeron no recibieron su pago, y de ese enojo nació la Hermandad Defias."] = "Орда разрушила Штормград в Первой войне. Каменщикам, отстроившим его, так и не заплатили, и из этой обиды родилось Братство Справедливости.",
	["La Horda tiene su propio pueblo al norte del marjal, para vigilar Theramore de cerca."] = "У Орды есть своя деревня к северу от топей, чтобы присматривать за Терамором.",
	["La Horda tiene una aldea en la costa de Desolace, y la Alianza un campamento en las montañas del norte."] = "У Орды есть деревня на побережье Пустошей, а у Альянса — лагерь в северных горах.",
	["La Jauría"] = "La Jauría",
	["La Jauría en el mapa"] = "La Jauría на карте",
	["La Jauría: estado"] = "La Jauría: состояние",
	["La Jauría: tu manada en el mapa, Seguir y el clan (/alfa manada ayuda)"] = "La Jauría: ваша стая на карте, следование и клан (/alfa manada ayuda)",
	["La Jauría: tus comandos"] = "La Jauría: ваши команды",
	["La Legión Ardiente es el ejército de demonios de Sargeras, un titán caído que quiere quemar toda la creación."] = "Пылающий Легион — армия демонов Саргераса, падшего титана, который хочет сжечь все сущее.",
	["La Liga de Arathor y los Rapiñadores se pelean la Cuenca de Arathi; las Centinelas Ala de Plata y la Escolta Grito de Guerra, la Garganta Grito de Guerra."] = "Лига Аратора и Осквернители бьются за Низину Арати; Среброкрылые Часовые и Всадники Песни Войны — за Ущелье Песни Войны.",
	["La Liga de Expedicionarios, los arqueólogos de Forjaz, busca por todo el mundo las ruinas que cuenten el origen de los enanos."] = "Лига исследователей, археологи Стальгорна, ищет по всему миру руины, которые расскажут о происхождении дворфов.",
	["La Luz para los humanos y enanos, Elune para los elfos de la noche y las sombras para muchos Renegados: cada sacerdote sirve a algo distinto."] = "Свет — для людей и дворфов, Элуна — для ночных эльфов, тьма — для многих Отрекшихся: каждый жрец служит чему-то своему.",
	["La Mano de Plata la fundó el arzobispo Alonsus Faol, y Uther fue su primer paladín."] = "Орден Серебряной Длани основал архиепископ Алонсий Фаол, а Утер стал его первым паладином.",
	["La Mano de Plata, la orden de paladines, la fundó el arzobispo Alonsus Faol, y Uther fue el primero de sus caballeros."] = "Орден паладинов Серебряной Длани основал архиепископ Алонсий Фаол, а Утер стал первым из его рыцарей.",
	["La Masacre fue Eldre'Thalas, una ciudad de los elfos Altonato de antes de la Gran División."] = "Забытый город когда-то был Эльдре'Таласом, городом высокорожденных эльфов времен до Раскола.",
	["La Milicia Popular de la Colina del Centinela la formaron los propios granjeros cuando Ventormenta dejó de mandar soldados."] = "Народное ополчение Сторожевого холма создали сами фермеры, когда Штормград перестал присылать солдат.",
	["La Montaña Roca Negra se alza entre esta garganta y las Estepas Ardientes. Dentro viven los Hierro Negro, Ragnaros y los dragones negros."] = "Черная гора высится между этим ущельем и Пылающими степями. Внутри живут дворфы Черного Железа, Рагнарос и черные драконы.",
	["La Muralla de Thoradin separa Arathi de las Laderas de Trabalomas; lleva el nombre del rey que unió a los humanos."] = "Стена Торадина отделяет Нагорье Арати от Предгорий Хилсбрада; она названа в честь короля, объединившего людей.",
	["La Orden de Tirisfal, los magos secretos que elegían al Guardián de Azeroth, tomó su nombre de estos claros. Medivh fue el último Guardián."] = "Орден Тирисфаля, тайные маги, выбиравшие Хранителя Азерота, получил имя от этих лесов. Медив был последним Хранителем.",
	["La Plaga es el ejército no-muerto del Rey Exánime. Kel'Thuzad la extendió por Lordaeron con grano infectado."] = "Плеть — армия нежити Короля-лича. Кел'Тузад распространил ее по Лордерону с зараженным зерном.",
	["La Polimorfia convierte al enemigo en oveja. Yo me portaría muy bien con esa oveja, palabra de loba."] = "«Превращение» обращает противника в овцу. Я бы с этой овцой вела себя очень прилично, честное волчье.",
	["La Segadora de arcanita es una de las armas más famosas que puede forjar un herrero."] = "Арканитовый жнец — одно из самых знаменитых оружий, которое может выковать кузнец.",
	["La Sima Ígnea está bajo Orgrimmar: ahí se esconden brujos de un culto junto con troggs."] = "Огненная пропасть находится под Оргриммаром: там прячутся чернокнижники культа вместе с троггами.",
	["La Sociedad Real de Boticarios trabaja en Entrañas en una plaga nueva. Mejor no preguntes para quién."] = "Королевское фармацевтическое общество работает в Подгороде над новой чумой. Лучше не спрашивай, для кого.",
	["La Sociedad Real de Boticarios trabaja en secreto en una plaga nueva... y no precisamente para los humanos solamente."] = "Королевское фармацевтическое общество тайно работает над новой чумой... и вовсе не только для людей.",
	["La Tercera Guerra empezó con la plaga del grano en Lordaeron y terminó en Hyjal con la caída de Archimonde."] = "Третья война началась с чумы в зерне Лордерона и закончилась на Хиджале падением Архимонда.",
	["La Torre de Azora, en el este de Elwynn, es la casa de Theocritus, un mago al servicio del reino."] = "Башня Азоры на востоке Элвиннского леса — дом Теокрита, мага на службе королевства.",
	["La aldea Sen'jin, en la costa de Durotar, lleva el nombre del líder que dio su vida por su pueblo."] = "Деревня Сен'джин на побережье Дуротара носит имя вождя, отдавшего жизнь за свой народ.",
	["La ayuda de rotación está apagada"] = "Помощник ротации выключен",
	["La barra con el nombre de la zona y la hora toma los colores y la letra del estilo. Los botones de rastreo, calendario y correo quedan como siempre."] = "Панель с названием зоны и временем принимает цвета и шрифт стиля. Кнопки отслеживания, календаря и почты остаются как обычно.",
	["La barra de acción, las barras extra, la de experiencia, el menú y las bolsas toman el estilo que elijas. Solo cambia su aspecto, fuera de combate; al apagarlo vuelven las del juego."] = "Панель команд, дополнительные панели, полоса опыта, меню и сумки принимают выбранный стиль. Меняется только внешний вид, вне боя; если выключить — вернутся игровые.",
	["La barra de pesca"] = "Полоса рыбалки",
	["La barra de tu vuelo con sus paradas sale siempre al despegar."] = "Полоса полёта с остановками теперь всегда появляется при взлёте.",
	["La barra de vida con el color de la clase de cada uno. Apagado: barra verde y el nombre con su color."] = "Полоса здоровья в цвете класса каждого. Выключено: зеленая полоса и имя в цвете класса.",
	["La base incluida trae %s lugares en %d zonas. Tú descubriste %s."] = "Во встроенной базе %s мест в зонах: %d. Вы нашли: %s.",
	["La bienvenida con las novedades de esta versión."] = "Приветствие с новинками этой версии.",
	["La bienvenida ocupa toda la pantalla, con el juego oscurecido detrás."] = "Приветствие занимает весь экран, а игра за ним затемнена.",
	["La básica la venden los instructores y los vendedores de suministros de pesca."] = "Простую продают учителя и торговцы рыболовными принадлежностями.",
	["La búsqueda de lugares cercanos no está disponible."] = "Поиск ближайших мест недоступен.",
	["La cadena de los Defias te lleva de Villadorada a los Páramos de Poniente y termina en las Minas de la Muerte, frente a VanCleef."] = "Цепочка о Братстве Справедливости ведет из Златоземья в Западный Край и заканчивается в Мертвых копях, лицом к лицу с ван Клифом.",
	["La cadena no trae talentos válidos."] = "В строке нет подходящих талантов.",
	["La caja donde escribes toma el estilo, con el borde de acento mientras escribes. En Clásico WoW queda la del juego."] = "Поле ввода принимает стиль, с акцентной рамкой, пока вы пишете. В стиле «Классический WoW» остается игровое.",
	["La cambiaste fuera de Alfa (menú del juego o consola)."] = "Вы изменили это вне Alfa (в меню игры или консоли).",
	["La capa de escamas de Onyxia protege del aliento de Nefarian, y en su banda la piden todos."] = "Плащ из чешуи Ониксии защищает от дыхания Нефариана, и в его рейде он нужен всем.",
	["La cerveza es casi sagrada para tu gente: en Kharanos está la destilería Cebatruenos."] = "Пиво для твоего народа почти свято: в Караносе стоит пивоварня Громоваров.",
	["La cola está vacía."] = "Очередь пуста.",
	["La cura de ese clic pasa al botón central."] = "Лечение с этого щелчка переходит на среднюю кнопку.",
	["La cámara no salta hacia ti por cada árbol o poste entre ella y tu personaje."] = "Камера не прыгает к вам из-за каждого дерева или столба между ней и персонажем.",
	["La cámara se mece un poco con tus pasos."] = "Камера слегка покачивается в такт шагам.",
	["La cámara se queda sobre el agua en lugar de meterse."] = "Камера остается над водой, а не уходит под нее.",
	["La cámara te sigue"] = "Камера следует за вами",
	["La de ahora pasa a tus sesiones anteriores."] = "Текущий переходит в ваши прошлые сеансы.",
	["La de ahora pasa a tus sesiones anteriores. Tu diario y tus logros no cambian."] = "Текущий переходит в ваши прошлые сеансы. Журнал и достижения не меняются.",
	["La de tu clase mientras subes: cambia sola cuando pongas talentos."] = "Приоритет класса, пока вы растете: сменится сам, когда вы распределите таланты.",
	["La derecha"] = "Вправо",
	["La dirección del texto sobre tu personaje."] = "Направление текста над персонажем.",
	["La empieza un objeto"] = "Начинается с предмета",
	["La enciclopedia de La Jauría"] = "Энциклопедия La Jauría",
	["La enciclopedia no puede abrir todavía"] = "Энциклопедия пока не может открыться",
	["La entrada de %s"] = "Вход: %s",
	["La entrada de cada mazmorra en el minimapa, en verde las que ya hiciste. El mapa del mundo ya las marca con «Entradas de mazmorras»."] = "Вход в каждое подземелье на мини-карте, пройденные — зеленым. На карте мира они уже отмечены слоем «Входы в подземелья».",
	["La familia Barov le entregó su castillo de Caer Darrow al Culto a cambio de vida eterna. Así nació Scholomance, y así les fue."] = "Семья Баровых отдала Культу свой замок в Каэр Дарроу в обмен на вечную жизнь. Так родился Некроситет — и вот чем это для них кончилось.",
	["La flecha no está disponible ahora."] = "Стрелка сейчас недоступна.",
	["La flecha que te guía"] = "Стрелка, которая ведет вас",
	["La flecha se mueve con su rastro y se detiene al llegar."] = "Стрелка движется по его следу и останавливается, когда вы приходите.",
	["La flecha sigue caminos por el suelo alrededor de acantilados, agua y muros, con los mapas para caminar de Alfa. Apagado: apunta directo a cada parada."] = "Стрелка ведет по тропам в обход скал, воды и стен по пешеходным картам Alfa. Выключено: указывает прямо на каждую остановку.",
	["La flecha te lleva a %s."] = "Стрелка ведет вас к %s.",
	["La flecha te lleva a este paso, no al de ahora."] = "Стрелка ведет вас к этому шагу, а не к текущему.",
	["La flecha te lleva a su entrada."] = "Стрелка ведет вас ко входу.",
	["La flecha te lleva aquí."] = "Стрелка ведет вас сюда.",
	["La flecha te lleva de un lugar al siguiente."] = "Стрелка ведет от одного места к следующему.",
	["La flecha tomó otro destino: dejaste de seguir a %s."] = "Стрелка получила другую цель: вы больше не следуете за %s.",
	["La flecha usa vuelos y tu piedra de hogar cuando conviene."] = "Стрелка использует полеты и камень возвращения, когда выгодно.",
	["La flecha y el camino"] = "Стрелка и путь",
	["La flecha ya no sigue tu ruta de farmeo."] = "Стрелка больше не ведет по маршруту фарма.",
	["La fuerza se cambia en la ventana, en Filtros."] = "Силу можно изменить в окне, в разделе «Фильтры».",
	["La guarida de Onyxia está en este marjal. Onyxia, hija de Alamuerte, se hace pasar por una noble humana en Ventormenta."] = "Логово Ониксии — в этих топях. Ониксия, дочь Смертокрыла, выдает себя за знатную даму в Штормграде.",
	["La guía en el minimapa"] = "Гайд на мини-карте",
	["La guía que mejor te queda por tu nivel y donde estás."] = "Гайд, который лучше всего подходит вам по уровню и местоположению.",
	["La guía que sigues, tu paso de ahora y todo lo de las guías a un clic."] = "Гайд, по которому вы идете, ваш текущий шаг и все о гайдах в один щелчок.",
	["La guía te lleva a entrenar en %d pasos."] = "До обучения по гайду шагов: %d.",
	["La guía te lleva a quien recibe cada una."] = "Гайд приведет вас к тому, кто принимает каждое задание.",
	["La haces de paso: abre %s."] = "Выполняется по пути: открывает %s.",
	["La haré"] = "Выполню",
	["La historia"] = "История",
	["La historia se guarda cuando el juego te muestra la misión."] = "История сохраняется, когда игра показывает вам задание.",
	["La lengua de la Alianza es el común y la de la Horda, el orco. Por eso lo que le dices al otro bando le llega como palabras raras."] = "Альянс говорит на всеобщем, а Орда — на орочьем. Поэтому твои слова другой фракции доходят как тарабарщина.",
	["La letra del aspecto (Inter en el de Alfa, Fira Sans en Halo, la del juego en los demás) o la que elijas."] = "Шрифт оформления (Inter в оформлении Alfa, Fira Sans в «Ореоле», шрифт игры в остальных) или шрифт на ваш выбор.",
	["La lista está apagada: enciende «Tu lista de sonidos» en Comodidades (/alfa comodidades)."] = "Список выключен: включите «Ваш список звуков» в «Удобствах» (/alfa comodidades).",
	["La lista por nivel y tu progreso."] = "Список по уровням и ваш прогресс.",
	["La lupa de la cabecera del rastreador abre el menú. También: /alfa cerca o tu tecla."] = "Лупа в заголовке трекера открывает меню. Также: /alfa cerca или ваша клавиша.",
	["La línea de tiempo de Blizzard dice qué ataque viene y cuándo, y los mensajes grandes, lo peligroso. Alfa no inventa avisos: los prendes y ajustas en Ajustes."] = "Шкала времени Blizzard показывает, какая атака будет и когда, а крупные сообщения — что опасно. Alfa не выдумывает предупреждения: их включают и настраивают в «Настройках».",
	["La línea de tu personaje ya no se corta: si no cabe, quita partes y nunca tu nombre ni tu nivel."] = "Строка вашего персонажа больше не обрезается: если не помещается, убираются части, но никогда имя и уровень.",
	["La línea del camino también en el minimapa."] = "Линия пути и на мини-карте.",
	["La manada a la vista"] = "Стая в поле зрения",
	["La manada aúlla contigo."] = "Стая воет вместе с вами.",
	["La manada crece"] = "Стая растет",
	["La manada es fuerte porque cada lobo lo es. Y tú lo eres."] = "Стая сильна, потому что силен каждый волк. И ты тоже.",
	["La manada no te ve en el mapa"] = "Стая не видит вас на карте",
	["La manada no ve a tu personaje en el mapa."] = "Стая не видит вашего персонажа на карте.",
	["La manada te ve en el mapa"] = "Стая видит вас на карте",
	["La manada te ve en el mapa: %s"] = "Стая видит вас на карте: %s",
	["La manada ya no ve a tu personaje en el mapa."] = "Стая больше не видит вашего персонажа на карте.",
	["La manada ya ve a tu personaje en el mapa del juego."] = "Теперь стая видит вашего персонажа на карте игры.",
	["La manada ya ve a tu personaje en el mapa del juego. Lo cambias cuando quieras en /alfa manada."] = "Теперь стая видит вашего персонажа на карте игры. Изменить можно в любой момент командой /alfa manada.",
	["La mazmorra"] = "Подземелье",
	["La mazmorra para mi nivel"] = "Подземелье для моего уровня",
	["La mazmorra para tu nivel, sus jefes, botín, misiones y consejos."] = "Подземелье для вашего уровня: боссы, добыча, задания и советы.",
	["La mazmorra para tu nivel, sus misiones y cómo llegar."] = "Подземелье для вашего уровня, его задания и как туда добраться.",
	["La mazmorra para tu nivel; con un nombre, esa mazmorra (también: progreso, ajustes)"] = "Подземелье для вашего уровня; с названием — это подземелье (также: progreso, ajustes)",
	["La mezcla de texturas del terreno."] = "Смешивание текстур рельефа.",
	["La misión"] = "Задание",
	["La montura"] = "Транспорт",
	["La niebla con cuerpo de valles, pantanos y amaneceres."] = "Плотный туман долин, болот и рассветов.",
	["La pantalla se pone negra uno o dos segundos mientras el juego vuelve a arrancar los gráficos. No sales del juego ni pierdes nada."] = "Экран на секунду-две станет черным, пока игра перезапускает графику. Вы не выйдете из игры и ничего не потеряете.",
	["La pesca de Alfa está apagada"] = "Рыбалка Alfa выключена",
	["La pesca se rehízo: una sola tecla para equiparte, lanzar y recoger, con diario, logros y una guía de 1 a 300."] = "Рыбалка переделана: одна клавиша, чтобы надеть снаряжение, забросить и вытащить, с журналом, достижениями и гайдом от 1 до 300.",
	["La piel verde de los orcos es una huella de la magia vil que usaron sus brujos en Draenor."] = "Зеленая кожа орков — след магии Скверны, которой пользовались их чернокнижники на Дреноре.",
	["La precisión es lo más importante: con dos armas fallas mucho sin ella."] = "Меткость важнее всего: с двумя оружиями без нее много промахов.",
	["La primera vez: %s%s."] = "Впервые: %s%s.",
	["La princesa Moira, hija de Magni Barbabronce, vive en las Profundidades de Roca Negra como esposa del emperador Thaurissan."] = "Принцесса Мойра, дочь Магни Бронзоборода, живет в Глубинах Черной горы как жена императора Тауриссана.",
	["La profesión"] = "Профессия",
	["La página de Bolsas; «abrir» abre tus bolsas y «banco» tu banco"] = "Страница «Сумки»; «abrir» открывает сумки, а «banco» — банк",
	["La que te toca, con sus misiones y su botín."] = "Подходящее вам подземелье — с заданиями и добычей.",
	["La recoges ahora"] = "Возьмите сейчас",
	["La recomendada para ti y todas las demás"] = "Рекомендуемый для вас и все остальные",
	["La recomendada para ti y todas las demás."] = "Рекомендуемый для вас и все остальные.",
	["La ruta más rápida desde tu nivel, misión por misión."] = "Самый быстрый маршрут от вашего уровня, задание за заданием.",
	["La ruta no trae tramos."] = "В маршруте нет этапов.",
	["La ruta te lleva a %s. La flecha está apagada: enciéndela en Ajustes > Guía para verla."] = "Маршрут ведет вас к %s. Стрелка выключена: включите ее в Настройки > Гайд, чтобы видеть.",
	["La ruta ya no se salta para siempre una misión que todavía no puede revisar."] = "Маршрут больше не пропускает навсегда задание, которое пока не может проверить.",
	["La sabes"] = "Изучено",
	["La sacas de tu plan."] = "Вы убираете его из плана.",
	["La sastrería usa la tela que sueltan los humanoides: lino, lana, seda, tejido mágico y tela rúnica."] = "Портняжное дело использует ткань, которую роняют гуманоиды: льняную, шерстяную, шелковую, магическую и руническую.",
	["La siguiente casilla cuesta %s y no te alcanza todavía."] = "Следующая ячейка стоит %s, денег пока не хватает.",
	["La siguiente casilla cuesta %s: cómprala con el botón del banco del juego, que ya está a la vista."] = "Следующая ячейка стоит %s: купите её кнопкой банка игры, она уже на экране.",
	["La subasta deja escanear todo cada 15 minutos. Falta %s."] = "Аукцион позволяет полное сканирование раз в 15 минут. Осталось %s.",
	["La subasta no aceptó el escaneo. Intenta de nuevo más tarde."] = "Аукцион не принял сканирование. Попробуйте позже.",
	["La subasta no envió subastas. Intenta de nuevo más tarde."] = "Аукцион не прислал лоты. Попробуйте позже.",
	["La subasta no respondió. Puede que aún esté en espera: intenta en unos minutos."] = "Аукцион не ответил. Возможно, ожидание еще не закончилось: попробуйте через несколько минут.",
	["La suma de lo que guardó Alfa de cada personaje (el tuyo, al día)."] = "Сумма того, что Alfa сохранил по каждому персонажу (ваш — актуально).",
	["La tecla del botón de tu barra con esa habilidad, sobre el ícono."] = "Клавиша кнопки с этой способностью на панели — поверх значка.",
	["La tecla del mapa abre este mapa"] = "Клавиша карты открывает эту карту",
	["La tecla que abre el mapa del juego (M) abre el de Alfa; en él, un botón te lleva al del juego. Apágalo y la tecla vuelve a abrir el del juego. También puedes darle una tecla propia en Opciones > Teclado > Alfa."] = "Клавиша, открывающая карту игры (M), открывает карту Alfa; в ней кнопка ведет к карте игры. Выключите, и клавиша снова будет открывать карту игры. Можно также назначить ей свою клавишу в Настройки > Назначение клавиш > Alfa.",
	["La tecla que usabas en tu otro addon de pesca (%s) ahora pesca con Alfa."] = "Клавиша, которую вы использовали в другом аддоне рыбалки (%s), теперь рыбачит через Alfa.",
	["La tela rúnica sale de humanoides de nivel 50 o más: los trols de las Tierras del Interior o los sátiros de Frondavil son buena opción."] = "Руническая ткань падает с гуманоидов 50-го уровня и выше: тролли Внутренних земель или сатиры Оскверненного леса — хороший выбор.",
	["La tela vil sale de sátiros y demonios de Frondavil y Azshara."] = "Ткань Скверны падает с сатиров и демонов Оскверненного леса и Азшары.",
	["La tomo otra vez"] = "Возьму снова",
	["La tribu Zandalar se considera la primera de todos los trols. Sus sacerdotes acampan en la Isla de Yojamba para frenar a Hakkar."] = "Племя Зандалар считает себя первым из всех троллей. Их жрецы стоят лагерем на острове Йоджамба, чтобы остановить Хаккара.",
	["La trituradora tira a la gente: vuelve a llamar su atención rápido."] = "Крошшер раскидывает людей: быстро верните его внимание на себя.",
	["La tuya tiene %d semanas: salen seguido."] = "Вашей версии уже недель: %d. Обновления выходят часто.",
	["La venta se detuvo: vendiste %d de %d."] = "Продажа остановлена: продано %d из %d.",
	["La ventana"] = "Окно",
	["La ventana de talentos del juego"] = "Игровое окно талантов",
	["La ventana del Legado del juego"] = "Игровое окно «Наследия»",
	["La última: %s."] = "В последний раз: %s.",
	["Lady Sylvanas Brisaveloz gobierna a los Renegados. Fue general forestal de Quel'Thalas antes de que Arthas la matara."] = "Леди Сильвана Ветрокрылая правит Отрекшимися. Она была генералом следопытов Кель'Таласа, пока Артас не убил ее.",
	["Lady Vashj, que fue dama de compañía de Azshara, ahora guía a sus naga al servicio de Illidan."] = "Леди Вайш, бывшая фрейлина Азшары, теперь ведет своих наг на службе Иллидану.",
	["Lanza bolas de fuego y fuego a su alrededor: interrúmpelo y, si peleas de lejos, aléjate."] = "Он бросает огненные шары и выпускает огонь вокруг: прерывайте его и, если сражаетесь на расстоянии, держитесь подальше.",
	["Lanza bombas de humo que aturden: sal del humo."] = "Бросает дымовые бомбы, которые оглушают: выходите из дыма.",
	["Lanza enredaderas que tumban a todos los que están cerca: si peleas de lejos, quédate lejos."] = "Выпускает лозы, которые сбивают с ног всех рядом: если сражаетесь на расстоянии, держитесь подальше.",
	["Lanza fuego a su alrededor: si peleas de lejos, aléjate de él."] = "Выпускает огонь вокруг себя: если сражаетесь на расстоянии, держитесь от него подальше.",
	["Lanza hechizos de tierra y pone tótems: rompan los tótems primero."] = "Применяет заклинания земли и ставит тотемы: сначала разбейте тотемы.",
	["Lanza metal fundido: si no tanqueas, no te quedes pegado a él."] = "Бросает расплавленный металл: если вы не танк, не стойте вплотную к нему.",
	["Lanza rayos y se puede curar: interrumpe sus hechizos."] = "Бьет молниями и может лечить себя: прерывайте ее заклинания.",
	["Lanza ráfagas arcanas: interrúmpelo."] = "Применяет чародейские вспышки: прерывайте его.",
	["Lanza sombras: interrúmpelo."] = "Применяет темную магию: прерывайте его.",
	["Lanza telarañas y una maldición: quita la maldición si puedes."] = "Опутывает паутиной и накладывает проклятие: снимайте проклятие, если можете.",
	["Lanza tormentas de arena que se mueven por la sala: no te pares en ellas."] = "Создает песчаные бури, которые движутся по залу: не стойте в них.",
	["Lanza tu hechizo más fuerte desde lejos y remata con los instantáneos."] = "Произнесите самое сильное заклинание издалека и добейте мгновенными.",
	["Lanza tu hechizo más fuerte primero y remata con un choque."] = "Сначала произнесите самое сильное заклинание и добейте шоком.",
	["Lanza una nube de veneno hacia adelante: gíralo lejos del grupo."] = "Выдыхает перед собой ядовитое облако: разверните ее от группы.",
	["Lanza una red que deja quieto a un jugador: no es grave, sigue atacando."] = "Бросает сеть, которая обездвиживает игрока: ничего страшного, продолжайте атаковать.",
	["Lanza veneno a todos: quita el veneno si puedes."] = "Отравляет всех: снимайте яд, если можете.",
	["Lanzado"] = "Заброшено",
	["Lanzamientos"] = "Забросы",
	["Lanzamientos: %d de %d"] = "Забросы: %d из %d",
	["Las Cavernas del Tiempo guardan los momentos más importantes de la historia, y el Vuelo Bronce no deja que nadie los cambie."] = "Пещеры Времени хранят важнейшие моменты истории, и бронзовые драконы никому не дают их изменить.",
	["Las Estepas Ardientes se incendiaron cuando Ragnaros despertó, y sus brasas siguen sin apagarse."] = "Пылающие степи загорелись, когда пробудился Рагнарос, и их угли до сих пор не погасли.",
	["Las Islas del Eco eran el hogar de los Lanza Negra, hasta que el brujo Zalazane sometió a muchos con su vudú y los demás tuvieron que mudarse a tierra firme."] = "Острова Эха были домом племени Черного Копья, пока колдун Залазан не поработил многих своим вуду, и остальным пришлось переселиться на большую землю.",
	["Las Minas de la Muerte esconden el refugio de VanCleef... y hasta un barco pirata."] = "Мертвые копи скрывают убежище ван Клифа... и даже пиратский корабль.",
	["Las Montañas Crestagrana deben su nombre a sus rocas rojizas."] = "Красногорье обязано своим названием красноватым скалам.",
	["Las Profundidades de Roca Negra son una ciudad enana entera bajo la montaña: la capital de los Hierro Negro."] = "Глубины Черной горы — целый дворфийский город под горой, столица Черного Железа.",
	["Las Rocas Rojas de Mulgore son un lugar sagrado: ahí descansan los ancestros de los tauren."] = "Красные Скалы Мулгора — священное место: там покоятся предки тауренов.",
	["Las Rocas Rojas son el lugar más sagrado de Mulgore: ahí descansan los ancestros de tu gente."] = "Красные Скалы — самое священное место Мулгора: там покоятся предки твоего народа.",
	["Las aguas de nivel 20 a 35. El rango Experto se aprende con el libro que vende el pescador de Bahía del Botín."] = "Воды для 20–35-го уровня. Ступень «Умелец» изучается по книге, которую продает рыбак в Пиратской Бухте.",
	["Las barras de abajo"] = "Нижние панели",
	["Las bendiciones mayores duran más y cubren a toda una clase del grupo. ¡Ahorran mucho maná!"] = "Великие благословения действуют дольше и накрывают целый класс в группе. Очень экономят ману!",
	["Las bolsas que coses siempre se venden: todo el mundo quiere más espacio."] = "Сумки, которые ты шьешь, всегда продаются: всем нужно больше места.",
	["Las bombas y granadas te salvan en mazmorras y en peleas contra el otro bando."] = "Бомбы и гранаты выручают в подземельях и в боях с другой фракцией.",
	["Las cajas cerradas las abren los pícaros; ofrécelas en el chat y a veces hasta te regalan el servicio."] = "Запертые ящики открывают разбойники; предложи в чате — иногда это сделают даже бесплатно.",
	["Las cartas de la Luna Negra caen de enemigos por todo el mundo; un mazo completo se cambia en la Feria por un abalorio poderoso."] = "Карты Новолуния падают с противников по всему миру; полную колоду на Ярмарке меняют на мощный аксессуар.",
	["Las casas de subastas neutrales de Bahía del Botín, Gadgetzan y Vista Eterna cobran más comisión, pero te dejan comerciar con el otro bando."] = "Нейтральные аукционы Пиратской Бухты, Прибамбасска и Круговзора берут больше комиссии, зато позволяют торговать с другой фракцией.",
	["Las centinelas de Vallefresno pelean sin descanso contra los leñadores orcos de Grito de Guerra."] = "Часовые Ясеневого леса без устали сражаются с орками-лесорубами из клана Песни Войны.",
	["Las centinelas domestican sables de hielo en Cuna del Invierno, y se los confían solo a quien se gana su respeto."] = "Часовые приручают ледопардов в Зимних Ключах и доверяют их только тем, кто заслужил их уважение.",
	["Las criaturas que invocan los enemigos por un rato."] = "Существа, которых противники призывают на время.",
	["Las cuentas"] = "Расчеты",
	["Las cuentas de prueba no pueden compartir: el juego no lo permite."] = "Пробные учетные записи не могут делиться: игра этого не позволяет.",
	["Las de tu ruta, las de la guía o todas: se eligen en Ajustes > Misiones, con lo demás de las misiones."] = "Задания вашего маршрута, гида или все: выбирается в Настройки > Задания, вместе со всем остальным про задания.",
	["Las demás"] = "Остальные",
	["Las demás ranuras"] = "Остальные ячейки",
	["Las dos se suben solas mientras matas y viajas, y lo que juntas se vende bien: oro para tu montura y tus habilidades."] = "Обе растут сами, пока вы убиваете и путешествуете, а собранное хорошо продается: золото на транспорт и способности.",
	["Las dríades son hijas de Cenarius, y los guardianes de la arboleda, sus hijos."] = "Дриады — дочери Кенария, а Хранители Рощи — его сыновья.",
	["Las esquinas de la pantalla se oscurecen poco a poco, como en una foto."] = "Углы экрана постепенно темнеют, как на фотографии.",
	["Las excavaciones de los enanos despertaron a los troggs, y ahora Thelsamar tiene que cuidarse de ellos."] = "Раскопки дворфов разбудили троггов, и теперь Телсамару приходится их остерегаться.",
	["Las explicaciones vuelven a salir."] = "Пояснения снова показываются.",
	["Las flores cantoras corrompidas de Frondavil se pueden purificar; al hacerlo te dan una bendición que dura un buen rato."] = "Оскверненные певучие цветы Оскверненного леса можно очистить; за это ты получаешь благословение надолго.",
	["Las fronteras entre zonas ya no parpadean al mover el mapa."] = "Границы между зонами больше не мерцают, когда вы двигаете карту.",
	["Las gafas de ingeniero solo las pueden usar ingenieros: ¡lúcelas con orgullo!"] = "Инженерные очки могут носить только инженеры: носи с гордостью!",
	["Las hierbas de nivel alto se venden muy bien en la casa de subastas."] = "Травы высокого уровня очень хорошо продаются на аукционе.",
	["Las líneas que escribe Anunciar en el chat de tu grupo o banda."] = "Строки, которые «Объявить» пишет в чат группы или рейда.",
	["Las marca con una flecha."] = "Отмечает их стрелкой.",
	["Las marcas de la manada también en el minimapa, no solo en el mapa del mundo."] = "Метки стаи и на мини-карте, а не только на карте мира.",
	["Las marcas en el suelo de hechizos y áreas. Apagarlas esconde avisos de combate: mejor dejarlas encendidas."] = "Метки заклинаний и областей на земле. Если их выключить, пропадут боевые предупреждения: лучше оставить включенными.",
	["Las mejores misiones que ya puedes tomar cerca de ti, en el orden más corto."] = "Лучшие задания поблизости, которые уже можно взять, в самом коротком порядке.",
	["Las mesetas de Cima del Trueno están unidas por puentes, y a la ciudad se sube en elevadores."] = "Месы Громового Утеса соединены мостами, а в город поднимаются на подъемниках.",
	["Las metas se cumplen solas al hacerlas; las notas las marcas tú. Ordénalas como quieras."] = "Цели выполняются сами, когда вы их делаете; заметки отмечаете вы. Расставьте их как угодно.",
	["Las misiones de Molino Tarren mandan a la Horda contra las granjas humanas de las laderas."] = "Задания Мельницы Таррен посылают Орду против человеческих ферм на склонах.",
	["Las misiones grises dan poca XP. Entrégalas y sigue adelante."] = "Серые задания дают мало опыта. Сдай их и иди дальше.",
	["Las misiones previas y el nivel que pide, para poder tomarla."] = "Предыдущие задания и требуемый уровень, чтобы его взять.",
	["Las misiones que más experiencia dan cerca de ti."] = "Задания рядом с вами, которые дают больше всего опыта.",
	["Las misiones repetibles de reputación, como entregar tela, también son una forma de farmeo."] = "Повторяемые задания на репутацию, вроде сдачи ткани, — тоже способ фарма.",
	["Las monturas de los gnomos son mecazancudos, aves mecánicas que ellos mismos inventaron."] = "Транспорт гномов — механодолгоноги, механические птицы, которых они сами изобрели.",
	["Las monturas de otra raza de tu bando pueden pedir reputación con su ciudad: la de tu raza siempre se puede."] = "Транспорт другой расы вашей фракции может требовать репутацию с ее столицей; транспорт своей расы доступен всегда.",
	["Las monturas de tu raza"] = "Транспорт вашей расы",
	["Las monturas épicas del Clásico cuestan bastante oro; juntarlo poco a poco es parte de la aventura."] = "Эпический транспорт классики стоит немало золота; копить его понемногу — часть приключения.",
	["Las ondas al caminar o nadar en el agua."] = "Круги на воде, когда вы идете или плывете.",
	["Las orillas de la pantalla un poco más oscuras."] = "Края экрана немного темнее.",
	["Las pestañas toman la letra y los colores del estilo; la elegida lleva la línea de acento. En Clásico WoW quedan las del juego."] = "Вкладки принимают шрифт и цвета стиля; у выбранной — акцентная линия. В стиле «Классический WoW» остаются игровые.",
	["Las piedras de afilar y los contrapesos que haces le sirven a guerreros y pícaros: siempre tienen compradores."] = "Твои точильные камни и грузила пригодятся воинам и разбойникам: покупатели найдутся всегда.",
	["Las piedras de salud que creas le salvan la vida a todo tu grupo."] = "Камни здоровья, которые ты создаешь, спасают жизнь всей группе.",
	["Las placas de nombre de los enemigos."] = "Индикаторы здоровья противников.",
	["Las plantas de herboristería."] = "Растения для травничества.",
	["Las pociones de vida y maná siempre se venden: toda mazmorra las pide."] = "Зелья здоровья и маны всегда продаются: они нужны в каждом подземелье.",
	["Las primeras misiones de un humano en Villanorte van de kóbolds, bandidos Defias... y lobos. No todos somos buenos, ¿eh?"] = "Первые задания человека в Североземье — про кобольдов, бандитов Братства Справедливости... и волков. Не все мы хорошие, да?",
	["Las profesiones de fabricación dan retos del Legado al llegar a 150, 225 y 300."] = "Профессии производства дают испытания «Наследия» на 150, 225 и 300.",
	["Las profesiones de recolección dan oro desde el nivel 1. ¡Hierbas o minería!"] = "Собирательные профессии приносят золото с 1-го уровня. Травничество или горное дело!",
	["Las que Lya ya te dijo sus tres veces. Con «Volver a mostrarlos» salen otra vez."] = "Фразы, которые Lya уже сказала вам по три раза. Кнопка «Показать снова» вернет их.",
	["Las que me faltan"] = "Которых нет",
	["Las que se hacen una sola vez."] = "Те, что выполняются один раз.",
	["Las que se repiten cada día."] = "Те, что повторяются каждый день.",
	["Las que se repiten cada semana."] = "Те, что повторяются каждую неделю.",
	["Las que tengo"] = "Которые есть",
	["Las que vienen después, más pequeñas a la derecha."] = "Следующие — поменьше, справа.",
	["Las que ya hiciste no cuentan."] = "Уже выполненные задания не учитываются.",
	["Las ranuras que tu tecla nunca cambia: cabeza, manos, pies, abalorios y las demás."] = "Ячейки, которые ваша клавиша никогда не меняет: голова, кисти рук, ступни, аксессуары и остальные.",
	["Las recetas se compran a vendedores de comida y algunas caen de enemigos."] = "Рецепты покупают у торговцев едой, а некоторые падают с противников.",
	["Las ruinas de Eldarath fueron una ciudad élfica; hoy están llenas de naga."] = "Руины Эльдарата когда-то были эльфийским городом; теперь там полно наг.",
	["Las rutas y los planes que armas en la página Ruta de Alfa."] = "Маршруты и планы, которые вы составляете на странице «Маршрут» Alfa.",
