	["Para vender, habla con un comerciante."] = "Чтобы продать, поговорите с торговцем.",
	["Para ver y romper los tótems enemigos."] = "Чтобы видеть и разбивать вражеские тотемы.",
	["Para verlas mejor"] = "Чтобы лучше их видеть",
	["Para volver a acumularla, descansa (o cierra sesión) en una posada o una ciudad."] = "Чтобы снова его накопить, отдохните (или выйдите из игры) в таверне или городе.",
	["Parada"] = "Парирование",
