	["Pasa el ratón sobre un compañero y cúralo con un clic."] = "Наведите курсор на союзника и вылечите его щелчком.",
	["Pasa el ratón sobre un compañero y haz clic: el izquierdo %s y el derecho %s."] = "Наведите курсор на союзника и щелкните: левая — %s, правая — %s.",
	["Pasa enfermedades: quítalas si tu clase puede."] = "Заражает болезнями: снимайте их, если ваш класс это умеет.",
	["Pasa tu build a un amigo o usa el que te pasen."] = "Передайте свой билд другу или используйте тот, что дадут вам.",
	["Paso %d"] = "Шаг %d",
