	["Pasos que siguen, numerados"] = "Следующие шаги с номерами",
	["Pausa"] = "Пауза",
	["Pausa para el lunch: tú comes, yo miro con ojitos tiernos."] = "Перерыв на обед: ты ешь, я смотрю жалобными глазками.",
	["Peces"] = "Рыбы",
	["Pecho"] = "Грудь",
	["Pedirle un consejo"] = "Попросить совет",
	["Pediste %s; el juego lo dejó en %s."] = "Вы просили %s; игра установила %s.",
	["Pega aquí (Ctrl+V) el texto de una ruta de Alfa."] = "Вставьте сюда (Ctrl+V) текст маршрута Alfa.",
	["Pega aquí una cadena que empiece con ALFA1; (Ctrl + V) y pulsa Importar. Alfa revisa cada talento contra tu árbol."] = "Вставьте сюда строку, начинающуюся с ALFA1; (Ctrl + V), и нажмите «Импорт». Alfa сверит каждый талант с вашим деревом.",
	["Pega fuerte pero no tiene trucos: es un buen jefe para aprender."] = "Бьет сильно, но без хитростей: хороший босс для обучения.",
	["Pega fuerte y se protege con un escudo de luz: empieza con la vida llena."] = "Бьет сильно и закрывается щитом Света: начинайте бой с полным здоровьем.",
	["Pega muchas veces seguidas al tanque: no dejes que su vida baje de la mitad."] = "Бьет танка много раз подряд: не давайте его здоровью опуститься ниже половины.",
	["Pega muy fuerte: empieza la pelea con la vida llena."] = "Бьет очень сильно: начинайте бой с полным здоровьем.",
	["Pega primero una cadena de build de Alfa."] = "Сначала вставьте строку билда Alfa.",
	["Pega primero una cadena de escala de estadísticas."] = "Сначала вставьте строку шкалы характеристик.",
	["Pega una cadena de escala de estadísticas (Ctrl+V), la que copiaste desde donde la compartieron."] = "Вставьте строку шкалы характеристик (Ctrl+V), скопированную оттуда, где ею поделились.",
	["Pega varias veces seguidas: empieza con la vida llena."] = "Бьет несколько раз подряд: начинайте с полным здоровьем.",
	["Pegas a dos: útil contra mascotas y grupos."] = "Вы бьете двоих: полезно против питомцев и групп.",
	["Pegas más después de recibir críticos."] = "Вы бьете сильнее после получения критических ударов.",
	["Pegas más fuerte después de recibir críticos."] = "Вы бьете сильнее после получения критических ударов.",
	["Pegas más fuerte después de recibir un golpe crítico."] = "Вы бьете сильнее после получения критического удара.",
	["Pelea con un solo monstruo a la vez; si vienen dos, usa Golpes de barrido."] = "Сражайтесь с одним монстром за раз; если пришли двое, используйте Размашистые удары.",
	["Pelea siempre con la vida llena; no encadenes monstruos sin descansar."] = "Всегда начинайте бой с полным здоровьем; не берите монстров одного за другим без отдыха.",
	["Pelear contra otros jugadores: aguantar, frenar y rematar."] = "Сражаться с другими игроками: выдержать, замедлить и добить.",
	["Peletería"] = "Кожевничество",
	["Peletería hace cuero con armadura y aguante para la forma de oso."] = "Кожевничество создает кожаные вещи с броней и выносливостью для облика медведя.",
	["Peletería hace malla para ti; Desuello te da el material sin gastar oro."] = "Кожевничество создает для вас кольчугу; Снятие шкур дает материалы, не тратя золото.",
	["Peletería hace piezas de cuero con agilidad y aguante; Desuello te da el cuero."] = "Кожевничество создает кожаные вещи с ловкостью и выносливостью; Снятие шкур дает кожу.",
	["Peligro"] = "Опасность",
	["Peligrosa para tu nivel"] = "Опасно для вашего уровня",
	["Pendiente"] = "Не выполнено",
	["Pequeñas tareas que Alfa hace por ti al abrir un comerciante, al despojar y al viajar."] = "Мелкие дела, которые Alfa делает за вас у торговца, при сборе добычи и в пути.",
	["Pequeños íconos en cada ataque: si es para el tanque, para quien cura, si se puede quitar o si es mortal."] = "Маленькие значки на каждой атаке: для танка ли она, для лекаря, можно ли ее снять и смертельна ли она.",
	["Perdimos el rastro de %s: ya no sabemos dónde está."] = "След потерян: %s — местоположение больше неизвестно.",
	["Perjuicios que puedes quitar"] = "Снимаемые отрицательные эффекты",
	["Personaje"] = "Персонаж",
	["Pesca"] = "Рыбная ловля",
	["Pesca %d/%d"] = "Рыбная ловля %d/%d",
	["Pesca 10 de oro en valor en una sola sesión."] = "Наловите на 10 золотых за один сеанс.",
	["Pesca 25 especies distintas."] = "Поймайте 25 разных видов.",
	["Pesca 5 especies distintas en una misma zona."] = "Поймайте 5 разных видов в одной зоне.",
	["Pesca 5 especies distintas."] = "Поймайте 5 разных видов.",
	["Pesca de Alfa apagada. Tu tecla y tus ajustes quedan como siempre."] = "Рыбалка Alfa выключена. Ваша клавиша и настройки остаются как обычно.",
	["Pesca de Alfa encendida, pero en pausa mientras otro addon de pesca esté activo."] = "Рыбалка Alfa включена, но на паузе, пока включен другой аддон рыбалки.",
