	["Sangre fría: tu siguiente remate es crítico seguro."] = "Хладнокровие: следующий завершающий прием гарантированно критический.",
	["Sapphiron, el dragón de escarcha de Naxxramas, fue un dragón azul antes de que la Plaga lo levantara."] = "Сапфирон, ледяной змей Наксрамаса, был синим драконом, пока Плеть его не подняла.",
	["Sargeras fue el gran campeón del Panteón. De tanto pelear contra demonios concluyó que la creación no tenía remedio, y fundó la Legión Ardiente."] = "Саргерас был великим защитником Пантеона. Сражаясь с демонами так долго, он решил, что творение не спасти, и основал Пылающий Легион.",
	["Sastrería"] = "Портняжное дело",
	["Sastrería hace tu ropa con lo que cae en mazmorras, y Encantamiento deshace lo que no usas y mejora tu equipo."] = "Портняжное дело шьет вам одежду из того, что падает в подземельях, а Наложение чар распыляет ненужное и улучшает вашу экипировку.",
	["Sastrería y Encantamiento: tu equipo siempre al día."] = "Портняжное дело и Наложение чар: ваша экипировка всегда актуальна.",
	["Scholomance, en la isla de Caer Darrow, es la escuela donde la Plaga enseña nigromancia. Antes fue el hogar de la familia Barov."] = "Некроситет на острове Каэр Дарроу — школа, где Плеть учит некромантии. Раньше это был дом семьи Баровых.",
	["Se abandona con «Abandonar marcadas», que pide confirmación."] = "От задания отказываются кнопкой «Отказаться от отмеченных», она запросит подтверждение.",
	["Se abre a nivel %d: te faltan %d niveles. Mientras, sigue tu ruta."] = "Открывается на %d-м уровне: осталось %d ур. А пока идите по маршруту.",
	["Se abre al salir de combate."] = "Откроется после выхода из боя.",
	["Se abre al terminar %s."] = "Открывается после %s.",
	["Se abren con la B. Elige la vista (todo junto, por categorías o por bolsa), busca por nombre o nivel y arrastra tus bolsas en su barra para cambiarlas."] = "Открываются клавишей B. Выберите вид (все вместе, по категориям или по сумкам), ищите по названию или уровню и перетаскивайте сумки на их панели, чтобы заменить.",
	["Se acabaron los textos cortados con «…» en Hoy, La Jauría, Buscar cerca y la Enciclopedia."] = "Больше никаких обрезанных «…» текстов в «Сегодня», La Jauría, «Найти рядом» и «Энциклопедии».",
	["Se acabó el aviso «Alfa_Builds se ha bloqueado…»: la ventana de talentos, el clic para lanzar y el Legado ahora los abre el juego, y tus hechizos se lanzan sin problema desde el libro."] = "Больше никакого сообщения «Alfa_Builds заблокирован…»: окно талантов, заклинания по щелчку и «Наследие» теперь открывает сама игра, а заклинания без проблем применяются из книги.",
	["Se acabó tu XP descansada"] = "Опыт за отдых закончился",
	["Se acelera a sí mismo y lanza rayos: interrúmpelo."] = "Ускоряет себя и бьет молниями: прерывайте его.",
	["Se acelera a sí mismo: interrúmpelo si puedes."] = "Ускоряет себя: прерывайте его, если можете.",
	["Se activó Claridad: tu siguiente hechizo es gratis."] = "Сработала Ясность мысли: следующее заклинание бесплатно.",
	["Se activó Claridad: tus Misiles arcanos salen gratis."] = "Сработала Ясность мысли: Чародейские стрелы бесплатны.",
	["Se activó Trance de las Sombras: tu Descarga de las Sombras es instantánea."] = "Сработал Теневой транс: Стрела Тьмы применяется мгновенно.",
	["Se agregó el sonido %d a tu lista."] = "Звук %d добавлен в ваш список.",
	["Se aplica al salir de combate."] = "Применится после выхода из боя.",
	["Se aprende con %s"] = "Изучается у: %s",
	["Se borra el progreso de mazmorras de este personaje. No se puede deshacer."] = "Прогресс подземелий этого персонажа будет удален. Отменить это нельзя.",
	["Se borran las sesiones guardadas de este personaje. La sesión de ahora sigue contando."] = "Сохраненные сеансы этого персонажа будут удалены. Текущий сеанс продолжит считаться.",
	["Se borran las sesiones, las zonas y los objetos de este personaje. No se puede deshacer."] = "Сеансы, зоны и предметы этого персонажа будут удалены. Отменить это нельзя.",
	["Se borran los %d marcadores de todos tus personajes. No se puede deshacer."] = "Удаляются все маркеры (%d) у всех ваших персонажей. Отменить нельзя.",
	["Se borran los jefes vencidos, las veces completada y el botín anotado de %s para este personaje."] = "Будут удалены побежденные боссы, число прохождений и записанная добыча (%s) для этого персонажа.",
	["Se borran los precios guardados de la subasta de este reino y facción. Tus recetas se quedan."] = "Сохраненные аукционные цены этого игрового мира и фракции будут удалены. Ваши рецепты останутся.",
	["Se borran todas las peleas guardadas, también en la ventana del medidor del juego."] = "Удаляются все сохраненные бои, в том числе в окне игрового измерителя.",
	["Se borran tus sesiones, tu diario, tus logros y tus metas de este personaje. Tu habilidad de pesca no cambia."] = "Удаляются сеансы, журнал, достижения и цели этого персонажа. Навык рыбной ловли не меняется.",
	["Se carga al salir de combate"] = "Загрузится после выхода из боя",
	["Se cerró la subasta antes de recibir los precios. Vuelve a intentarlo después."] = "Аукцион закрылся до получения цен. Попробуйте позже.",
	["Se cerró la ventana de clic para lanzar de Blizzard. Vuelve a pulsar «Abrir clic para lanzar» para abrirla."] = "Окно заклинаний по щелчку Blizzard закрылось. Снова нажмите «Открыть заклинания по щелчку», чтобы открыть его.",
	["Se cumple al llegar a ese nivel."] = "Выполняется при достижении этого уровня.",
	["Se cura a sí mismo: interrumpe su curación."] = "Лечит себя: прерывайте его лечение.",
	["Se cura comiendo: mátenlo rápido."] = "Лечится едой: убейте его быстро.",
	["Se cura: interrúmpelo."] = "Лечит себя: прерывайте его.",
	["Se descubren todos los jefes de %s, como si la hubieras terminado. Si te equivocas, puedes olvidar tu progreso aquí."] = "Открываются все боссы подземелья %s, как если бы вы его прошли. Если это ошибка, прогресс можно сбросить здесь.",
	["Se detuvo al cerrar el banco: guardaste %d y faltaron %d."] = "Остановлено при закрытии банка: положено %d, осталось %d.",
	["Se detuvo al entrar en combate: guardaste %d y faltaron %d."] = "Остановлено с началом боя: положено %d, осталось %d.",
	["Se enfurece al final: guarden su mejor daño."] = "В конце впадает в ярость: приберегите самый сильный урон.",
