	["Seleccionar todo"] = "Выбрать все",
	["Sello"] = "Печать",
	["Sepia"] = "Сепия",
	["Servicio"] = "Услуга",
	["Servicios"] = "Услуги",
	["Servicios en el minimapa"] = "Услуги на мини-карте",
	["Será una mejora más adelante"] = "Станет улучшением позже",
	["Sesiones anteriores"] = "Прошлые сеансы",
	["Sesiones que guarda el diario"] = "Сколько сеансов хранит дневник",
	["Sesiones, diario, logros y metas de este personaje. No se puede deshacer."] = "Сеансы, журнал, достижения и цели этого персонажа. Отменить нельзя.",
	["Sesión de pesca nueva."] = "Новый сеанс рыбалки.",
	["Señalar"] = "Указать",
	["Señor de las aguas"] = "Повелитель вод",
	["Si aguantas bien, usa Golpe heroico con la ira sobrante para más amenaza."] = "Если держитесь хорошо, тратьте лишнюю ярость на Удар героя ради угрозы.",
	["Si algo sale mal, tu habilidad para desaparecer te saca de la pelea. Úsala antes de que sea tarde."] = "Если что-то пошло не так, умение исчезать вытащит тебя из боя. Используй его, пока не поздно.",
	["Si alguien de la manada te pasa uno, impórtalo y Alfa te guía con él punto por punto."] = "Если кто-то из стаи даст вам билд, импортируйте его, и Alfa проведет вас по нему очко за очком.",
	["Si alguien huye, puede traer a más presos: deténganlo con un ataque que lo frene."] = "Если кто-то убегает, он может привести еще заключенных: остановите его замедляющей атакой.",
	["Si alguna vez ves salchichas en una posada, guárdame una… o dos."] = "Если увидишь сосиски в таверне, оставь мне одну… или две.",
	["Si bajas por el Gran Elevador, verás por qué se llama así: cientos de agujas de roca."] = "Если спуститься на Великом подъемнике, поймешь, откуда название: сотни каменных игл.",
	["Si en estas fechas ves calabazas en las posadas, es Halloween: los posaderos te dan dulces con truco o trato, y a veces un disfraz."] = "Если в это время видишь тыквы в тавернах — это Тыквовин: трактирщики дают сладости за «сладость или гадость», а иногда и костюм.",
	["Si en estas fechas ves faroles y fuegos artificiales, es el Festival Lunar: visita a los Ancestros por el mundo, que cada uno te da una moneda."] = "Если в это время видишь фонари и фейерверки — это Лунный фестиваль: навести Старейшин по всему миру, каждый даст монету.",
	["Si en febrero las ciudades huelen a perfume, es «Amor en el aire»: la gente reparte regalos y hasta los guardias reciben detalles."] = "Если в феврале города пахнут духами — это «Любовная лихорадка»: люди дарят подарки, и даже стражникам что-то перепадает.",
	["Si encuentras un hueso, es mío. ¿Trato hecho?"] = "Найдёшь косточку — она моя. Договорились?",
	["Si eres desollador, las zonas llenas de bestias, como raptores, kodos o felinos, te dan cuero sin parar."] = "Если ты снимаешь шкуры, зоны, полные зверей — ящеров, кодо или кошек, — дают кожу без конца.",
	["Si está fuera de tu alcance, su marco se ve más tenue."] = "Если союзник вне досягаемости, его рамка выглядит бледнее.",
	["Si fabricas para otros, cobra justo: la gente vuelve y te recomienda."] = "Если мастеришь для других, бери честную цену: люди вернутся и порекомендуют тебя.",
	["Si hoy cuesta, mañana sale. Aquí sigo contigo."] = "Если сегодня трудно, завтра получится. Я все еще с тобой.",
	["Si juegas sin grupo, la ventana se esconde."] = "Если вы играете без группы, окно скрывается.",
	["Si la pelea va mal, desvanécete y vuelve a empezar."] = "Если бой идет плохо, используйте Исчезновение и начните заново.",
	["Si la recompensa tiene varias opciones, eliges tú."] = "Если в награде несколько вариантов, выбираете вы.",
	["Si la terminas"] = "Если пройдете его",
	["Si la vida baja de la mitad y el sanador no llega, usa Último recurso."] = "Если здоровье упало ниже половины, а лекарь не успевает, используйте «Ни шагу назад».",
	["Si le haces el gesto de gallina a una gallina de granja muchas veces, a veces te pide ayuda... y la historia termina en mascota."] = "Если много раз показать фермерской курице эмоцию «курица», иногда она просит о помощи... и история заканчивается питомцем.",
	["Si llega a 0 % se rompe y deja de darte sus estadísticas. Repara cuanto antes con un herrero o un vendedor que repare."] = "При 0 % вещь ломается и перестаёт давать свои характеристики. Почините её как можно скорее у кузнеца или торговца, который чинит.",
	["Si llegas a exaltado con otra raza de tu bando, te venden sus monturas. ¡Un kodo para un orco o un sable de la noche para un humano!"] = "Если достичь превознесения у другой расы своей фракции, тебе продадут их транспорт. Кодо для орка или ночной саблезуб для человека!",
	["Si llevas puesto el abalorio del Alba Argenta, los no-muertos de las Tierras de la Peste sueltan piedras que cambias por reputación y fichas."] = "Если надет аксессуар Серебряного Рассвета, нежить Чумных земель роняет камни, которые меняют на репутацию и жетоны.",
	["Si lo que te dan mejora tu equipo, te lo pones al salir de combate."] = "Если полученное улучшает экипировку, вы наденете это после выхода из боя.",
	["Si moviste los avisos y ya no los encuentras."] = "Если вы передвинули оповещения и не можете их найти.",
	["Si mueres seguido, cambia al estilo Tranquilo."] = "Если часто умираете, перейдите на стиль «Спокойно».",
	["Si necesitas silencio, con clic derecho me callas un rato."] = "Если нужна тишина, щёлкни по мне правой кнопкой — я ненадолго замолчу.",
	["Si no eres druida, al Claro de la Luna se llega por los túneles de los Fauces de Madera, desde Frondavil."] = "Если ты не друид, на Лунную поляну можно пройти через туннели Древобрюхих из Оскверненного леса.",
	["Si no tienes ninguna abierta, abre la recomendada para tu nivel."] = "Если ни один не открыт, открывает рекомендуемый для вашего уровня.",
	["Si nos perdemos en %s, tú lees el mapa y yo sigo el rastro."] = "Если мы заблудимся в %s, ты читаешь карту, а я иду по следу.",
	["Si peleas de lejos, quédate lejos de ella."] = "Если сражаетесь на расстоянии, держитесь от нее подальше.",
	["Si quieres matar más rápido en solitario, cambia a Armas cuando tengas oro para reiniciar."] = "Если хотите быстрее убивать в одиночку, перейдите на Оружие, когда будет золото на сброс талантов.",
	["Si quieres, tu personaje aparece en el mapa del juego de los lobos que usan Alfa, y ellos en el tuyo: quién anda cerca, dónde y, con un clic, la flecha te lleva. Solo es el lugar de tu personaje dentro de WoW, nunca tu ubicación real. Tu grupo se ve siempre."] = "Если хотите, ваш персонаж появится на карте игры у волков, которые пользуются Alfa, а они — на вашей: кто рядом, где, и одним щелчком стрелка ведет к ним. Это только место персонажа в WoW, никогда ваше реальное местоположение. Ваша группа видна всегда.",
	["Si sigues el consejo"] = "Если последовать совету",
	["Si sigues la cadena del mariscal Windsor, en Ventormenta destaparás quién es en realidad Lady Prestor."] = "Если пройти цепочку маршала Виндзора, в Штормграде ты разоблачишь, кто на самом деле леди Престор.",
	["Si sigues la historia del Templo Sumergido, en el pantano te espera Itharius, un dragón verde."] = "Если следовать истории Затонувшего храма, на болоте тебя ждет Итариус, зеленый дракон.",
	["Si sigues los consejos"] = "Если следовать советам",
	["Si sigues los consejos ganas %s"] = "Если следовать советам, вы получите %s",
	["Si te alcanzan, usa tus golpes cuerpo a cuerpo y aléjate otra vez."] = "Если вас догнали, используйте удары ближнего боя и снова отойдите.",
	["Si te baja mucho la vida, cambia a actitud defensiva: tu ira no se pierde."] = "Если здоровье сильно упало, перейдите в Оборонительную стойку: ярость не теряется.",
	["Si te pegan mientras te vendas, se corta: aléjate un poco antes de usarla."] = "Если тебя ударят во время перевязки, она прервется: отойди немного, прежде чем ее использовать.",
	["Si te quedas sin lanzar"] = "Если вы перестали забрасывать",
	["Si te sobra un pedacito de carne, aquí hay una panza que lo recibe con gusto."] = "Если у тебя лишний кусочек мяса, тут есть животик, который с радостью его примет.",
	["Si tienes poco tiempo, si no tienes con quién jugar o quién te ayude, puedes apoyarte en Alfa y en Lya en tu travesía."] = "Если у вас мало времени, не с кем играть или некому помочь, в пути можно положиться на Alfa и Lya.",
	["Si tu caña no tiene cebo, tu tecla pone el mejor que tengas (o el que prefieras) antes de lanzar."] = "Если на удочке нет приманки, клавиша перед забросом наложит лучшую из имеющихся (или любимую).",
	["Si tu objetivo es un jugador, su fondo toma el color de su clase en lugar del de su reacción."] = "Если ваша цель — игрок, ее фон окрашивается в цвет класса, а не в цвет отношения.",
	["Si tu rango lo permite, la hermandad paga y tu dinero pone el resto."] = "Если звание позволяет, платит гильдия, а остальное — из ваших денег.",
	["Si tú o tus personajes pueden"] = "Если можете вы или ваши персонажи",
	["Si un día ganamos mucho oro, yo ya sé en qué gastarlo: salchichas."] = "Если мы когда-нибудь заработаем много золота, я уже знаю, на что его потратить: на сосиски.",
	["Si un enemigo te persigue, no corras: acércate al tanque."] = "Если противник гонится за вами, не убегайте: подойдите к танку.",
	["Si un enemigo viene hacia ti, llévalo hacia el tanque: no corras lejos."] = "Если противник идет на вас, ведите его к танку: не убегайте далеко.",
	["Si un lugar está lleno de jugadores farmeando lo mismo, cámbiate de zona: te rinde más."] = "Если место забито игроками, которые фармят то же самое, смени зону: выйдет выгоднее.",
	["Si un monstruo esquiva, usa Abrumar enseguida (Alfa te avisa)."] = "Если монстр уклонился, сразу используйте Превосходство (Alfa подскажет).",
	["Si una misión se pone difícil, pide ayuda en el chat. En manada todo pesa menos."] = "Если задание стало трудным, попроси помощи в чате. В стае все легче.",
	["Si una subasta no se vende, pierdes el depósito: no pongas precios fuera de la realidad."] = "Если лот на аукционе не продастся, ты теряешь залог: не ставь нереальные цены.",
	["Si vendes todo al comerciante"] = "Если продать все торговцу",
	["Si ves a otro lobo por ahí, salúdalo de mi parte."] = "Если увидишь где-нибудь другого волка, передай ему привет от меня.",
	["Si ves carpas de colores en Villadorada o en Mulgore, llegó la Feria de la Luna Negra: hay juegos, premios y cartas que se juntan en mazos."] = "Если в Златоземье или Мулгоре видишь пестрые шатры — приехала Ярмарка Новолуния: игры, призы и карты, которые собирают в колоды.",
	["Si viajas con un mago, pídele un portal a la capital: te ahorra mucho camino."] = "Если путешествуешь с магом, попроси портал в столицу: сэкономишь много дороги.",
	["Siempre"] = "Всегда",
	["Siempre con cebo"] = "Всегда с приманкой",
	["Siempre: te ofrece la historia de cada misión y un dato de cada zona nueva. A veces: de las misiones que tomas sin leer, y no siempre. Solo si le pido: con clic derecho, «Cuéntame algo de aquí». Las historias se guardan igual."] = "Всегда: предлагает историю каждого задания и факт о каждой новой зоне. Иногда: о заданиях, которые вы берете не читая, и не каждый раз. Только по просьбе: правый щелчок, «Расскажи что-нибудь об этом месте». Истории сохраняются в любом случае.",
	["Sigilo"] = "Незаметность",
	["Sigilo y emboscadas: tú eliges cuándo pelear y desapareces cuando quieres."] = "Незаметность и засады: вы сами выбираете, когда сражаться, и исчезаете, когда хотите.",
	["Siglos después de la División, los Altonato que no soltaban la magia arcana fueron desterrados. Cruzaron el mar y fundaron Quel'Thalas: son los altos elfos."] = "Через века после Раскола высокорожденных, не желавших отказаться от тайной магии, изгнали. Они пересекли море и основали Кель'Талас: это высшие эльфы.",
	["Siglos después, los orcos Faucedraco usaron el Alma de Demonio para tener presa a Alexstrasza y criar dragones de guerra para la Horda."] = "Века спустя орки Драконьей Пасти с помощью Души Демона держали Алекстразу в плену и разводили боевых драконов для Орды.",
	["Sigue a tu lado, pero no habla hasta las %s."] = "Она все еще рядом, но молчит до %s.",
	["Sigue a tu lado, pero no habla por un rato."] = "Она все еще рядом, но какое-то время молчит.",
	["Sigue donde ibas"] = "Продолжите, где остановились",
	["Sigue la flecha."] = "Следуйте за стрелкой.",
	["Sigue la flecha: las paradas van en el orden más corto, juntas por PNJ."] = "Следуйте за стрелкой: остановки идут в самом коротком порядке, по NPC.",
	["Sigue subiendo: %d de %d"] = "Продолжайте качать: %d из %d",
	["Sigue: %s"] = "Далее: %s",
	["Sigue: %s. Lee sus consejos antes de la pelea."] = "Далее: %s. Прочтите советы перед боем.",
	["Sigues a %s"] = "Вы следуете: %s",
	["Sigues con tu equipo de pesca."] = "На вас все еще рыболовное снаряжение.",
	["Siguiendo"] = "Следование",
	["Siguiendo a %s."] = "Вы следуете за %s.",
	["Siguiendo el rastro"] = "Идем по следу",
	["Siguiendo el rastro de %s. La flecha te lleva hasta su posición."] = "Идем по следу: %s. Стрелка ведет вас к этому игроку.",
	["Siguiendo tu ruta de %s"] = "Идем по маршруту: %s",
	["Siguiente"] = "Далее",
	["Siguiente parada:"] = "Следующая остановка:",
	["Siguiente paso de la guía"] = "Следующий шаг гайда",
	["Siguiente: %s (%d de %d)"] = "Далее: %s (%d из %d)",
	["Silencia los sonidos que agregues por su número de archivo (FileDataID): /alfa silenciar <número>; /alfa silenciar quitar <número> lo quita."] = "Заглушает звуки, которые вы добавите по номеру файла (FileDataID): /alfa silenciar <номер>; /alfa silenciar quitar <номер> убирает его.",
	["Silenciar 1 hora"] = "Отключить звук на 1 час",
	["Silenciar sonidos"] = "Заглушить звуки",
	["Silenciar un sonido por su número (FileDataID)"] = "Заглушить звук по номеру (FileDataID)",
	["Silithus es la puerta de Ahn'Qiraj, donde los silítidos y los qiraji sirven al dios antiguo C'Thun."] = "Силитус — врата Ан'Киража, где силитиды и киражи служат Древнему богу К'Туну.",
	["Sin Minería no ves filones; sin Herboristería, hierbas; sin Pesca, bancos. Los tesoros siempre se ven."] = "Без горного дела не видны жилы, без травничества — травы, без рыбной ловли — косяки. Сокровища видны всегда.",
	["Sin Pesca"] = "Без рыбной ловли",
	["Sin XP descansada"] = "Нет опыта за отдых",
	["Sin acción"] = "Без действия",
	["Sin activar"] = "Выключено",
	["Sin aprender"] = "Не изучено",
	["Sin aullido"] = "Без воя",
	["Sin bloqueos y más claro"] = "Без блокировок и понятнее",
	["Sin cambiar de forma."] = "Вы не в облике.",
	["Sin cambios"] = "Без изменений",
	["Sin datos"] = "Нет данных",
	["Sin demonio"] = "Нет демона",
	["Sin el ratón encima, la barra guarda sus botones y deja solo lo que pasa."] = "Без курсора над ней полоса прячет кнопки и показывает только происходящее.",
	["Sin encantar"] = "Не зачаровано",
	["Sin fuente conocida"] = "Источник неизвестен",
	["Sin grupo"] = "Без группы",
	["Sin límite de tiempo"] = "Без ограничения по времени",
	["Sin mascota"] = "Нет питомца",
	["Sin metas todavía"] = "Целей пока нет",
	["Sin metas todavía. Pulsa + para ponerte una: un pez, capturas, tiempo o valor."] = "Целей пока нет. Нажмите +, чтобы поставить: рыба, улов, время или стоимость.",
	["Sin metas todavía: ábrelo y agrégale una."] = "Целей пока нет: откройте его и добавьте цель.",
	["Sin munición"] = "Нет боеприпасов",
	["Sin objeto"] = "Без предмета",
	["Sin otros personajes, uno solo puede ganar 29: 3 por subir de nivel, 6 de profesiones, 12 de JcJ, 2 de aventura y 6 de mazmorras y bandas. El resto sale de subir otras clases."] = "Без других персонажей один может заработать 29: 3 за уровни, 6 за профессии, 12 за PvP, 2 за приключения и 6 за подземелья и рейды. Остальное — за прокачку других классов.",
	["Sin precio todavía: escanea la subasta."] = "Цены пока нет: просканируйте аукцион.",
	["Sin precios"] = "Нет цен",
	["Sin precios todavía"] = "Цен пока нет",
	["Sin profesión"] = "Без профессии",
	["Sin sello"] = "Нет печати",
	["Sin tecla"] = "Без клавиши",
	["Sin tinte"] = "Без оттенка",
	["Sin ubicación"] = "Нет местоположения",
	["Sin ubicación ahora: en una instancia o fuera del mapa"] = "Сейчас нет местоположения: в подземелье или вне карты",
	["Sin veneno"] = "Нет яда",
	["Sin zona"] = "Без зоны",
	["Sobre Lya"] = "О Lya",
	["Sobre tu compañero, este clic %s."] = "На союзнике этот щелчок %s.",
	["Solo %s"] = "Только %s",
	["Solo al acabarse"] = "Только когда закончится",
	["Solo al moverte"] = "Только в движении",
	["Solo buffs"] = "Только баффы",
	["Solo con quienes usan Alfa y aceptaron compartir. Tú decides."] = "Только с теми, кто пользуется Alfa и согласился делиться. Решаете вы.",
	["Solo cuando estás en grupo"] = "Только в группе",
	["Solo el botín que me sirve"] = "Только подходящая мне добыча",
	["Solo en una fiesta del año"] = "Только во время ежегодного праздника",
	["Solo en warcraft.wiki.gg e Icy Veins: cuántos puntos pide cada premio (15, 25, 40 y 55). Ninguna fuente publica cuánto cuesta cada rango de los árboles: míralo en la ventana del Legado."] = "Только на warcraft.wiki.gg и Icy Veins: сколько очков нужно для каждой награды (15, 25, 40 и 55). Ни один источник не публикует, сколько стоит каждый ранг деревьев: смотрите в окне «Наследия».",
	["Solo encontré %d misiones que te sirvan ahora."] = "Сейчас подходящих заданий найдено только: %d.",
	["Solo importantes"] = "Только важные",
	["Solo la entrada"] = "Только вход",
	["Solo las misiones de tu ruta"] = "Только задания вашего маршрута",
	["Solo las que puedes tomar: tu bando, raza, clase y nivel, y que no hayas hecho."] = "Только те, что можно взять: ваша фракция, раса, класс и уровень, и еще не выполненные.",
	["Solo lo de mi papel"] = "Только для моей роли",
	["Solo lo que tu clase puede usar y le conviene a tu especialización."] = "Только то, что может использовать ваш класс и что подходит вашей специализации.",
	["Solo lo que tu personaje puede usar hoy: clase, armadura, armas, nivel y profesión."] = "Только то, что ваш персонаж может использовать сегодня: класс, доспехи, оружие, уровень и профессия.",
	["Solo lo que ya puedes recolectar"] = "Только то, что уже можете собрать",
	["Solo los de la zona donde estás."] = "Только те, что в вашей текущей зоне.",
	["Solo los de tus profesiones, en el mapa del mundo y en el minimapa."] = "Только для ваших профессий, на карте мира и мини-карте.",
	["Solo los graves"] = "Только серьезные",
	["Solo los que me apuntan a mí"] = "Только направленные на меня",
	["Solo misiones de XP, las mejores cerca de ti, en tres tandas."] = "Только задания на опыт, лучшие рядом с вами, в три захода.",
	["Solo para %s."] = "Только для: %s.",
	["Solo para mirar: tu paso de ahora no cambia. Alfa avanza sola cuando lo cumples."] = "Только посмотреть: текущий шаг не меняется. Alfa сам перейдет дальше, когда вы его выполните.",
	["Solo puedes tener dos principales a la vez; las secundarias son libres. Se aprenden con su entrenador en las ciudades."] = "Основных профессий одновременно может быть только две; вспомогательные — без ограничений. Их изучают у учителей в городах.",
	["Solo salen los clanes donde puedes invitar, y Alfa te confirma en el chat a quién invitaste. Lo apagas en La Jauría > Invitar."] = "Показываются только те места, куда вы можете приглашать, а Alfa подтверждает в чате, кого вы пригласили. Отключается в La Jauría > Пригласить.",
	["Solo se admite la versión 1 de la cadena de escala."] = "Поддерживается только версия 1 строки шкалы.",
	["Solo si falta"] = "Только если нет",
	["Solo si le pido"] = "Только по просьбе",
	["Solo sirve con un monitor HDR y el HDR de Windows encendido (Configuración > Pantalla). Sin eso, déjalo apagado: los colores se ven lavados."] = "Работает только с HDR-монитором и включенным HDR в Windows (Параметры > Дисплей). Без этого оставьте выключенным: цвета будут блеклыми.",
	["Solo tocan gráficos: nunca la cámara, el ratón ni la interfaz. «Deshacer» devuelve lo que tenías antes del último que aplicaste."] = "Меняют только графику: никогда камеру, мышь или интерфейс. «Отменить» возвращает то, что было до последнего примененного набора.",
	["Solo tu grupo y quienes usan Alfa y aceptaron compartir."] = "Только ваша группа и те, кто пользуется Alfa и согласился делиться.",
	["Solo tú"] = "Только вы",
	["Solo tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "Только вы, ваша группа, ваши маркеры и следующий шаг гайда.",
	["Sombra"] = "Тьма",
	["Sombra para subir"] = "Тьма для прокачки",
	["Sombra suave en rincones, pliegues y bajo los objetos: da volumen a todo."] = "Мягкая тень в углах, складках и под объектами: придает всему объем.",
	["Sombras"] = "Тени",
	["Sombras con bordes más finos. Usa más memoria de video."] = "Тени с более тонкими краями. Использует больше видеопамяти.",
	["Sombras suaves"] = "Мягкие тени",
	["Son %s más que venderlo todo al comerciante."] = "Это на %s больше, чем продать все торговцу.",
	["Son puntos de tu cuenta: los ganas con los retos del Legado (logros de Forever) en cualquier personaje, y cada personaje los gasta por su cuenta en sus árboles."] = "Это очки учетной записи: вы зарабатываете их испытаниями «Наследия» (достижения Forever) любым персонажем, а каждый персонаж тратит их сам в своих деревьях.",
	["Son tres enanos que pelean juntos: uno dispara de lejos, otro es muy veloz y otro se protege con escudo. Mátenlos uno por uno."] = "Это три дворфа, которые сражаются вместе: один стреляет издалека, другой очень быстрый, а третий закрывается щитом. Убивайте их по одному.",
	["Sonido"] = "Звук",
