	["Su botín está por descubrir"] = "Добычу еще предстоит открыть",
	["Su electricidad salta de un jugador a otro: sepárense."] = "Его электричество перескакивает с игрока на игрока: разойдитесь.",
	["Su final no alcanzó a guardarse."] = "Ее концовку не успели сохранить.",
