	["Subir cocina y pesca juntas"] = "Качать кулинарию и рыбную ловлю вместе",
	["Subir como tanque: más lento que Armas, pero casi nunca mueres, juntas varios monstruos a la vez y llegas listo para tanquear cualquier mazmorra."] = "Прокачка танком: медленнее, чем Оружие, но вы почти никогда не умираете, берете нескольких монстров сразу и приходите готовым танковать любое подземелье.",
	["Subir de nivel"] = "Повысить уровень",
	["Subir de nivel, profesiones, hacer oro o mazmorras: dos clics y Alfa te lleva."] = "Прокачка, профессии, золото или подземелья: два щелчка, и Alfa отведет вас.",
	["Subir de nivel, profesiones, oro o mazmorras."] = "Прокачка, профессии, золото или подземелья.",
	["Subir el sonido al pescar"] = "Громче звук во время рыбалки",
	["Subir rápido"] = "Быстрая прокачка",
	["Subir solo"] = "Прокачка в одиночку",
	["Subir una profesión"] = "Развить профессию",
	["Succionar vida: daño con el tiempo que te cura."] = "Вытягивание жизни: периодический урон, который лечит вас.",
	["Suelta"] = "Роняет",
	["Suelta el lanzamiento de ahora y lanza otra vez, sin poner equipo ni cebo."] = "Отменяет текущий заброс и забрасывает снова, без снаряжения и приманки.",
	["Suelta lo que tienes en el cursor y vuelve a intentarlo."] = "Отпустите то, что держите на курсоре, и попробуйте снова.",
	["Suelta una carta que empieza una misión: revisa su botín."] = "С него падает письмо, которое начинает задание: проверьте его добычу.",
	["Suelta una llave que abre una puerta más adelante: alguien debe recogerla."] = "С него падает ключ, который открывает дверь дальше: кто-то должен его подобрать.",
	["Suelta una nube de enfermedad a su alrededor: quiten enfermedades."] = "Выпускает вокруг себя облако болезни: снимайте болезни.",
	["Suelta una ola de fuego a su alrededor: si peleas de lejos, quédate lejos de él."] = "Выпускает вокруг себя волну огня: если сражаетесь на расстоянии, держитесь от него подальше.",
	["Suena ahora, aunque el aullido esté apagado."] = "Воспроизводит сейчас, даже если вой выключен.",
	["Sueño con una montaña de salchichas... y yo en la punta, feliz."] = "Мне снится гора сосисок... и я на самой вершине, счастливая.",
