	["Sugerir qué vender"] = "Подсказывать, что продать",
	["Sulfuras es el martillo de Ragnaros. Con su ojo, los más valientes pueden forjar una versión legendaria."] = "Сульфурас — молот Рагнароса. С его глазом самые смелые могут выковать легендарную версию.",
	["Suma tus sesiones de hoy con este personaje."] = "Сумма за сегодняшние сеансы этого персонажа.",
	["Suma «conseguir este objeto» a tu plan de ahora (o a uno nuevo)."] = "Добавляет «получить этот предмет» в текущий план (или в новый).",
	["Supervivencia"] = "Выживание",
	["Supervivencia para subir"] = "Выживание для прокачки",
	["Sus bolas de sombra pegan mucho: interrúmpelo."] = "Его стрелы Тьмы бьют сильно: прерывайте его.",
	["Sus consejos"] = "Ее советы",
	["Sus consejos te esperan en Alfa."] = "Его советы ждут вас в Alfa.",
	["Sus jefes, su botín, sus misiones y cómo llegar."] = "Его боссы, добыча, задания и как туда добраться.",
	["Sus misiones dan"] = "Его задания дают",
	["Sus rayos saltan entre jugadores: sepárense."] = "Ее молнии перескакивают между игроками: разойдитесь.",
	["Sutileza"] = "Скрытность",
	["Sutileza para subir"] = "Скрытность для прокачки",
	["Sylvanas era hermana de Alleria y de Vereesa Brisaveloz. Hoy guía a los Renegados con mano firme."] = "Сильвана была сестрой Аллерии и Верисы Ветрокрылых. Сегодня она твердой рукой ведет Отрекшихся.",
	["Sylvanas recibe en el Barrio Real de Entrañas, con Varimathras a su lado."] = "Сильвана принимает в Королевском квартале Подгорода, а рядом с ней Вариматрас.",
	["Sylvanas tiene dos hermanas: Alleria, que se fue más allá del Portal Oscuro, y Vereesa, que se casó con el mago Rhonin."] = "У Сильваны две сестры: Аллерия, ушедшая за Темный портал, и Вериса, вышедшая замуж за мага Ронина.",
	["Sí"] = "Да",
