	["Te faltan ingredientes para el siguiente lote."] = "Не хватает ингредиентов для следующей партии.",
	["Te faltan ingredientes."] = "Не хватает ингредиентов.",
	["Te faltan niveles para llegar a %d: la guía te lo marca y sigues subiendo con tu ruta."] = "До уровня %d еще далеко: гайд отметит это, а вы продолжите качаться по маршруту.",
	["Te faltan niveles: cada nivel desde el 10 te da un punto."] = "Не хватает уровней: каждый уровень начиная с 10 дает одно очко.",
	["Te la da %s, en %s."] = "Выдает: %s, %s.",
	["Te la da %s."] = "Выдает: %s.",
	["Te la dio %s"] = "Выдал: %s",
	["Te la dio %s · Se entrega con %s"] = "Выдал: %s · Сдать: %s",
	["Te la dio y la recibe %s"] = "Выдает и принимает: %s",
	["Te lleva a las misiones de tu ruta que ya puedes tomar."] = "Ведет к заданиям вашего маршрута, которые уже можно взять.",
	["Te llevo a %s"] = "Веду вас: %s",
	["Te llevo a la mejor fuente. Recuerda que una montura pide nivel, equitación y oro."] = "Веду вас к лучшему источнику. Помните: для верхового животного нужны уровень, верховая езда и золото.",
	["Te llevo a quien recibe cada una y recoges las que siguen."] = "Отведу вас к тому, кто принимает каждое задание, и вы возьмете следующие.",
	["Te lo da un PNJ"] = "Выдает NPC",
	["Te lo enseña cualquier instructor de pesca. Hasta que lo aprendas, tu habilidad no pasa del tope."] = "Обучит любой учитель рыбной ловли. Пока вы не изучите, навык не поднимется выше предела.",
	["Te lo enseña tu entrenador."] = "Изучается у учителя.",
	["Te lo pido de corazón: nunca desuelles a un lobo enfrente de mí, ¿sí?"] = "Прошу от всего сердца: никогда не снимай шкуру с волка при мне, ладно?",
	["Te los enseña tu entrenador."] = "Изучаются у учителя.",
	["Te queda 1 espacio"] = "Осталась 1 ячейка",
	["Te queda muy poco maná: Estimular lo recupera."] = "Маны очень мало: Озарение восполнит ее.",
	["Te queda muy poco maná: Evocación lo recupera."] = "Маны очень мало: Прилив сил восполнит ее.",
	["Te queda poca XP descansada"] = "Опыт за отдых заканчивается",
	["Te queda poco maná y te sobra vida: cambia vida por maná."] = "Маны мало, а здоровья с избытком: обменяйте здоровье на ману.",
	["Te queda poco maná: cambia vida por maná."] = "Мало маны: обменяйте здоровье на ману.",
	["Te queda poco maná: usa tu varita."] = "Маны мало: используйте жезл.",
	["Te quedan %d de %d espacios"] = "Осталось ячеек: %d из %d",
	["Te saluda según la hora, comenta la zona y a veces se sienta a pedirte algo con su huesito."] = "Она здоровается по времени суток, говорит о зоне, а иногда садится и выпрашивает что-нибудь со своей косточкой.",
	["Te sobra ira y hay varios enemigos: tu siguiente golpe alcanza a dos."] = "Ярости в избытке и противников несколько: следующий удар заденет двоих.",
	["Te sobra ira: gástala en tu siguiente golpe."] = "Ярости в избытке: потратьте ее на следующий удар.",
	["Te sobra ira: tu siguiente golpe es más fuerte."] = "Ярости в избытке: следующий удар будет сильнее.",
	["Te sugiere objetivos de pasos más adelante que tienes muy cerca."] = "Предлагает цели следующих шагов, которые совсем рядом.",
	["Te sugiere qué habilidad usar ahora y cuáles siguen. Solo sugiere: nunca presiona nada por ti."] = "Подсказывает, какую способность использовать сейчас и какие дальше. Только подсказывает: никогда ничего не нажимает за вас.",
	["Tecla del modo pesca"] = "Клавиша режима рыбалки",
	["Tecla fija para pescar"] = "Постоянная клавиша для рыбалки",
	["Tecla para abrir o cerrar el modo"] = "Клавиша, чтобы открыть или закрыть режим",
	["Tecla para volver a lanzar"] = "Клавиша перезаброса",
	["Tecla y modo pesca"] = "Клавиша и режим рыбалки",
	["Tela"] = "Ткань",
	["Teldrassil es tan grande que entre sus ramas hay colinas, lagos y cuevas."] = "Тельдрассил так огромен, что в его ветвях есть холмы, озера и пещеры.",
	["Teldrassil es un árbol del mundo que los elfos de la noche plantaron sin la bendición de los dragones. Por eso no les dio la inmortalidad."] = "Тельдрассил — мировое древо, которое ночные эльфы посадили без благословения драконов. Поэтому оно не дало им бессмертия.",
	["Teldrassil se plantó para recuperar la inmortalidad, pero sin la bendición de los dragones. Algo en él no anda bien."] = "Тельдрассил посадили, чтобы вернуть бессмертие, но без благословения драконов. С ним что-то не так.",
	["Ten siempre a mano una poción de vida: este build no perdona errores."] = "Всегда держите под рукой зелье здоровья: этот билд не прощает ошибок.",
	["Tenga o no"] = "Есть или нет",
	["Tengo hambre… ¿me compartes algo de tu mochila?"] = "Я проголодалась… поделишься чем-нибудь из сумки?",
	["Terenas Menethil, rey de Lordaeron, unió a los reinos en la Alianza de Lordaeron. Años después, su propio hijo Arthas lo mató en su trono."] = "Теренас Менетил, король Лордерона, объединил королевства в Альянс Лордерона. Годы спустя собственный сын Артас убил его на троне.",
	["Termina la configuración para usar Alfa (2 minutos)."] = "Завершите настройку, чтобы пользоваться Alfa (2 минуты).",
	["Terminada"] = "Выполнено",
	["Terminado: cumpliste todas sus metas."] = "Готово: вы выполнили все его цели.",
	["Terminar la cadena de Lord Valthalak también es un reto del Legado."] = "Пройти цепочку Лорда Вальталака — тоже испытание «Наследия».",
	["Terminaste %d de sus misiones: entrégalas y recoge las que siguen."] = "Выполнено его заданий: %d. Сдайте их и возьмите следующие.",
	["Terminaste 1 de sus misiones: entrégala y recoge las que siguen."] = "Выполнено 1 его задание: сдайте его и возьмите следующие.",
	["Terminaste esta guía."] = "Вы прошли этот гайд.",
	["Terminaste esta guía. Elige la siguiente para seguir subiendo."] = "Вы прошли этот гайд. Выберите следующий, чтобы продолжить прокачку.",
	["Termínala antes de entregarla."] = "Выполните его, прежде чем сдавать.",
	["Terreno, como el minimapa"] = "Рельеф, как на мини-карте",
	["Terreno: al acercarte se ve el suelo real del minimapa, con sus montañas, ríos y tonos. Clásico: solo el mapa pintado del juego."] = "Рельеф: при приближении видна настоящая земля мини-карты с горами, реками и оттенками. Классическая: только нарисованная карта игры.",
	["Tesoro"] = "Сокровище",
	["Tesoros"] = "Сокровища",
	["Tesoros en el mapa"] = "Сокровища на карте",
	["Tesoros en el minimapa"] = "Сокровища на мини-карте",
	["Texto de combate flotante"] = "Всплывающий текст боя",
	["Texto sobre tu personaje"] = "Текст над персонажем",
	["Textos y cajas mejor alineados en las ventanas de Alfa."] = "Тексты и поля лучше выровнены в окнах Alfa.",
	["Texturas del mundo"] = "Текстуры мира",
	["Texturas del suelo"] = "Текстуры земли",
	["Texturas proyectadas"] = "Проецируемые текстуры",
	["Texturas y nitidez"] = "Текстуры и резкость",
	["Theradras, la princesa de la tierra, es hija de Therazane. Amó a Zaetar, hijo de Cenarius, y sus hijos, los centauros, terminaron matándolo."] = "Терадрас, принцесса земли, — дочь Теразан. Она любила Зейтара, сына Кенария, а их дети, кентавры, в итоге убили его.",
	["Theramore la fundó Jaina Valiente con los humanos que salieron de Lordaeron antes de su caída."] = "Терамор основала Джайна Праудмур с людьми, покинувшими Лордерон до его падения.",
	["Thrall eligió esta tierra roja y seca para que los orcos libres empezaran de nuevo, lejos de los campos de internamiento de los humanos."] = "Тралл выбрал эту красную сухую землю, чтобы свободные орки начали заново, вдали от лагерей для интернированных.",
	["Thrall es el chamán más famoso: los elementos le responden como a nadie."] = "Тралл — самый знаменитый шаман: стихии откликаются ему как никому.",
	["Thrall gobierna la Horda desde Orgrimmar como jefe de guerra, con la mirada puesta en la paz."] = "Тралл правит Ордой из Оргриммара как вождь, думая о мире.",
	["Thrall liberó a los orcos de los campos de internamiento con la ayuda de Grom Grito Infernal y de Orgrim Martillo Maldito."] = "Тралл освободил орков из лагерей для интернированных с помощью Грома Адского Крика и Оргрима Молота Рока.",
	["Thrall nació en Draenor, hijo de Durotan y Draka. Aedelas Blackmoore lo encontró de bebé y lo llamó «Thrall», que quiere decir esclavo."] = "Тралл родился на Дреноре, сын Дуротана и Дреки. Эделас Блэкмур нашел его младенцем и назвал «Траллом», что значит «раб».",
	["Thrall quiere que los orcos recuperen el honor que tenían antes de la corrupción demoníaca."] = "Тралл хочет, чтобы орки вернули честь, которая была у них до демонической порчи.",
	["Tiempo"] = "Время",
	["Tiempo de juego por sesión"] = "Время игры за сеанс",
	["Tiempo hasta que pica"] = "Время до поклевки",
	["Tiempo máximo entre los dos clics. Súbelo si tus dobles clics no lanzan."] = "Наибольшее время между двумя щелчками. Увеличьте его, если двойной щелчок не забрасывает.",
	["Tiempo pescando"] = "Время за рыбалкой",
	["Tiene cuatro partes que se hacen por separado: Cementerio, Biblioteca, Armería y Catedral, de la más fácil a la más difícil."] = "Состоит из четырех частей, которые проходятся отдельно: Кладбище, Библиотека, Оружейная и Собор, от самой легкой к самой трудной.",
	["Tienes"] = "У вас",
	["Tienes %d"] = "У вас %d",
	["Tienes %d  ·  en %s"] = "У вас %d  ·  в %s",
	["Tienes %d casillas libres"] = "Свободных ячеек: %d",
	["Tienes %d de %d"] = "У вас %d из %d",
	["Tienes %d de %d casillas de bolsa en el banco."] = "Ячеек для сумок в банке: %d из %d.",
	["Tienes %d de %d casillas de bolsa. La siguiente cuesta %s; después pon una bolsa en ella."] = "Ячеек для сумок: %d из %d. Следующая стоит %s; затем положите в нее сумку.",
	["Tienes %d encendidas. Abajo está cada una, con lo que hace, por si quieres cambiar algo."] = "Включено: %d. Ниже каждая — с описанием, если захотите что-то изменить.",
	["Tienes %d misiones listas para entregar"] = "Заданий, готовых к сдаче: %d",
	["Tienes %d misiones listas para entregar. ¿Las juntamos en una ruta?"] = "Готовых к сдаче заданий: %d. Соберем их в один маршрут?",
	["Tienes %d para gastar"] = "Можно потратить: %d",
	["Tienes %d piezas mejores para pescar en tus bolsas."] = "В сумках есть лучшие предметы для рыбалки: %d.",
	["Tienes %d puntos de talento: empieza por %s"] = "Очков талантов: %d. Начните с «%s»",
	["Tienes %d puntos fuera de %s. Alfa nunca quita talentos: para seguir este build, reinicia tus talentos con tu entrenador de clase y Alfa te los vuelve a poner con un clic. O elige el build de la rama que ya llevas."] = "Очков вне ветки: %d (%s). Alfa никогда не сбрасывает таланты: чтобы следовать этому билду, сбросьте таланты у учителя класса, и Alfa расставит их заново в один щелчок. Или выберите билд ветки, в которую вы уже вложились.",
	["Tienes %d puntos libres, pero los talentos que siguen en %s no existen en tu árbol (puede que cambiaran con un parche). Ponlos a mano en la ventana del juego o prueba otro estilo."] = "Свободных очков: %d, но следующих талантов из «%s» нет в вашем дереве (возможно, их изменил патч). Распределите их вручную в окне игры или попробуйте другой стиль.",
	["Tienes %s de %s"] = "У вас %s из %s",
	["Tienes %s precios de tus búsquedas. Para conocer todos, escanea en la casa de subastas."] = "У вас цен из ваших поисков: %s. Чтобы знать все, просканируйте аукцион.",
	["Tienes 1 misión lista para entregar"] = "1 задание готово к сдаче",
	["Tienes 5 puntos de combo y estás en grupo: el sangrado rinde más."] = "У вас 5 очков серии и вы в группе: кровотечение выгоднее.",
	["Tienes 5 puntos de combo: el remate más fuerte."] = "У вас 5 очков серии: самый сильный завершающий прием.",
	["Tienes 5 puntos de combo: muerde fuerte."] = "У вас 5 очков серии: кусайте сильнее.",
	["Tienes 6 guías abiertas"] = "У вас открыто 6 гайдов",
	["Tienes activado «Rechazar invitaciones a hermandad» en Ajustes > Comodidades > Social: apágalo para que te llegue la invitación."] = "У вас включено «Отклонять приглашения в гильдию» в Настройки > Удобства > Общение: выключите, чтобы приглашение дошло до вас.",
	["Tienes cambios sin confirmar en la ventana de talentos: se descartan antes de aplicar."] = "В окне талантов есть неподтвержденные изменения: они будут отброшены перед применением.",
	["Tienes cambios sin guardar en la ventana de talentos del juego: guárdalos o deshazlos ahí primero"] = "В окне талантов игры есть несохранённые изменения: сначала сохраните или отмените их там",
	["Tienes encendido «solo las misiones de mi ruta»: solo acepta las de tu ruta."] = "Включено «только задания моего маршрута»: принимаются только задания вашего маршрута.",
	["Tienes furia: úsalo antes de la siguiente pelea, te da más poder de ataque a ti y a tu grupo."] = "У вас есть ярость: используйте его до следующего боя, он дает больше силы атаки вам и вашей группе.",
	["Tienes habilidades nuevas"] = "У вас есть новые навыки",
	["Tienes habilidades sin aprender (%d). Aprenderlas te hace más fuerte."] = "Есть неизученные способности (%d). Изучи их — станешь сильнее.",
	["Tienes la %s, %d versiones atrás."] = "У вас версия %s (новых версий с тех пор: %d).",
	["Tienes la %s."] = "У вас версия %s.",
	["Tienes más rangos de los que pide tu build."] = "У вас больше рангов, чем требует билд.",
	["Tienes puesto «%s». Abre la ventana para afinar cada detalle: distancia, pasto, niebla, agua, cámara, placas y filtros."] = "Применен набор «%s». Откройте окно, чтобы настроить каждую мелочь: дальность, траву, туман, воду, камеру, индикаторы и фильтры.",
	["Tienes puntos fuera del plan: Alfa no los quita, solo agrega."] = "У вас есть очки вне плана: Alfa их не убирает, только добавляет.",
	["Tienes seis guías abiertas: cierra una y vuelve a intentarlo."] = "У вас открыто шесть гайдов: закройте один и попробуйте снова.",
	["Tienes todo %s"] = "У вас есть все: %s",
	["Tienes un hechizo para ir al Claro de la Luna, el santuario de los druidas."] = "У тебя есть заклинание, переносящее на Лунную поляну, святилище друидов.",
	["Tienes un punto de talento: %s"] = "У вас 1 очко таланта: %s",
	["Tienes una misión de clase"] = "У вас есть классовое задание",
	["Tinte de color"] = "Цветовой оттенок",
	["Tipo"] = "Тип",
	["Tirion Vadín fue expulsado de la Mano de Plata por defender a Eitrigg, un orco que le salvó la vida. Hoy Eitrigg aconseja a Thrall en Orgrimmar."] = "Тириона Фордринга изгнали из ордена Серебряной Длани за то, что он заступился за Эйтригга, орка, спасшего ему жизнь. Сегодня Эйтригг советник Тралла в Оргриммаре.",
	["Tirion Vadín, el paladín expulsado de la orden, vive solo en una cabaña de estas tierras."] = "Тирион Фордринг, изгнанный из ордена паладин, живет один в хижине в этих краях.",
	["Toca ahora"] = "Сейчас",
	["Toca el interruptor para poner o quitar una; lo que tocas manda sobre el filtro."] = "Переключите тумблер, чтобы добавить или убрать задание; ваш выбор важнее фильтра.",
	["Toda calidad"] = "Любое качество",
	["Toda fuente"] = "Любой источник",
	["Toda la cuenta"] = "Вся учетная запись",
	["Toda ranura"] = "Любая ячейка",
	["Todas"] = "Все",
	["Todas (%d)"] = "Все (%d)",
	["Todas las guías de profesiones"] = "Все гайды профессий",
	["Todas las guías por zona y nivel, con la que Alfa te sugiere para ti."] = "Все гайды по зонам и уровням — с тем, который Alfa рекомендует вам.",
	["Todas las mascotas de compañía: dónde salen, cuánto cuestan y cuáles te faltan."] = "Все питомцы: откуда берутся, сколько стоят и каких у вас нет.",
	["Todas las mazmorras"] = "Все подземелья",
	["Todas las metas, notas y pasos de esta guía en otra ventana."] = "Все цели, заметки и шаги этого гайда в отдельном окне.",
	["Todas las misiones"] = "Все задания",
	["Todas las misiones que Lya te guardó, por zona, con su historia completa. También con /alfa historias."] = "Все задания, которые Lya сохранила для вас, по зонам, с полной историей. Также командой /alfa historias.",
	["Todas las monturas: cómo se consigue cada una, qué pide y si ya la tienes."] = "Весь транспорт: как получить каждый, что он требует и есть ли он у вас.",
	["Todas las profesiones"] = "Все профессии",
	["Todas las zonas"] = "Все зоны",
	["Todas las zonas y razas"] = "Все зоны и расы",
	["Todavía es pronto"] = "Пока рано",
	["Todavía nada en esta sesión"] = "В этом сеансе пока ничего",
	["Todavía no"] = "Пока нет",
	["Todavía no conoces sus hechizos: se llenan al aprenderlos."] = "Вы еще не знаете этих заклинаний: они появятся, когда вы их изучите.",
	["Todavía no conozco tus recetas"] = "Я пока не знаю ваших рецептов",
	["Todavía no es para ti"] = "Пока не для вас",
	["Todavía no estás en una hermandad. En la página La Jauría ves cómo unirte a la manada."] = "Вы пока не состоите в гильдии. На странице La Jauría рассказано, как вступить в стаю.",
	["Todavía no has pescado nada en esta sesión"] = "В этом сеансе вы еще ничего не поймали",
	["Todavía no hay ayuda de rotación para ti"] = "Для вас пока нет помощника ротации",
	["Todavía no hay datos de este personaje"] = "Данных об этом персонаже пока нет",
	["Todavía no hay datos para esta gráfica."] = "Для этого графика пока нет данных.",
	["Todavía no hay foto de este banco"] = "Снимка этого банка пока нет",
	["Todavía no hay peleas"] = "Боев пока нет",
	["Todavía no hay progreso"] = "Прогресса пока нет",
	["Todavía no hay una pelea anterior"] = "Предыдущего боя пока нет",
	["Todavía no hay una pelea que anunciar."] = "Пока нечего объявлять.",
	["Todavía no lo pescas"] = "Еще не поймано",
	["Todavía no lo recolectas"] = "Еще не собирали",
	["Todavía no lo sacas del agua. Cuando lo hagas, aquí verás cuántos llevas, cuándo y dónde."] = "Вы ее еще не вытащили. Когда вытащите, здесь будет видно, сколько, когда и где.",
	["Todavía no pescas en %s. Lo que saques aquí se anota por zona."] = "Вы еще не рыбачили в %s. Улов здесь записывается по зонам.",
	["Todavía no puedes conseguirlo: %s."] = "Пока нельзя получить: %s.",
	["Todavía no recolectas nada"] = "Вы еще ничего не собрали",
	["Todavía no sabes pescar"] = "Вы еще не умеете рыбачить",
	["Todavía no se puede tomar: Alfa la recoge cuando se abra."] = "Пока нельзя взять: Alfa возьмет его, когда откроется.",
	["Todavía no sigues ninguna guía. Elige una y Alfa te lleva paso a paso, con la flecha y la ruta."] = "Вы пока не идете ни по одному гайду. Выберите гайд, и Alfa поведет вас шаг за шагом — стрелкой и маршрутом.",
	["Todavía no te alcanza."] = "Денег пока не хватает.",
	["Todavía no tienes escalas propias. Pega una cadena de escala arriba."] = "Своих шкал пока нет. Вставьте строку шкалы выше.",
	["Todavía no tienes marcadores"] = "Маркеров пока нет",
	["Todavía no tienes rutas propias"] = "Собственных маршрутов пока нет",
	["Todavía no tienes talentos para compartir."] = "Пока нет талантов, которыми можно поделиться.",
	["Todavía no tienes una guía abierta. Elige una y Alfa te lleva paso a paso: a dónde ir, qué hacer y con quién hablar."] = "У вас еще нет открытого гайда. Выберите его, и Alfa поведет вас шаг за шагом: куда идти, что делать и с кем говорить.",
	["Todavía quedan pilones de los titanes en el cráter, y funcionan con cristales de colores."] = "В кратере до сих пор стоят пилоны титанов, и они работают на цветных кристаллах.",
	["Todo"] = "Всё",
	["Todo Azeroth en un solo lienzo: acerca con la rueda, arrastra para moverte y pon tus marcadores con clic derecho."] = "Весь Азерот на одном холсте: приближайте колесом, перетаскивайте, чтобы двигаться, и ставьте маркеры правым щелчком.",
	["Todo a la mano"] = "Всё под рукой",
	["Todo al máximo seguro. Pide una tarjeta de video fuerte."] = "Все на безопасном максимуме. Нужна мощная видеокарта.",
	["Todo bien (lo más gastado: %d%%)"] = "Все в порядке (самое изношенное: %d%%)",
	["Todo como estaba antes de Alfa"] = "Все как было до Alfa",
	["Todo con tu estilo"] = "Все в вашем стиле",
	["Todo el juego, aunque no lo tengas"] = "Вся игра, даже то, чего у вас нет",
	["Todo el juego, aunque no lo tengas: objetos, PNJ, misiones, zonas y raros."] = "Вся игра, даже то, чего у вас нет: предметы, NPC, задания, зоны и редкие.",
	["Todo el juego, aunque no lo tengas: objetos, monturas, mascotas, PNJ, misiones, zonas y raros."] = "Вся игра, даже то, чего у вас нет: предметы, транспорт, питомцы, NPC, задания, зоны и редкие существа.",
	["Todo en orden"] = "Все в порядке",
	["Todo esto lo hace Alfa sola al hablar con quien da o recibe una misión. Mantén presionado Mayús para hacerlo tú en el momento."] = "Все это Alfa делает сам, когда вы говорите с тем, кто выдает или принимает задание. Удерживайте Shift, чтобы в этот момент сделать это самостоятельно.",
	["Todo junto"] = "Все вместе",
	["Todo junto muestra cada casilla en su lugar; por categorías agrupa equipo, consumibles, misiones y materiales; por bolsa pone cada bolsa en su bloque."] = "«Все вместе» показывает каждую ячейку на своем месте; «По категориям» группирует снаряжение, расходуемые предметы, предметы заданий и материалы; «По сумкам» выводит каждую сумку отдельным блоком.",
	["Todo listo"] = "Все готово",
	["Todo lo que no sea equipo"] = "Все, кроме снаряжения",
	["Todo lo que se pinta en tus mapas, en un solo lugar. Lo de otros módulos de Alfa también llega aquí."] = "Все, что рисуется на ваших картах, в одном месте. Сюда попадает и то, что добавляют другие модули Alfa.",
	["Todo nivel"] = "Любой уровень",
	["Todo objeto, PNJ, misión, zona y raro, con dónde conseguirlo y «Guíame»."] = "Любой предмет, NPC, задание, зона и редкий — с тем, где это получить, и «Веди меня».",
	["Todo oficio"] = "Все роли",
	["Todo para el daño: críticos, sangrados y Abrumar muy seguido. Matas rapidísimo, pero no hay defensa extra: si se te juntan muchos, corre."] = "Все ради урона: критические удары, кровотечения и очень частое Превосходство. Вы убиваете очень быстро, но дополнительной защиты нет: если на вас навалилось много противников, бегите.",
	["Todo subtipo"] = "Любой подтип",
	["Todo tipo"] = "Любой тип",
	["Todos"] = "Все",
	["Todos llegan a %s"] = "Все ведут к %s",
	["Todos los de ese tipo, o solo uno (por ejemplo, solo cobre). Entre paréntesis, cuántos hay en tu zona."] = "Все этого типа или только один (например, только медь). В скобках — сколько их в вашей зоне.",
	["Todos los materiales"] = "Все материалы",
	["Todos los niveles"] = "Все уровни",
	["Todos los objetos, PNJ, misiones, zonas y raros, aunque no los tengas: quién lo suelta y con qué probabilidad, quién lo vende y dónde, qué misión lo da y cómo llegar."] = "Все предметы, NPC, задания, зоны и редкие, даже те, что у вас нет: кто роняет и с какой вероятностью, кто продает и где, какое задание дает и как туда добраться.",
	["Todos los objetos, monturas, mascotas, PNJ, misiones, zonas y raros, aunque no los tengas: quién lo suelta y con qué probabilidad, quién lo vende y dónde, qué misión lo da y cómo llegar."] = "Все предметы, транспорт, питомцы, NPC, задания, зоны и редкие существа, даже те, которых у вас нет: кто роняет и с каким шансом, кто продает и где, какое задание дает и как туда добраться.",
	["Todos los paladines sueñan con la Crematoria, la espada de Alexandros Mograine."] = "Все паладины мечтают об Испепелителе, мече Александроса Могрейна.",
	["Todos los pasos"] = "Все шаги",
	["Todos los pasos de esta guía; clic en uno para verlo."] = "Все шаги этого гайда; щелкните по шагу, чтобы посмотреть его.",
	["Todos los pasos de la guía en la ventana de guía."] = "Все шаги гайда — в окне гайда.",
	["Todos los tipos"] = "Все типы",
	["Todos tus puntos ya están gastados y parte de ellos fuera de este build. Para cambiarte a este build, reinicia tus talentos con tu entrenador de clase; después Alfa te los aplica con un clic."] = "Все ваши очки уже потрачены, и часть из них — вне этого билда. Чтобы перейти на этот билд, сбросьте таланты у учителя своего класса; затем Alfa применит их одним щелчком.",
	["Todos: también los avisos leves. Solo los graves: únicamente lo que puede matarte."] = "Все: включая легкие предупреждения. Только серьезные: лишь то, что может вас убить.",
	["Toma el botín de la pesca enseguida, aunque tengas apagado el botín automático del juego."] = "Сразу забирает добычу с рыбалки, даже если в игре выключен автоматический сбор добычи.",
	["Toma las de tu ruta que tienes cerca"] = "Возьмите задания маршрута поблизости",
	["Toma las mejores de cerca que ya puedes hacer."] = "Возьмите лучшие задания поблизости, которые уже можно выполнить.",
	["Toma las mejores misiones de por aquí y después ciérralas juntas."] = "Возьмите лучшие задания здесь, а потом закройте их вместе.",
	["Toma todo el botín de una vez cuando tienes el despojo automático."] = "Забирает всю добычу сразу, когда включен автосбор добычи.",
	["Toma unas misiones cerca y Alfa las cierra contigo por el camino más corto."] = "Возьмите несколько заданий поблизости, и Alfa закроет их вместе с вами по самому короткому пути.",
	["Tomar %s"] = "Взять: %s",
	["Tomar el vuelo de tu ruta"] = "Лететь по маршруту",
	["Tomar la mejor recompensa"] = "Брать лучшую награду",
	["Tomarla"] = "Взять",
	["Tomarla, completarla o entregarla."] = "Взять, выполнить или сдать.",
	["Tomaste otra misión de su grupo: esta ya no se abre."] = "Вы взяли другое задание из этой группы: это больше не откроется.",
	["Top %d de %s"] = "Топ %d: %s",
	["Top de daño"] = "Топ урона",
	["Tope por personaje"] = "Предел на персонажа",
	["Tortura mental: daño constante y frena al enemigo."] = "Пытка разума: постоянный урон и замедление противника.",
	["Total"] = "Всего",
	["Tramo %d de %d: %s."] = "Этап %d из %d: %s.",
	["Trampas, golpes cuerpo a cuerpo de emergencia y mucha agilidad: el cazador más difícil de atrapar."] = "Ловушки, экстренные удары ближнего боя и много ловкости: охотник, которого труднее всего поймать.",
	["Tranquilo"] = "Спокойно",
	["Transformar"] = "Переработать",
	["Transformar %d"] = "Переработать %d",
	["Transmutar hierro en oro existe de verdad: el sueño de todo alquimista."] = "Превращение железа в золото действительно существует: мечта любого алхимика.",
	["Tras aceptar o entregar, cierra la ventana del PNJ si solo ofrece misiones que tu guía no hace."] = "После принятия или сдачи закрывает окно NPC, если он предлагает только задания, которых нет в гайде.",
	["Tras la Guerra de los Tres Martillos, los Martillo Salvaje se fueron a Grim Batol y luego al Interior; los Hierro Negro, a la Montaña Roca Negra."] = "После Войны Трех Молотов Громовой Молот ушли в Грим Батол, а потом во Внутренние земли; Черное Железо — в Черную гору.",
	["Tras la Segunda Guerra, mantener a los orcos en los campos de internamiento costaba una fortuna. Esos impuestos ayudaron a romper la Alianza."] = "После Второй войны содержание орков в лагерях для интернированных стоило целое состояние. Эти налоги помогли расколоть Альянс.",
	["Tras las Guerras Trol, el viejo Arathor se repartió en siete reinos: Lordaeron, Ventormenta, Gilneas, Alterac, Stromgarde, Kul Tiras y Dalaran."] = "После Тролльих войн древний Аратор распался на семь королевств: Лордерон, Штормград, Гилнеас, Альтерак, Стромгард, Кул-Тирас и Даларан.",
	["Tratado"] = "Манускрипт",
	["Tres caminos para cada objeto"] = "Три пути для каждого предмета",
	["Tres estilos y el lobo"] = "Три стиля и волк",
	["Tres pasos y listo"] = "Три шага, и готово",
	["Tres pasos: tus clics, dónde van tus marcos y una prueba."] = "Три шага: ваши щелчки, где будут рамки, и проверка.",
	["Trilineal"] = "Трилинейная",
	["Trinquete es un puerto goblin neutral: ahí se tolera a cualquiera que traiga oro, y su barco lleva hasta Bahía del Botín."] = "Кабестан — нейтральный гоблинский порт: здесь терпят любого, у кого есть золото, а его корабль ходит в Пиратскую Бухту.",
	["Trofeo"] = "Трофей",
	["Trofeos y concurso"] = "Трофеи и состязание",
	["Trols"] = "Тролли",
	["Tu Alfa ya está configurada. Revisa o cambia cualquier respuesta cuando quieras."] = "Ваш Alfa настроен. Проверяйте или меняйте любой ответ когда угодно.",
	["Tu Grito de batalla llega a todo el grupo y dura más."] = "Ваш Боевой крик достает всю группу и длится дольше.",
	["Tu abisario aguanta los golpes por ti: deja que empiece la pelea."] = "Ваш демон Бездны принимает удары за вас: пусть он начинает бой.",
	["Tu arma no tiene encantamiento: Lengua de fuego."] = "На оружии нет чар: Язык пламени.",
	["Tu arma no tiene encantamiento: Muerdepiedras."] = "На оружии нет чар: Камнедробитель.",
	["Tu arma no tiene encantamiento: Viento furioso."] = "На оружии нет чар: Неистовство ветра.",
	["Tu arma no usa munición."] = "Вашему оружию не нужны боеприпасы.",
	["Tu arma secundaria pega más."] = "Оружие в левой руке бьет сильнее.",
	["Tu armadura ya no aguanta mucho (%d%%). ¿Vamos a reparar?"] = "Доспехи долго не протянут (%d%%). Пойдем на ремонт?",
	["Tu avance arriba, el paso en una tarjeta, los dos siguientes a la vista y los botones abajo."] = "Прогресс сверху, шаг на карточке, два следующих на виду и кнопки внизу.",
	["Tu avance de misiones con tu grupo"] = "Прогресс заданий вместе с группой",
	["Tu ayuda de rotación está lista"] = "Ваш помощник ротации готов",
	["Tu banco"] = "Ваш банк",
	["Tu banco está completo"] = "Ваш банк полностью расширен",
	["Tu banco y lo que llevas"] = "Ваш банк и то, что при вас",
	["Tu banco ya tiene todas sus casillas."] = "В вашем банке уже все ячейки.",
	["Tu barra de %s está vacía"] = "Панель «%s» пуста",
	["Tu barra se llena al salir de combate."] = "Панель заполнится после боя.",
	["Tu botón de emergencia."] = "Ваша кнопка на крайний случай.",
	["Tu buff"] = "Ваш бафф",
	["Tu build"] = "Ваш билд",
	["Tu camino"] = "Ваш путь",
	["Tu camino [mapa]"] = "Твой путь",
	["Tu camino en el mapa y un aullido nuevo"] = "Твой путь на карте и новый вой",
	["Tu caña tiene cebo: %s más."] = "На удочке приманка: осталось %s.",
	["Tu clase la gana con esta cadena de misiones."] = "Ваш класс получает его за эту цепочку заданий.",
	["Tu clase no necesita recordatorio"] = "Вашему классу напоминание не нужно",
	["Tu clase no tiene habilidades de reacción. Si quieres, Alfa te avisa cuando el juego hace brillar una de tus habilidades (en Avisos, abajo)."] = "У вашего класса нет способностей-реакций. Если хотите, Alfa сообщит, когда игра подсветит одну из ваших способностей (в «Оповещениях» ниже).",
	["Tu clase todavía no tiene uno propio: Alfa usa el más parecido."] = "Для вашего класса пока нет своего: Alfa использует самый похожий.",
	["Tu cliente no deja cambiar talentos desde un addon. Usa la ventana de talentos del juego (tecla N)."] = "Ваш клиент не позволяет аддону менять таланты. Используйте игровое окно талантов (клавиша N).",
	["Tu cliente no tiene la línea de tiempo de jefes."] = "В вашем клиенте нет шкалы времени боссов.",
	["Tu cliente no trae el medidor de daño del juego."] = "В вашем клиенте нет игрового измерителя урона.",
	["Tu cliente no trae la ayuda de combate de Blizzard."] = "В вашем клиенте нет помощника в бою от Blizzard.",
	["Tu cola"] = "Ваша очередь",
	["Tu cola de cocina está vacía"] = "Очередь готовки пуста",
	["Tu color de acento"] = "Ваш акцентный цвет",
	["Tu compañera"] = "Ваша спутница",
	["Tu compañera de caza"] = "Ваш напарник на охоте",
	["Tu configuración de Alfa"] = "Ваши настройки Alfa",
	["Tu correo"] = "Ваша почта",
	["Tu curación"] = "Ваше исцеление",
	["Tu demonio"] = "Ваш демон",
	["Tu demonio es más fuerte y tú más resistente: el brujo más seguro."] = "Ваш демон сильнее, а вы крепче: самый безопасный чернокнижник.",
	["Tu destino y tus marcadores ya no desaparecen cuando hay muchos pines."] = "Ваша цель и маркеры больше не пропадают, когда меток много.",
	["Tu diario"] = "Ваш дневник",
	["Tu diario de mazmorras"] = "Ваш журнал подземелий",
	["Tu día con la manada: el plan, lo urgente y tu clase."] = "Ваш день со стаей: план, срочное и ваш класс.",
	["Tu elección"] = "Ваш выбор",
	["Tu entrenador de clase tiene algo para ti."] = "У учителя вашего класса есть что-то для вас.",
	["Tu entrenador de equitación"] = "Ваш учитель верховой езды",
	["Tu entrenador tiene algo nuevo para ti"] = "У вашего учителя есть для вас что-то новое",
	["Tu entrenador: %s (%s)."] = "Ваш учитель: %s (%s).",
	["Tu entrenador: %s."] = "Ваш учитель: %s.",
	["Tu equipo está al %d%%. Mejor repararlo antes de la siguiente pelea."] = "Прочность экипировки %d%%. Лучше починить ее до следующего боя.",
	["Tu equipo se está gastando"] = "Ваша экипировка изнашивается",
	["Tu equipo, tus bolsas y tu entrenamiento están al día."] = "Экипировка, сумки и обучение — все в порядке.",
	["Tu escudo protege mucho, pero deja al aliado con el alma debilitada un rato: no puedes ponérselo otra vez enseguida."] = "Твой щит хорошо защищает, но на время оставляет союзнику «Ослабленную душу»: сразу наложить его снова нельзя.",
	["Tu especialización"] = "Ваша специализация",
	["Tu estilo"] = "Ваш стиль",
	["Tu estilo (Alfa, Clásico WoW o Cristal), el color de acento y el aullido."] = "Ваш стиль (Alfa, Классический WoW или Стекло), акцентный цвет и вой.",
	["Tu estilo: %s"] = "Ваш стиль: %s",
	["Tu facción (%s)"] = "Ваша фракция (%s)",
	["Tu forma de viaje es un felino veloz... pero en una carrera yo no te la pondría fácil."] = "Твой походный облик — быстрая кошка... но в гонке я бы тебе поблажек не дала.",
	["Tu gente no confía en la magia arcana: recuerda bien lo que pasó con Azshara y el Pozo de la Eternidad."] = "Твой народ не доверяет тайной магии: он хорошо помнит, что случилось с Азшарой и Источником Вечности.",
	["Tu gente, los humanos, desciende de las tribus que el rey Thoradin unió en Arathor hace miles de años."] = "Твой народ, люди, происходит от племен, которые король Торадин объединил в Араторе тысячи лет назад.",
	["Tu golpe más fuerte desde el nivel 40 hasta el 60."] = "Ваш самый сильный удар с 40 по 60 уровень.",
	["Tu golpe más fuerte desde el nivel 40."] = "Ваш самый сильный удар с 40 уровня.",
	["Tu golpe más fuerte, crece con tu bloqueo."] = "Ваш самый сильный удар, растет вместе с блоком.",
	["Tu golpe más fuerte, y además reduce las curas del enemigo."] = "Ваш самый сильный удар, который к тому же снижает исцеление противника.",
	["Tu golpe más fuerte."] = "Ваш самый сильный удар.",
	["Tu golpe principal contra jefes."] = "Ваш главный удар против боссов.",
	["Tu golpe principal."] = "Ваш главный удар.",
	["Tu grupo"] = "Ваша группа",
	["Tu grupo en el mapa"] = "Ваша группа на карте",
	["Tu grupo o banda en el mapa y el minimapa, con el color de su clase."] = "Ваша группа или рейд на карте и мини-карте, цветом их класса.",
	["Tu grupo y tu banda con su vida, para curar con un clic. Se cambia fuera de combate."] = "Ваша группа и рейд со здоровьем, чтобы лечить одним щелчком. Меняется вне боя.",
	["Tu grupo, tu hermandad y tus amigos en el mapa, con Seguir y la página del clan."] = "Ваша группа, гильдия и друзья на карте — со следованием и страницей клана.",
	["Tu guía"] = "Ваш гайд",
	["Tu guía deja fuera las misiones que ya no dan experiencia, salvo que otra las necesite."] = "Гайд пропускает задания, которые больше не дают опыта, если они не нужны для другого.",
	["Tu guía está lista. Ábrela para ver tu paso."] = "Ваш гайд готов. Откройте его, чтобы увидеть свой шаг.",
	["Tu guía puede elegir y avanzar sola, o preguntarte en cada cruce."] = "Гайд может сам выбирать и идти дальше или спрашивать вас на каждой развилке.",
	["Tu guía te lleva a entrenar en %d pasos."] = "Шагов до учителя по гайду: %d.",
	["Tu guía te lleva a entrenar en este paso."] = "Гайд приведет вас к учителю на этом шаге.",
	["Tu guía te lleva a tomarla."] = "Гайд приведет вас за ним.",
	["Tu guía terminó y el camino se abre"] = "Гайд окончен, и путь разветвляется",
	["Tu guía ya no te manda a entregar misiones sin terminar: primero te lleva a lo que falta, y «Cerrar mis misiones» se pone al día sola."] = "Гайд больше не отправляет вас сдавать невыполненные задания: сначала он ведет к тому, что осталось, а «Закрыть мои задания» обновляется само.",
	["Tu hechizo principal de fuego."] = "Ваше основное заклинание огня.",
	["Tu hechizo principal."] = "Ваше основное заклинание.",
	["Tu hechizo principal: daño y frena al enemigo."] = "Ваше основное заклинание: урон и замедление противника.",
	["Tu hermandad conectada"] = "Гильдия в сети",
	["Tu hermandad y tu grupo reciben los horarios que tomas, y tú los suyos."] = "Ваша гильдия и группа получают выбранное вами время рейсов, а вы — их.",
	["Tu historial"] = "Ваша история",
	["Tu insignia de La Jauría en el borde de tu retrato, y en el de tu objetivo si la lleva."] = "Ваш значок La Jauría на краю портрета, а также у цели, если он у неё есть.",
	["Tu insignia en los retratos"] = "Ваш значок на портретах",
	["Tu instalación está mezclada o incompleta (%s). Cierra el juego, borra todas las carpetas de Alfa en Interface/AddOns e instala Alfa de nuevo con la app de CurseForge o el zip más reciente (no \"Source code\")."] = "Установка смешанная или неполная (%s). Закройте игру, удалите все папки Alfa в Interface/AddOns и установите Alfa заново через приложение CurseForge или свежий zip (не \"Source code\").",
	["Tu ira se llena al pegar y al recibir golpes: entra a la pelea con Cargar para empezar con ira."] = "Ярость копится, когда ты бьешь и когда бьют тебя: начинай бой с «Рывка», чтобы сразу иметь ярость.",
	["Tu libro no tiene hechizos para aliados"] = "В вашей книге заклинаний нет заклинаний для союзников",
	["Tu lista de sonidos"] = "Ваш список звуков",
	["Tu lista de sonidos está vacía. Agrega uno con /alfa silenciar <número>."] = "Ваш список звуков пуст. Добавьте звук командой /alfa silenciar <номер>.",
	["Tu lista de sonidos quedó vacía."] = "Ваш список звуков теперь пуст.",
	["Tu lista: síguelos con la flecha, compártelos con el grupo, cámbialos o bórralos."] = "Ваш список: следуйте за ними по стрелке, делитесь с группой, изменяйте или удаляйте.",
	["Tu loba compañera: consejos cortos, ánimo y nunca te deja atrás."] = "Ваша спутница-волчица: короткие советы, поддержка, и она никогда вас не бросит.",
	["Tu loba compañera: te da consejos y ánimo. También con /alfa lya."] = "Ваша спутница-волчица: советует и подбадривает. Также командой /alfa lya.",
	["Tu lugar resalta más: tu flecha lleva un aro y un pulso suave, y se ve bien hasta en la nieve."] = "Твоё место заметнее: у стрелки есть кольцо и мягкая пульсация, и её хорошо видно даже на снегу.",
	["Tu manada"] = "Ваша стая",
	["Tu manada en el mapa: tu grupo y quienes usan Alfa y comparten. Síguelos con la flecha, invítalos y conoce al clan."] = "Ваша стая на карте: ваша группа и те, кто пользуется Alfa и делится. Следуйте за ними по стрелке, приглашайте их и знакомьтесь с кланом.",
	["Tu manada está fuera del mapa"] = "Ваша стая вне карты",
	["Tu mapa"] = "Ваша карта",
	["Tu mapa del ratón está vacío: elige algo en una ranura primero."] = "Ваша схема мыши пуста: сначала выберите что-нибудь для ячейки.",
	["Tu marcador"] = "Ваш маркер",
	["Tu mascota"] = "Ваш питомец",
	["Tu mascota aprende habilidades de otras bestias: doma una que sepa lo que quieres y te lo enseña."] = "Твой питомец учится способностям у других зверей: приручи того, кто знает нужное, и он научит.",
	["Tu mascota hace gran parte del trabajo y aguanta los golpes: la forma más fácil y segura de subir con cazador."] = "Питомец делает большую часть работы и принимает удары: самый простой и безопасный способ прокачать охотника.",
	["Tu mascota tiene poca vida: cúrala."] = "У питомца мало здоровья: вылечите его.",
	["Tu montura de clase"] = "Ваш классовый транспорт",
	["Tu montura rápida (nivel 60)"] = "Ваш быстрый транспорт (60-й уровень)",
	["Tu munición"] = "Ваши боеприпасы",
	["Tu nivel"] = "Ваш уровень",
	["Tu nivel, reparar, comida y bebida, y la entrada de la mazmorra para ti."] = "Ваш уровень, ремонт, еда и напитки и вход в подходящее вам подземелье.",
	["Tu nota"] = "Ваша заметка",
	["Tu objetivo esquivó: Abrumar no se puede esquivar y pega fuerte. Necesita actitud de batalla."] = "Ваша цель уклонилась: от Превосходства нельзя уклониться, и оно бьет сильно. Нужна Боевая стойка.",
	["Tu oro"] = "Ваше золото",
	["Tu pantalla y tu compañera"] = "Ваш экран и ваша спутница",
	["Tu paso de ahora es el %d."] = "Ваш текущий шаг — %d.",
	["Tu paso de ahora es el %d: %s."] = "Ваш текущий шаг — %d: %s.",
	["Tu personaje"] = "Ваш персонаж",
	["Tu personaje aparece en el mapa de quienes también se dejan ver. Solo su lugar en el juego y nunca dentro de mazmorras; va por un canal oculto que alguien con otro addon podría leer."] = "Ваш персонаж появляется на карте тех, кто тоже показывает себя. Только его место в игре и никогда в подземельях; это идёт через скрытый канал, который кто-то с другим аддоном может прочитать.",
	["Tu personaje deja de decir \"No tengo suficiente maná\", \"Eso todavía no está listo\" y parecidas. El texto rojo sigue."] = "Ваш персонаж перестает говорить «Недостаточно маны», «Это еще не готово» и подобное. Красный текст остается.",
	["Tu personaje no aparece en el mapa de nadie de La Jauría. Lo cambias cuando quieras en la página de La Jauría."] = "Ваш персонаж не появляется на карте ни у кого из La Jauría. Это можно изменить в любой момент на странице La Jauría.",
	["Tu personaje todavía no recolecta. Con Minería o Herboristería, Alfa une las minas o las hierbas de tu zona en una vuelta corta. Te las enseña un instructor de profesión."] = "Ваш персонаж пока ничего не собирает. С горным делом или травничеством Alfa соединит залежи или травы вашей зоны в короткий круг. Обучиться этим профессиям можно у учителя профессии.",
	["Tu pesca"] = "Ваша рыбалка",
	["Tu pesca está al máximo"] = "Ваша рыбная ловля на максимуме",
	["Tu piedra de hogar te regresa a tu posada. Úsala para ahorrar caminata."] = "Камень возвращения переносит тебя в твою таверну. Пользуйся им, чтобы меньше ходить пешком.",
	["Tu piedra de hogar y el descanso"] = "Камень возвращения и отдых",
	["Tu pieza más gastada: %s al %d %%."] = "Самая изношенная вещь: %s, %d %%.",
	["Tu plan"] = "Ваш план",
	["Tu plan está en Talentos."] = "Ваш план — в «Талантах».",
	["Tu plan no pudo agregarlo."] = "Не удалось добавить в план.",
	["Tu plan no tiene metas"] = "В вашем плане нет целей",
	["Tu plan no tiene metas todavía"] = "В вашем плане пока нет целей",
	["Tu plan se quedó sin paso. Seguir lo vuelve a armar con las misiones que tienes ahora."] = "В вашем плане не осталось шагов. «Следовать» соберёт его заново с текущими заданиями.",
	["Tu posición en la parte de abajo del minimapa."] = "Ваше положение внизу мини-карты.",
	["Tu posición y la del cursor bajo el mapa."] = "Ваше положение и положение курсора под картой.",
	["Tu primer punto, en el nivel 10."] = "Первое очко — на 10-м уровне.",
	["Tu primer talento"] = "Ваш первый талант",
	["Tu primera guía"] = "Ваш первый гайд",
	["Tu primera montura (nivel 40)"] = "Ваш первый транспорт (40-й уровень)",
	["Tu primera sesión entra al diario cuando salgas del juego. La manada te espera: ¡a cazar!"] = "Ваш первый сеанс попадет в дневник, когда вы выйдете из игры. Стая ждет: на охоту!",
	["Tu prioridad"] = "Ваш приоритет",
	["Tu prioridad: %s"] = "Ваш приоритет: %s",
	["Tu progreso"] = "Ваш прогресс",
	["Tu propia lista de metas, en el orden que quieras: un objeto, oro, una profesión, un lugar, una misión, un nivel o una nota. Alfa las mide solas y te lleva a cada una."] = "Ваш собственный список целей в любом порядке: предмет, золото, профессия, место, задание, уровень или заметка. Alfa сам отслеживает их и ведет вас к каждой.",
	["Tu propio marco aparece aunque no estés en grupo, para curarte con un clic."] = "Ваша собственная рамка видна, даже если вы не в группе, чтобы лечить себя одним щелчком.",
	["Tu prueba"] = "Ваша проверка",
	["Tu rama: %s"] = "Ваша ветка: %s",
	["Tu rastro"] = "Ваш след",
	["Tu ratón"] = "Ваша мышь",
	["Tu registro está lleno: cierra algunas misiones primero."] = "Журнал заданий заполнен: сначала закройте некоторые задания.",
	["Tu registro está vacío"] = "Журнал заданий пуст",
	["Tu reporte, listo para pegar"] = "Ваш отчет готов к вставке",
	["Tu ritmo de los últimos 15 minutos"] = "Ваш темп за последние 15 минут",
	["Tu ritmo de los últimos 15 minutos, con el contador de XP de Alfa."] = "Ваш темп за последние 15 минут, по счетчику опыта Alfa.",
	["Tu ruta de %d tramos."] = "Ваш маршрут: этапов — %d.",
	["Tu ruta de %s en %s está lista"] = "Маршрут «%s» в %s готов",
	["Tu ruta dibujada en el mapa de Alfa hasta tu destino, que late para que lo encuentres; arriba ves a qué distancia está y cuánto falta, y un clic te muestra todo el camino."] = "Твой маршрут на карте Alfa до цели, которая пульсирует, чтобы ты её заметил; вверху видно, как далеко она и сколько осталось, а один щелчок покажет весь путь.",
	["Tu ruta está vacía"] = "Ваш маршрут пуст",
	["Tu ruta no pudo agregarlo."] = "Маршрут не смог это добавить.",
	["Tu ruta no tiene tramos todavía"] = "В вашем маршруте пока нет этапов",
	["Tu ruta pasa por ahí."] = "Ваш маршрут проходит там.",
	["Tu ruta personalizada, armada por Alfa con tus tramos."] = "Ваш собственный маршрут, составленный Alfa из ваших этапов.",
	["Tu ruta se actualizó"] = "Маршрут обновлен",
	["Tu ruta, paso a paso"] = "Ваш маршрут шаг за шагом",
	["Tu ruta, tus misiones y tus guías (/alfa rutas ayuda)."] = "Ваш маршрут, задания и гайды (/alfa rutas ayuda).",
	["Tu sesión anterior (%s): %s"] = "Ваш прошлый сеанс (%s): %s",
	["Tu sesión anterior, %s"] = "Ваш прошлый сеанс, %s",
	["Tu sesión de ahora"] = "Текущий сеанс",
	["Tu sesión de pesca ya estaba vacía: la nueva empieza con tu primer lanzamiento."] = "Ваша рыболовная сессия уже была пустой: новая начнётся с первого заброса.",
	["Tu sesión, tu diario, recordatorios y tu siguiente paso, con el color de tu clase."] = "Ваш сеанс, дневник, напоминания и следующий шаг — в цвете вашего класса.",
	["Tu siguiente mazmorra"] = "Ваше следующее подземелье",
	["Tu siguiente paso"] = "Ваш следующий шаг",
	["Tu siguiente paso, lo urgente y lo de tu clase, de un vistazo."] = "Ваш следующий шаг, срочное и все для вашего класса — с одного взгляда.",
	["Tu siguiente talento"] = "Ваш следующий талант",
	["Tu tecla del mapa (%s) lo abre."] = "Ваша клавиша карты (%s) открывает ее.",
	["Tu tecla primero te pone la mejor caña y lo que tengas con bonificación de pesca (sombrero, guantes, botas, abalorios)."] = "Сначала клавиша надевает лучшую удочку и все с бонусом к рыбной ловле (шляпу, перчатки, сапоги, аксессуары).",
	["Tu tecla y tus ajustes del juego quedan como siempre. Enciéndela para pescar con una sola tecla."] = "Ваша клавиша и игровые настройки остаются как всегда. Включите, чтобы рыбачить одной клавишей.",
	["Tu ventana de Alfa"] = "Ваше окно Alfa",
	["Tu vida baja: Rejuvenecimiento te cura poco a poco."] = "Здоровье падает: Омоложение лечит вас постепенно.",
	["Tu vida baja: Renovar te cura poco a poco."] = "Здоровье падает: Обновление лечит вас постепенно.",
	["Tu vida baja: el escudo absorbe el daño."] = "Здоровье падает: щит поглощает урон.",
	["Tu vida está a punto de acabarse: Imposición de manos te cura entero."] = "Здоровье на исходе: Возложение рук полностью исцелит вас.",
	["Tu vida está baja: cúrate rápido."] = "Мало здоровья: быстро вылечитесь.",
	["Tu vida está baja: cúrate."] = "Мало здоровья: вылечитесь.",
	["Tu vida está baja: róbasela al enemigo."] = "Мало здоровья: отнимите его у противника.",
	["Tu vida está muy baja: cúrate rápido."] = "Очень мало здоровья: быстро вылечитесь.",
	["Tu vuelo en el mapa"] = "Твой полёт на карте",
	["Tu árbol"] = "Ваше дерево",
	["Tu última sesión: %s · %s"] = "Прошлый сеанс: %s · %s",
	["Tu último escaneo fue %s. Escanea otra vez en la casa de subastas para tener precios al día."] = "Последнее сканирование: %s. Просканируйте аукцион снова, чтобы цены были актуальны.",
	["Turalyon y Alleria Brisaveloz cruzaron el Portal Oscuro tras la guerra para cerrarles el paso a los orcos, y no regresaron."] = "Туралион и Аллерия Ветрокрылая ушли после войны за Темный портал, чтобы отрезать путь оркам, и не вернулись.",
	["Tus %d puntos están donde tu build los pide. Lo que sigue es el equipo: piezas con las estadísticas que le sirven a tu build."] = "Все очки (%d) там, где их требует билд. Дальше — снаряжение: вещи с характеристиками, полезными вашему билду.",
	["Tus actitudes son de batalla, defensiva y rabiosa; elige la que pida el momento."] = "Твои стойки — боевая, оборонительная и берсерка; выбирай ту, что нужна в этот момент.",
	["Tus ajustes pasan una prueba de guardar y recargar en cada versión, para que nunca se pierdan."] = "Ваши настройки проходят проверку сохранения и перезагрузки в каждой версии, чтобы никогда не потеряться.",
	["Tus avisos"] = "Ваши оповещения",
	["Tus bolsas"] = "Ваши сумки",
	["Tus bolsas están casi llenas"] = "Ваши сумки почти полны",
	["Tus bolsas están llenas"] = "Ваши сумки полны",
	["Tus bolsas están vacías"] = "Ваши сумки пусты",
	["Tus bolsas piden auxilio (%d libres). Vende o tira lo que ya no uses."] = "Сумки просят о помощи (свободно: %d). Продай или выброси то, чем больше не пользуешься.",
	["Tus bolsas se están llenando"] = "Сумки заполняются",
	["Tus bolsas se están llenando: queda 1 casilla."] = "Сумки заполняются: осталась 1 ячейка.",
	["Tus bolsas se están llenando: quedan %d casillas."] = "Сумки заполняются: осталось ячеек: %d.",
	["Tus bolsas y tu banco en una sola ventana, y lo que lleva cada uno de tus personajes."] = "Ваши сумки и банк в одном окне, а также то, что носит каждый ваш персонаж.",
	["Tus builds importados"] = "Ваши импортированные билды",
	["Tus clics"] = "Ваши щелчки",
	["Tus clics de Curación se aplican al salir de combate."] = "Ваши щелчки «Исцеления» применятся после выхода из боя.",
	["Tus clics vuelven a los del preajuste. Lo que cambiaste a mano se pierde."] = "Ваши щелчки вернутся к набору. Ручные изменения будут потеряны.",
	["Tus comodidades están listas"] = "Ваши удобства готовы",
	["Tus compañeros de grupo y de banda en el mapa de Alfa."] = "Участники вашей группы и рейда на карте Alfa.",
	["Tus críticos de habilidades pegan todavía más."] = "Критические удары ваших способностей бьют еще сильнее.",
	["Tus críticos hacen muchísimo daño."] = "Ваши критические удары наносят огромный урон.",
	["Tus críticos hacen sangrar: matas más rápido y sufres menos."] = "Ваши критические удары вызывают кровотечение: вы убиваете быстрее и меньше страдаете.",
	["Tus críticos sangran."] = "Ваши критические удары вызывают кровотечение.",
	["Tus críticos sangran: más daño y amenaza."] = "Ваши критические удары вызывают кровотечение: больше урона и угрозы.",
	["Tus curas curan más."] = "Ваше исцеление лечит сильнее.",
	["Tus datos"] = "Ваши данные",
	["Tus demonios llegan con misiones: diablillo, abisario, súcubo y manáfago; y más adelante, el infernal y el guardia apocalíptico."] = "Твои демоны приходят через задания: бес, демон Бездны, суккуб и охотник Скверны; а позже инфернал и страж ужаса.",
	["Tus estadísticas"] = "Ваши характеристики",
	["Tus flechas de mejora no usan tu build"] = "Стрелки улучшения не учитывают ваш билд",
	["Tus flechas de mejora usan tu build"] = "Стрелки улучшения учитывают ваш билд",
	["Tus golpes alcanzan a un segundo enemigo: perfecto cuando se te juntan dos."] = "Ваши удары достают второго противника: идеально, когда на вас двое.",
	["Tus gritos llegan más lejos y duran más: ayudas a todo el grupo."] = "Ваши крики действуют дальше и дольше: вы помогаете всей группе.",
	["Tus habilidades cuestan menos ira."] = "Ваши способности стоят меньше ярости.",
	["Tus habilidades de ira te curan: menos descanso."] = "Ваши способности ярости лечат вас: меньше отдыха.",
	["Tus habilidades nuevas"] = "Ваши новые способности",
	["Tus hechizos de daño pegan más."] = "Ваши атакующие заклинания бьют сильнее.",
	["Tus hechizos de escarcha frenan: el monstruo casi nunca llega a pegarte."] = "Ваши ледяные заклинания замедляют: монстр почти никогда не успевает вас ударить.",
	["Tus hechizos fallan menos."] = "Ваши заклинания реже промахиваются.",
	["Tus hechizos hacen crítico más seguido."] = "Ваши заклинания чаще наносят критический эффект.",
	["Tus herramientas de combate"] = "Ваши боевые инструменты",
	["Tus historias"] = "Ваши истории",
	["Tus llaves junto a tus bolsas."] = "Ваши ключи рядом с сумками.",
	["Tus marcadores"] = "Ваши маркеры",
	["Tus marcadores en el mapa de Alfa y en el del juego."] = "Ваши маркеры на карте Alfa и на карте игры.",
	["Tus marcadores también en el minimapa, cuando estás cerca."] = "Ваши маркеры и на мини-карте, когда вы рядом.",
	["Tus marcos de combate volvieron a su lugar de siempre."] = "Ваши боевые окна вернулись на привычное место.",
	["Tus marcos de combate vuelven a su lugar de siempre."] = "Боевые рамки возвращаются на обычное место.",
	["Tus marcos de curación están apagados"] = "Рамки исцеления выключены",
	["Tus marcos están listos"] = "Ваши рамки готовы",
	["Tus metas en tu orden: un objeto, oro, una profesión, un lugar..."] = "Ваши цели в вашем порядке: предмет, золото, профессия, место...",
	["Tus misiones"] = "Ваши задания",
	["Tus misiones abiertas, para terminarlas y entregarlas por el camino más corto."] = "Ваши открытые задания — чтобы выполнить и сдать их по самому короткому пути.",
	["Tus números"] = "Ваши цифры",
	["Tus personajes"] = "Ваши персонажи",
	["Tus precios de la subasta son viejos: escanéala otra vez."] = "Ваши аукционные цены устарели: просканируйте аукцион снова.",
	["Tus profesiones"] = "Ваши профессии",
	["Tus próximos golpes también alcanzan a otro enemigo."] = "Следующие удары задевают еще одного противника.",
	["Tus puntos"] = "Ваши очки",
	["Tus puntos van por otro camino"] = "Ваши очки вложены иначе",
	["Tus recetas de pescado, la cola de cocina y la fogata."] = "Ваши рыбные рецепты, очередь готовки и костер.",
	["Tus recetas que dejan ganancia"] = "Ваши прибыльные рецепты",
	["Tus talentos"] = "Ваши таланты",
	["Tus tótems de tierra, fuego, agua y aire se ganan con misiones a lo largo de tu camino."] = "Тотемы земли, огня, воды и воздуха ты получаешь за задания по ходу пути.",
	["Tyrande liberó a Illidan para pelear contra la Plaga, y Maiev, su carcelera, nunca se lo perdonó."] = "Тиранда освободила Иллидана, чтобы сражаться с Плетью, и Майев, его тюремщица, так ей этого и не простила.",
	["Tótem"] = "Тотем",
	["Tótems"] = "Тотемы",
	["Tótems enemigos"] = "Вражеские тотемы",
	["Tú"] = "Вы",
	["Tú recibes los golpes y proteges al grupo. Necesitas escudo."] = "Вы принимаете удары и защищаете группу. Нужен щит.",
	["Ubicación de %s"] = "Местоположение: %s",
	["Ultra"] = "Ультра",
	["Un arma en cada mano y mucha ira: el que más daño hace en grupo."] = "По оружию в каждой руке и много ярости: больше всех урона в группе.",
	["Un arma grande de dos manos y golpes que hacen sangrar. La forma más fácil de subir."] = "Большое двуручное оружие и удары с кровотечением. Самый простой способ прокачки.",
	["Un aturdimiento cuando lo necesites."] = "Оглушение, когда оно нужно.",
	["Un aullido de lobo, del propio juego, la primera vez que abres Alfa en cada sesión."] = "Волчий вой из самой игры при первом открытии Alfa в каждом сеансе.",
	["Un aviso con sus jefes y lo que llevas vencido, con un clic a sus consejos."] = "Оповещение с боссами и тем, сколько вы победили, — в одном щелчке от советов.",
	["Un aviso corto con el lugar, su zona y el tiempo de camino."] = "Короткое оповещение с местом, его зоной и временем пути.",
	["Un aviso corto cuando se activa una habilidad que depende de lo que pasó, como Abrumar después de que el enemigo esquive."] = "Короткое оповещение, когда срабатывает способность, зависящая от происходящего, например Превосходство после уклонения противника.",
	["Un aviso cuando vences a un jefe nuevo, con un clic a su botín."] = "Оповещение, когда вы побеждаете нового босса, — в одном щелчке от его добычи.",
	["Un aviso y una franja en tus bolsas con qué vender, qué conservar y a qué comerciante ir, con un clic para marcar la chatarra."] = "Оповещение и полоса в сумках: что продать, что оставить и к какому торговцу идти, плюс один щелчок, чтобы отметить хлам.",
	["Un barrido oscuro y suave sobre los íconos mientras su recarga corre."] = "Мягкое темное затемнение на значках, пока идет восстановление.",
	["Un borde del color de la calidad: verde, azul, morado..."] = "Рамка цвета качества: зеленая, синяя, фиолетовая...",
	["Un borde verde que late sobre el botón de tu barra con la habilidad sugerida, para encontrarlo rápido."] = "Пульсирующая зеленая рамка на кнопке панели с предложенной способностью, чтобы быстро ее найти.",
	["Un brujo con dos compañeros puede invocar al resto del grupo a la entrada de una mazmorra."] = "Чернокнижник с двумя помощниками может призвать остальную группу ко входу в подземелье.",
	["Un buzón"] = "Почтовый ящик",
	["Un clic bajito cuando Lya te dice algo."] = "Тихий щелчок, когда Lya что-то говорит.",
	["Un clic y queda solo lo esencial: tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "Один щелчок — и остается только главное: вы, ваша группа, ваши маркеры и следующий шаг гайда.",
	["Un cuadro pequeño y movible con tu vida y las estadísticas que más pesan para tu clase. En combate el juego oculta algunos números: se queda el último que se pudo leer."] = "Небольшое подвижное окошко со здоровьем и самыми важными для вашего класса характеристиками. В бою игра скрывает некоторые числа: остается последнее прочитанное значение.",
	["Un enemigo"] = "Один противник",
	["Un error, una mejora o un comentario, directo al desarrollador"] = "Ошибка, идея или комментарий — прямо разработчику",
	["Un fondo del color de tu clase bajo tu nombre."] = "Фон цвета вашего класса под вашим именем.",
	["Un golpe enorme con el escudo y muchísima amenaza."] = "Огромный удар щитом и очень много угрозы.",
	["Un golpe más para gastar ira."] = "Еще один удар, чтобы тратить ярость.",
	["Un golpe nuevo y fuerte para tu barra."] = "Новый сильный удар для вашей панели.",
	["Un gran aumento de daño para monstruos difíciles; además te libra del miedo."] = "Большой прирост урона против сложных монстров; к тому же освобождает от страха.",
	["Un grano fino de cine sobre el mundo."] = "Тонкое киношное зерно поверх мира.",
	["Un grano fino, como de cine. Casi no cuesta: se mueve unas 14 veces por segundo y solo mientras se ve."] = "Тонкое зерно, как в кино. Почти не нагружает: меняется около 14 раз в секунду и только когда видно.",
	["Un hechizo de tus barras tiene un rango viejo"] = "Заклинание старого ранга на панели",
	["Un mapa de una pieza: al acercar ya no se ven pedazos pegados, y el terreno se une sin rayas ni cuadros."] = "Карта единым целым: при приближении больше не видно склеенных кусков, а местность соединяется без полос и квадратов.",
	["Un mapa impecable"] = "Безупречная карта",
	["Un marco dorado en lo que sirve para una misión (con «!» si empieza una)."] = "Золотая рамка на предметах для заданий (с «!», если предмет начинает задание).",
	["Un objeto que quieres: Alfa arma el camino para conseguirlo, con lo que haga falta antes."] = "Нужный вам предмет: Alfa строит путь к нему со всем, что нужно сначала.",
	["Un paisaje más bonito"] = "Пейзаж покрасивее",
	["Un pescadito asado no me caería nada mal."] = "Жареная рыбка мне бы сейчас не помешала.",
	["Un pescadito asado para la loba que te acompaña no estaría nada mal, ¿eh?"] = "Жареная рыбка для волчицы, которая тебя сопровождает, была бы совсем не лишней, а?",
	["Un pin pequeño con su número donde te llevan los próximos pasos."] = "Маленькая метка с номером там, куда ведут следующие шаги.",
	["Un poco de golpe crítico, de esquivar y de armadura."] = "Немного шанса критического удара, уклонения и брони.",
	["Un poco de vida de vuelta después de críticos."] = "Немного здоровья обратно после критических ударов.",
	["Un poco más de defensa."] = "Чуть больше защиты.",
	["Un poco más de ira al cargar."] = "Чуть больше ярости от Рывка.",
	["Un punto para abrir la siguiente fila y fallar un poco menos."] = "Одно очко, чтобы открыть следующий ряд и чуть реже промахиваться.",
	["Un servicio cercano, un marcador de tu mapa, donde estás ahora o la entrada de una mazmorra."] = "Ближайшая услуга, маркер на вашей карте, место, где вы сейчас, или вход в подземелье.",
	["Un signo de exclamación sobre quien te da misiones de tu nivel."] = "Восклицательный знак над теми, кто дает задания вашего уровня.",
	["Un signo de interrogación sobre quien recibe una misión ya lista."] = "Вопросительный знак над теми, кому можно сдать выполненное задание.",
	["Un solo addon con todo lo que usas al jugar: guías paso a paso con flecha y ruta, mapa, bolsas, builds, curación con clic, recolección, mazmorras, pesca y comercio. Todo con el mismo estilo."] = "Один аддон со всем, что нужно в игре: пошаговые гайды со стрелкой и маршрутом, карта, сумки, билды, исцеление по щелчку, сбор, подземелья, рыбная ловля и торговля. Все в едином стиле.",
	["Un tanque que pega fuerte: mucha amenaza para grupos que hacen mucho daño, a cambio de menos defensa extra. Para tanques con algo de experiencia."] = "Танк, который сильно бьет: много угрозы для групп с большим уроном ценой меньшей дополнительной защиты. Для танков с некоторым опытом.",
	["Un tramo más en la ruta que armas en la página Ruta: Alfa elige el camino para conseguirlo."] = "Еще один этап маршрута, который вы составляете на странице «Маршрут»: Alfa сам выберет путь, чтобы это получить.",
	["Un ícono con la habilidad que conviene ahora. Solo muestra: nunca aprieta nada por ti."] = "Значок со способностью, которую лучше применить сейчас. Только показывает: никогда ничего не нажимает за вас.",
	["Un ícono de misión en la placa de nombre de los enemigos y personajes que todavía necesitas para una misión de tu registro. En mazmorras el juego oculta esos datos y no se marcan."] = "Значок задания на индикаторе здоровья противников и персонажей, которые еще нужны для задания из журнала. В подземельях игра скрывает эти данные, и они не отмечаются.",
	["Una acción recomendada en grande y tu camino en un par de clics."] = "Одно крупное рекомендуемое действие и ваш путь в пару щелчков.",
	["Una barra con los ataques que el jefe va a hacer y cuánto falta para cada uno. Así sabes cuándo moverte o defenderte."] = "Полоса с атаками, которые собирается применить босс, и временем до каждой. Так вы знаете, когда отойти или защищаться.",
	["Una bienvenida nueva en 9 pasos con la intro del lobo: eliges el idioma de Alfa (hay 10) y cada cosa que hace sola por ti."] = "Новое приветствие из 9 шагов со вступлением с волком: вы выбираете язык Alfa (их 10) и все, что он делает за вас сам.",
	["Una cadena de texto lleva un build completo: la copias, la pasas y la pegan."] = "Одна строка текста содержит весь билд: вы ее копируете, передаете, а ее вставляют.",
	["Una cantidad de oro; se cumple cuando la llevas encima."] = "Сумма золота; цель выполнена, когда она у вас при себе.",
	["Una categoría…"] = "Категория…",
	["Una cuenta de prueba no puede compartir"] = "Пробная учетная запись не может делиться",
	["Una fila con vuelo, posada, reparar, banco, buzón y tu entrenador, a un clic."] = "Ряд с полетом, таверной, ремонтом, банком, почтой и вашим учителем — в один щелчок.",
	["Una flecha en pantalla que apunta a tu siguiente objetivo, con la distancia. Apagada: tú decides por dónde ir."] = "Стрелка на экране, указывающая на следующую цель, с расстоянием. Выключено: путь выбираете вы.",
	["Una flecha verde en cada objeto de tus bolsas que es una mejora para tu especialización."] = "Зеленая стрелка на каждом предмете в сумках, который станет улучшением для вашей специализации.",
	["Una flecha verde en el equipo que es mejor que lo que llevas puesto, según tu clase y nivel."] = "Зеленая стрелка на экипировке, которая лучше надетой, с учетом вашего класса и уровня.",
	["Una franja verde clara muestra las curas que ya vienen en camino."] = "Светло-зеленая полоска показывает уже летящее исцеление.",
	["Una guía para tu nivel y tu zona, o tu propia ruta de misiones."] = "Гайд для вашего уровня и зоны или собственный маршрут заданий.",
	["Una loba gordita como yo necesita sus tres comidas... y sus botanas."] = "Пухленькой волчице вроде меня нужны три приема пищи... и перекусы.",
	["Una loba negra que te da consejos y ánimo en el camino, sin estorbar. En memoria de una gran perrita."] = "Черная волчица, которая дает советы и подбадривает в пути, не мешая. В память об одной замечательной собачке.",
	["Una línea corta debajo del ícono, como «Golpe mortal: recarga lista». Cada una sale hasta 4 veces y luego se calla; su × la calla antes."] = "Короткая строка под значком, например «Смертельный удар: восстановлено». Каждая показывается до 4 раз, затем умолкает; кнопка × заглушает ее раньше.",
	["Una línea debajo del aviso con lo que pasó."] = "Строка под оповещением о том, что произошло.",
	["Una línea roja arriba avisa cuando un enemigo va por ese compañero."] = "Красная линия сверху предупреждает, когда противник нацелился на этого союзника.",
	["Una mano"] = "Одноручное",
	["Una meta que marcas tú (el botón de hecha del rastreador o de esta lista)."] = "Цель, которую отмечаете вы (кнопкой выполнения в трекере или в этом списке).",
	["Una misión"] = "Задание",
	["Una moneda sobre lo gris y lo que marcaste como chatarra."] = "Монетка на серых предметах и отмеченном вами хламе.",
	["Una nota con el instructor más cercano cuando tienes habilidades nuevas."] = "Заметка с ближайшим учителем, когда у вас есть новые способности.",
	["Una revisión completa de todos los módulos: más de 60 arreglos."] = "Полная проверка всех модулей: более 60 исправлений.",
	["Una revisión completa para la versión estable: más de 20 arreglos en mazmorras con grupo, combate, el mapa, Pesca, Talentos y más."] = "Полная проверка для стабильной версии: более 20 исправлений в групповых подземельях, бою, на карте, в рыбалке, талантах и не только.",
	["Una ruta es tu árbol de tramos: misiones de XP, de oro, de clase, materiales u objetos. Elige una de estas para empezar:"] = "Маршрут — это ваше дерево этапов: задания на опыт, золото или классовые, материалы или предметы. Выберите один из них, чтобы начать:",
	["Una ruta necesita al menos 3 lugares que tu habilidad alcance. Elige otro tipo o recurso abajo, o recolecta aquí: Alfa anota cada nodo que encuentras."] = "Маршруту нужно хотя бы 3 места, доступных вашему навыку. Выберите ниже другой тип или ресурс либо собирайте здесь: Alfa записывает каждый найденный узел.",
	["Una ruta por los mejores lugares para tu habilidad, con unas misiones de XP en medio."] = "Маршрут по лучшим местам для вашего навыка, с несколькими заданиями на опыт по пути.",
	["Una salchicha al día mantiene a la loba feliz. Es ciencia."] = "Одна сосиска в день — и волчица счастлива. Это наука.",
	["Una sesión termina tras 20 minutos sin lanzar o cuando empiezas otra; entonces aparece aquí con lo que sacaste y dónde."] = "Сеанс заканчивается после 20 минут без забросов или когда вы начинаете новый; тогда он появляется здесь с уловом и местом.",
	["Una sesión tranquila: nada nuevo que contar."] = "Спокойный сеанс: ничего нового.",
	["Una tecla para todo: equipo, cebo, lanzar y recoger. Con diario, guía, cocina, metas y estadísticas."] = "Одна клавиша для всего: снаряжение, приманка, заброс и подсечка. С журналом, гайдом, кулинарией, целями и статистикой.",
	["Une los %d lugares que tu habilidad alcanza en una vuelta corta, la dibuja en el mapa y la flecha te lleva de parada en parada."] = "Соединяет %d мест, доступных вашему навыку, в короткий круг, рисует его на карте, и стрелка ведет вас от остановки к остановке.",
	["Unir las capas de sombra"] = "Сглаживать стыки слоев теней",
	["Unirte al grupo de tus amigos"] = "Вступать в группы друзей",
	["Uno de los dragones verdes de la pesadilla aparece en el Bosque del Ocaso, junto a un gran árbol."] = "Один из зеленых драконов кошмара появляется в Сумеречном лесу, рядом с великим деревом.",
	["Uno menos"] = "На один меньше",
	["Uno más"] = "На один больше",
	["Unos pocos altos elfos siguen con la Alianza; viven en Quel'Danil, en las Tierras del Interior."] = "Немногие высшие эльфы остаются с Альянсом; они живут в Кель'Даниле во Внутренних землях.",
	["Usa %s"] = "Используйте %s",
	["Usa %s: tu tecla lo pone."] = "Используйте %s: клавиша его наложит.",
	["Usa Bloquear con escudo cuando un jefe pegue fuerte."] = "Используйте Блок щитом, когда босс бьет сильно.",
	["Usa Deseo de muerte al empezar contra un jefe."] = "Используйте Жажду смерти в начале боя с боссом.",
	["Usa Deseo de muerte con monstruos difíciles, no con los fáciles."] = "Используйте Жажду смерти против сложных монстров, а не против легких.",
	["Usa Golpe mortal sobre todo contra sanadores."] = "Используйте Смертельный удар прежде всего против лекарей.",
	["Usa Golpes de barrido cuando haya dos o más enemigos juntos."] = "Используйте Размашистые удары, когда рядом два противника или больше.",
	["Usa Ira rabiosa para romper miedos."] = "Используйте Ярость берсерка, чтобы снимать страх.",
	["Usa Revancha cada vez que se ilumine y Hender armadura para sumar amenaza."] = "Используйте Реванш каждый раз, когда он подсвечивается, и Раскол брони, чтобы набирать угрозу.",
	["Usa Transfusión de vida para recuperar maná a cambio de vida."] = "Используйте Жизнеотвод, чтобы получить ману в обмен на здоровье.",
	["Usa a tu demonio para frenar al monstruo mientras lanzas."] = "Используйте демона, чтобы задержать монстра, пока вы произносите заклинания.",
	["Usa el juicio y vuelve a poner tu sello enseguida."] = "Используйте Правосудие и сразу накладывайте печать снова.",
	["Usa el número de abajo en lugar del que detecta el juego."] = "Использует число ниже вместо определенного игрой.",
	["Usa el número de abajo para el blanco normal."] = "Использует число ниже для обычного белого.",
	["Usa el resaltado del propio juego sobre el botón de la habilidad sugerida."] = "Использует подсветку самой игры на кнопке предложенной способности.",
	["Usa la forma felina con un monstruo y la de oso si vienen varios."] = "Используйте облик кошки против одного монстра и облик медведя, если их несколько.",
	["Usa tu golpe principal para juntar puntos de combo y gástalos en tu remate."] = "Используйте основной удар, чтобы набирать приемы в серии, и тратьте их на завершающий прием.",
	["Usa tu varita cuando quieras ahorrar maná."] = "Используйте жезл, когда хотите сэкономить ману.",
	["Usa tus hechizos de control si se te juntan dos monstruos."] = "Используйте заклинания контроля, если на вас напали два монстра.",
	["Usa un arma lenta y fuerte: tus mejoras de arma pegan con cada golpe."] = "Используйте медленное и сильное оружие: усиления оружия срабатывают с каждым ударом.",
	["Usa una varita para rematar enemigos sin gastar maná."] = "Добивай противников жезлом, не тратя ману.",
	["Usar"] = "Использовать",
	["Usar el banco de Alfa"] = "Использовать банк Alfa",
	["Usar esta"] = "Использовать",
