	["¡Bien hecho! %s"] = "Отлично! %s",
	["¡Buen día, %s! El sol ya salió en Azeroth. ¿Vamos?"] = "Доброе утро, %s! Солнце уже встало над Азеротом. Идём?",
	["¡Buenas noches, %s! Las lobas cazamos mejor de noche."] = "Добрый вечер, %s! Мы, волчицы, лучше всего охотимся ночью.",
	["¡Buenas tardes, %s! Buena hora para unas misiones."] = "Добрый день, %s! Отличное время для заданий.",
	["¡Buenas, %s! Paso a paso se llega lejos."] = "Привет, %s! Шаг за шагом можно уйти далеко.",
	["¡Buenos días, %s! Me estiro, bostezo y estoy lista."] = "Доброе утро, %s! Потянусь, зевну — и я готова.",
	["¡Completaste %s!"] = "Пройдено: %s!",
	["¡Contraataque!"] = "Контратака!",
	["¡De vuelta con la manada!"] = "Снова со стаей!",
	["¡De vuelta en la manada, %s!"] = "Снова в стае, %s!",
	["¡Ejecutar!"] = "Казнь!",
	["¡En Thelsamar venden morcilla! La morcilla de Thelsamar es casi una salchicha... ¿me compras una?"] = "В Телсамаре продают кровяную колбасу! Телсамарская кровяная колбаса — почти сосиска... купишь мне одну?",
	["¡Es ahora! Hasta las %s"] = "Уже идет! До %s",
	["¡Hola!"] = "Привет!",
	["¡Hola! Soy Lya, la loba de confianza del Alfa. Cuido a la manada y voy contigo en el camino."] = "Привет! Я Lya, верная волчица Альфы. Я берегу стаю и иду с тобой в пути.",
	["¡Hola, %s!"] = "Привет, %s!",
	["¡Hola, %s! Hoy huele a buena cacería."] = "Привет, %s! Сегодня пахнет хорошей охотой.",
	["¡Hola, %s! La tarde pinta tranquila. ¿Qué cazamos hoy?"] = "Привет, %s! День обещает быть спокойным. На кого охотимся сегодня?",
	["¡Hola, %s! Noche de luna: perfecta para la manada."] = "Привет, %s! Лунная ночь — то, что нужно стае.",
	["¡Listo! %s precios guardados."] = "Готово! Сохранено цен: %s.",
	["¡Listo! Alfa ya es tuyo"] = "Готово! Alfa теперь ваш",
	["¡Lo tienes! %s ×%d"] = "Есть! %s ×%d",
	["¡Martillo de cólera!"] = "Молот гнева!",
	["¡Mordedura de mangosta!"] = "Укус мангуста!",
	["¡Nivel %d! Date un momento para presumirlo, te lo ganaste."] = "Уровень %d! Найди минутку похвастаться — есть чем!",
	["¡Nivel %d! Paso firme y colmillo afilado."] = "Уровень %d! Твердый шаг и острые клыки.",
	["¡Nivel %d! Tu esfuerzo se nota. Sigue así."] = "Уровень %d! Твои старания видны. Так держать.",
	["¡Nivel %d! ¡Auuu! Así se sube en manada."] = "Уровень %d! Ауууу! Вот так растет стая.",
	["¡Nivel %d, bien hecho! Revisa si tu entrenador tiene algo nuevo."] = "Уровень %d, отлично! Загляни, нет ли у учителя чего-то нового.",
	["¡Nivel 10! Ya tienes talentos: elígelos con calma, Talentos te ayuda."] = "Уровень 10! Теперь у тебя есть таланты: выбирай спокойно, «Таланты» помогут.",
	["¡Nivel 20! Ya puedes con mazmorras de verdad. ¿Armamos grupo?"] = "Уровень 20! Теперь тебе по силам настоящие подземелья. Соберем группу?",
	["¡Nivel 30! Ya vas a la mitad del camino. ¡Qué orgullo de manada!"] = "Уровень 30! Полпути позади. Стая гордится тобой!",
	["¡Nivel 40! Ya puedes aprender a montar. ¡Tu primera montura te espera!"] = "Уровень 40! Теперь можно научиться верховой езде. Твой первый транспорт ждет!",
	["¡Nivel 50! Ya se huele la cima. Junta oro para lo que viene."] = "Уровень 50! Вершина уже чувствуется. Копи золото на то, что впереди.",
	["¡Nivel 60! ¡Lo lograste, alfa! Ahora toca cazar en grande."] = "Уровень 60! У тебя получилось, альфа! Теперь время большой охоты.",
	["¡Plan terminado!"] = "План выполнен!",
	["¡Primera vez! Nuevo en tu diario"] = "Впервые! Новая запись в журнале",
	["¡Qué buena racha traes! Sigue así."] = "Какая удачная серия! Так держать.",
	["¡Qué bueno tenerte de vuelta, %s! Aquí sigo, cuidándote la espalda."] = "Как хорошо, что ты снова здесь, %s! Я все еще рядом и прикрываю тебе спину.",
	["¡Qué gusto verte de vuelta! Esto es lo que trae esta versión para ti y tu manada."] = "Рады снова вас видеть! Вот что эта версия принесла вам и вашей стае.",
	["¡Qué gusto verte, %s! La manada ya te esperaba."] = "Рада тебя видеть, %s! Стая уже ждала тебя.",
	["¡Repara tu equipo!"] = "Почините экипировку!",
	["¡Revancha!"] = "Реванш!",
	["¡Subiste a nivel %d! Cada nivel te hace más fuerte."] = "Новый уровень — %d! Каждый уровень делает тебя сильнее.",
	["¡Te extrañé, %s! Corrí hasta aquí para verte."] = "Я скучала по тебе, %s! Бежала со всех лап, чтобы тебя увидеть.",
	["¡Te extrañé, %s! Tu ruta sigue donde la dejaste."] = "Я скучала, %s! Твой маршрут там же, где и был.",
	["¡Terminaste %s!"] = "Готово: %s!",
	["¡Terminaste esta guía! Elige la siguiente y sigue subiendo con la manada."] = "Вы прошли этот гайд! Выберите следующий и продолжайте расти вместе со стаей.",
	["¡Terminaste tu guía!"] = "Вы прошли гайд!",
	["¡Tú!"] = "Вы!",
	["¡Volviste, %s! Estira las patas y vámonos."] = "С возвращением, %s! Разомни лапы — и в путь.",
	["¡Ya eres nivel %d! La manada aúlla por ti."] = "Уже уровень %d! Стая воет в твою честь.",
	["¡Ya llegaste, %s! Te extrañé. ¿A dónde vamos hoy?"] = "Наконец-то ты здесь, %s! Я скучала. Куда отправимся сегодня?",
	["¡Ya terminaste %d misiones! Vamos a cobrar la recompensa."] = "Выполнено заданий: %d! Пойдем за наградой.",
	["«%s» tiene su historia. ¿Te la cuento?"] = "У «%s» есть своя история. Рассказать?",
	["«%s» ya quedó. Su final vale la pena, ¿te lo cuento?"] = "«%s» позади. Ее концовка того стоит — рассказать?",
	["«Alejar más la cámara» de Comodidades está encendido y manda sobre este valor al entrar."] = "Включено «Отдалять камеру сильнее» из «Удобств», и при входе оно перекрывает это значение.",
	["«Buscar cerca» en la página Hoy"] = "«Найти рядом» на странице «Сегодня»",
	["«Buscar cerca» te lleva con flecha a lo que necesitas, y «Mis planes» arma tus propias metas, que se marcan solas."] = "«Найти рядом» ведет вас стрелкой к нужному, а «Мои планы» составляют ваши собственные цели, которые отмечаются сами.",
	["«Cerrar mis misiones» está al día"] = "«Закрыть мои задания»: все актуально",
	["«Igual que Alfa» sigue el estilo de Ajustes > Apariencia y cambia con él."] = "«Как в Alfa» следует стилю из Настройки > Внешний вид и меняется вместе с ним.",
	["«Invitar al clan» en el clic derecho"] = "«Пригласить в гильдию или сообщество» по правому клику",
	["«Prepárame» recoge solo las que ya puedes tomar y te lleva a la entrada."] = "«Подготовь меня» берет только те, что уже можно взять, и ведет ко входу.",
	["«Seguir» en La Jauría ya no se suelta cuando tu guía cambia de paso ni cuando vas por tu cuerpo: al terminar, la flecha vuelve con quien sigues."] = "«Следовать» в La Jauría больше не сбрасывается, когда гид переходит к другому шагу или вы бежите к своему телу: потом стрелка снова указывает на того, за кем вы следуете.",
	["«Siempre» sirve si un amigo encantador te ayuda. Las tablas de desencantar son estimadas."] = "«Всегда» подходит, если вам помогает друг-чародей. Таблицы распыления примерные.",
	["«Ver el siguiente» te deja mirar el paso que viene y lo dice claro; y un solo contador de pasos hechos."] = "«Показать следующий» позволяет посмотреть следующий шаг и ясно об этом говорит; а счетчик выполненных шагов теперь один.",
	["¿Abandonar %d misiones?"] = "Отказаться от заданий: %d?",
	["¿Abandonar %d misión?"] = "Отказаться от %d задания?",
	["¿Algo raro?"] = "Что-то не так?",
	["¿Aplicar estos talentos?"] = "Применить эти таланты?",
	["¿Borrar el diario?"] = "Очистить дневник?",
	["¿Borrar el historial?"] = "Удалить историю?",
	["¿Borrar esta ruta?"] = "Удалить этот маршрут?",
	["¿Borrar este build?"] = "Удалить этот билд?",
	["¿Borrar este plan?"] = "Удалить этот план?",
	["¿Borrar lo que descubriste?"] = "Удалить ваши находки?",
	["¿Borrar los precios?"] = "Удалить цены?",
	["¿Borrar todo tu progreso?"] = "Удалить весь ваш прогресс?",
	["¿Borrar todo tu registro de pesca?"] = "Удалить весь журнал рыбалки?",
	["¿Borrar todos tus marcadores?"] = "Удалить все ваши маркеры?",
	["¿Cuánto decide Alfa por ti en el camino?"] = "Сколько Alfa решает за вас в пути?",
	["¿Cómo quieres hacerlo?"] = "Как вы хотите это сделать?",
	["¿Cómo quieres que se vea Alfa?"] = "Как должен выглядеть Alfa?",
	["¿Empezar el medidor de cero?"] = "Обнулить измеритель?",
	["¿Empezar una sesión nueva?"] = "Начать новый сеанс?",
	["¿En qué idioma quieres Alfa?"] = "На каком языке вам нужен Alfa?",
	["¿Eso que huele es pan de la posada? Mi nariz nunca se equivoca."] = "Это пахнет хлебом из таверны? Мой нос никогда не ошибается.",
	["¿La haces con tu manada o la saltas?"] = "Выполните его со стаей или пропустите?",
	["¿La vuelves a tomar o la sacas de la ruta?"] = "Взять его снова или убрать из маршрута?",
	["¿Olvidar a este personaje?"] = "Забыть этого персонажа?",
	["¿Olvidar tu progreso?"] = "Забыть ваш прогресс?",
	["¿Otra cosa hoy?"] = "Что-то другое сегодня?",
	["¿Otra vez?"] = "Еще раз?",
	["¿Oíste eso? Nada… solo el viento. Sigamos."] = "Слышал? Ничего… просто ветер. Идём дальше.",
	["¿Paramos a comer? Mi panza ya está aullando."] = "Может, остановимся поесть? Мой живот уже воет.",
	["¿Por dónde sigues?"] = "Куда дальше?",
	["¿Quieres cazar con nosotros? Pulsa el botón: Alfa busca a un oficial conectado y te abre un susurro con tu mensaje listo para que lo envíes con Intro."] = "Хотите охотиться с нами? Нажмите кнопку: Alfa найдет офицера в сети и откроет шепот с готовым сообщением — останется нажать Enter.",
	["¿Quieres que la manada te vea en el mapa del juego?"] = "Хотите, чтобы стая видела вас на карте игры?",
	["¿Qué buscas?"] = "Что вы ищете?",
	["¿Qué es Alfa?"] = "Что такое Alfa?",
	["¿Qué hace Alfa con comerciantes y viajes?"] = "Что Alfa делает с торговцами и путешествиями?",
	["¿Qué hace Alfa con tus misiones?"] = "Что Alfa делает с вашими заданиями?",
	["¿Qué hacemos hoy?"] = "Чем займемся сегодня?",
	["¿Qué hago con mis objetos?"] = "Что делать с моими предметами?",
	["¿Qué nos quieres contar?"] = "Что вы хотите нам рассказать?",
	["¿Qué quieres hacer hoy?"] = "Чем хотите заняться сегодня?",
	["¿Qué quieres hacer?"] = "Чем хотите заняться?",
	["¿Qué responde Alfa por ti a otros jugadores?"] = "Что Alfa отвечает за вас другим игрокам?",
	["¿Qué sigue?"] = "Что дальше?",
	["¿Reiniciar los gráficos?"] = "Перезапустить графику?",
	["¿Sabías que las lobas tenemos el mejor oído de la manada? Bueno, eso digo yo."] = "А ты знаешь, что у волчиц лучший слух в стае? Ну, это я так говорю.",
	["¿Sabías que…? Alfa junta tus misiones listas en una sola ruta corta."] = "Знаешь ли ты? Alfa собирает твои готовые задания в один короткий маршрут.",
	["¿Sabías que…? Alfa tiene tres estilos: Alfa, Clásico WoW y Cristal. Y yo me pongo el que elijas."] = "Знаешь ли ты? У Alfa три стиля: Alfa, Классический WoW и Стекло. И я надеваю тот, что выберешь ты.",
	["¿Sabías que…? Alt+clic en un objeto lo abre en la Enciclopedia."] = "Знаешь ли ты? Alt+щелчок по предмету открывает его в «Энциклопедии».",
	["¿Sabías que…? Buscar cerca te lleva al herrero, al banco o al vuelo más cercano."] = "Знаешь ли ты? «Найти рядом» ведет к ближайшему кузнецу, банку или распорядителю полетов.",
	["¿Sabías que…? Comercio te dice si algo conviene venderlo, subastarlo o convertirlo."] = "Знаешь ли ты? «Торговля» подскажет, что выгоднее: продать торговцу, выставить на аукцион или переработать.",
	["¿Sabías que…? Con /alfa reportar le cuentas a toxic3000 de un error o una idea."] = "Знаешь ли ты? Командой /alfa reportar можно рассказать toxic3000 об ошибке или идее.",
	["¿Sabías que…? Con Pesca lanzas y recoges con una sola tecla."] = "Знаешь ли ты? С «Рыбной ловлей» ты забрасываешь и вытаскиваешь одной клавишей.",
	["¿Sabías que…? Con clic derecho sobre mí puedes silenciarme una hora o pedirme menos consejos."] = "Знаешь ли ты? Правым щелчком по мне можно заставить меня помолчать час или попросить меньше советов.",
	["¿Sabías que…? Con el botón del minimapa ocultas todo Alfa y lo vuelves a traer."] = "Знаешь ли ты? Кнопка у мини-карты скрывает весь Alfa и возвращает его.",
	["¿Sabías que…? El mapa de Alfa muestra el terreno, tus marcadores y lo que hay cerca."] = "Знаешь ли ты? Карта Alfa показывает рельеф, твои маркеры и то, что рядом.",
	["¿Sabías que…? En Bolsas ves tus bolsas, tu banco y lo de todos tus personajes."] = "Знаешь ли ты? В «Сумках» видны твои сумки, банк и вещи всех твоих персонажей.",
	["¿Sabías que…? En La Jauría ves a tu grupo y a la manada que usa Alfa."] = "Знаешь ли ты? В La Jauría видна твоя группа и стая, которая пользуется Alfa.",
	["¿Sabías que…? En Mis planes armas tu propia lista de metas y la flecha te guía."] = "Знаешь ли ты? В «Моих планах» ты составляешь свой список целей, и стрелка ведет тебя.",
	["¿Sabías que…? En Talentos ves qué talento poner ahora y por qué."] = "Знаешь ли ты? В «Талантах» видно, какой талант взять сейчас и почему.",
	["¿Sabías que…? La Enciclopedia te dice dónde sale cada objeto, PNJ o misión."] = "Знаешь ли ты? «Энциклопедия» подскажет, где найти любой предмет, NPC или задание.",
	["¿Sabías que…? La página Hoy te dice qué hacer ahora y lo urgente de tu personaje."] = "Знаешь ли ты? Страница «Сегодня» подскажет, что делать сейчас и что срочно для твоего персонажа.",
	["¿Sabías que…? Mazmorras te dice cuál te toca y cómo prepararte."] = "Знаешь ли ты? «Подземелья» подскажут, какое подземелье твое и как подготовиться.",
	["¿Sabías que…? Recolección te marca en el mapa minerales, hierbas y bancos de peces."] = "Знаешь ли ты? «Сбор» отмечает на карте руду, травы и косяки рыбы.",
	["¿Te conté que mi comida favorita son las salchichas? Ninguna otra cosa se le acerca."] = "Я говорила, что моя любимая еда — сосиски? Ничто с ними не сравнится.",
	["¿Una carrerita hasta allá? Yo gano."] = "Наперегонки вон до туда? Я выиграю.",
	["¿Usar tu hechizo nuevo?"] = "Использовать новое заклинание?",
	["¿Usar «%s»?"] = "Использовать «%s»?",
	["¿Vender, subastar o transformar? (escanear, precio <objeto>)"] = "Продать, на аукцион или переработать? (escanear — сканировать, precio <предмет> — цена)",
	["¿Vender, subastar o transformar? Lo que más oro te deja con cada objeto."] = "Продать, на аукцион или переработать? Что принесет больше всего золота с каждого предмета.",
	["¿Volver a lo de antes?"] = "Вернуть как было?",
	["¿Ya exploraste todo %s? Siempre queda un rincón por ver."] = "Ты уже весь %s исследовал? Всегда остаётся уголок, который стоит увидеть.",
	["¿Ya hiciste esta mazmorra?"] = "Вы уже проходили это подземелье?",
	["¿qué quieres hacer?"] = "чем хотите заняться?",
	["Ábrela con su botón en la barra de menú del juego: la fila de botones pequeños de abajo a la derecha."] = "Откройте его кнопкой на панели меню игры — это ряд маленьких кнопок справа внизу.",
	["Ábrela con tu tecla de talentos (%s) o desde el menú del juego."] = "Откройте его клавишей талантов (%s) или через меню игры.",
	["Ábrela con tu tecla de talentos o desde el menú del juego."] = "Откройте его клавишей талантов или через меню игры.",
	["Ábrela con tu tecla del Legado (%s) o con su botón en la barra de menú del juego."] = "Откройте его клавишей «Наследия» (%s) или кнопкой на панели меню игры.",
	["Ábrelo con /alfa o con el lobo del minimapa. Para cambiar algo de esto: /alfa bienvenida."] = "Откройте его командой /alfa или волком на мини-карте. Чтобы что-то изменить: /alfa bienvenida.",
	["Ámbar"] = "Янтарный",
